15	#include <graph/utils/type_utils.h>
16	#include <register/op_impl_registry.h>
17	#include "err/ops_err.h"
18	
19	
20	using namespace ge;
21	
22	namespace ops {
23	constexpr uint32_t QUERY_INDEX = 0;
24	constexpr uint32_t KEY_INDEX = 1;
25	constexpr uint32_t ACTUAL_SEQ_K_INDEX = 4;
26	constexpr uint32_t ATTR_QUERY_LAYOUT_INDEX = 0;
27	constexpr uint32_t ATTR_KEY_LAYOUT_INDEX = 1;
28	constexpr uint32_t ATTR_SPARSE_COUNT_INDEX = 2;
29	constexpr uint32_t ATTR_RETURN_VALUE_INDEX = 6;
30	constexpr uint32_t ATTR_SPARSE_BLOCK_SIZE_INDEX = 7;
31	
32	static ge::graphStatus InferShapeLightningIndexerEnhance(gert::InferShapeContext *context)
33	{
34	    OPS_ERR_IF(context == nullptr, OP_LOGE("LightningIndexerEnhance", "InferShapeContext is nullptr!"),
35	               return ge::GRAPH_FAILED);
36	    const gert::Shape *queryShape = context->GetInputShape(QUERY_INDEX);
37	    OP_CHECK_NULL_WITH_CONTEXT(context, queryShape);
38	    const gert::Shape *keyShape = context->GetInputShape(KEY_INDEX);
39	    OP_CHECK_NULL_WITH_CONTEXT(context, keyShape);
40	    gert::Shape *sparseIndicesShape = context->GetOutputShape(0);
41	    OP_CHECK_NULL_WITH_CONTEXT(context, sparseIndicesShape);
42	    gert::Shape *sparseValuesShape = context->GetOutputShape(1);
43	    OP_CHECK_NULL_WITH_CONTEXT(context, sparseValuesShape);
44	
45	    auto attrs = context->GetAttrs();
46	    OP_CHECK_NULL_WITH_CONTEXT(context, attrs);
47	    const char *inputLayoutQueryPtr = attrs->GetAttrPointer<char>(ATTR_QUERY_LAYOUT_INDEX);
48	    OP_CHECK_NULL_WITH_CONTEXT(context, inputLayoutQueryPtr);
49	    const char *inputLayoutKeyPtr = attrs->GetAttrPointer<char>(ATTR_KEY_LAYOUT_INDEX);
50	    OP_CHECK_NULL_WITH_CONTEXT(context, inputLayoutKeyPtr);
51	    const int64_t *sparse_count = attrs->GetInt(ATTR_SPARSE_COUNT_INDEX);
52	    OP_CHECK_NULL_WITH_CONTEXT(context, sparse_count);
53	    const int64_t *sparse_block_size = attrs->GetInt(ATTR_SPARSE_BLOCK_SIZE_INDEX);
54	    OP_CHECK_NULL_WITH_CONTEXT(context, sparse_block_size);
55	    const int64_t selected_count = (*sparse_count + *sparse_block_size - 1) / *sparse_block_size;
56	    std::string inputLayoutQueryPtrStr = std::string(inputLayoutQueryPtr);
57	    std::string inputLayoutKeyPtrStr = std::string(inputLayoutKeyPtr);
58	    OPS_ERR_IF(
59	        inputLayoutQueryPtrStr != "TND" && inputLayoutQueryPtrStr != "BSND",
60	        OP_LOGE(context, "The attr layout_query should be TND or BSND, but got %s.", inputLayoutQueryPtrStr.c_str()),
61	        return ge::GRAPH_FAILED);
62	
63	    sparseIndicesShape->SetDimNum(queryShape->GetDimNum());
64	    sparseValuesShape->SetDimNum(queryShape->GetDimNum());
65	
66	    if (inputLayoutQueryPtrStr == "BSND") {
67	        OPS_ERR_IF(
68	            queryShape->GetDimNum() != 4,
69	            OP_LOGE(context, "Layout BSND, queryDims (%zu) must be 4!", queryShape->GetDimNum()),
70	            return ge::GRAPH_FAILED);
71	        sparseIndicesShape->SetDim(0, queryShape->GetDim(0)); // 0:Dim B
72	        sparseIndicesShape->SetDim(1, queryShape->GetDim(1)); // 1:Dim S
73	        sparseIndicesShape->SetDim(2, keyShape->GetDim(2));   // 2:Dim N
74	        sparseIndicesShape->SetDim(3, selected_count);        // 3:Dim K
75	
76	        sparseValuesShape->SetDim(0, queryShape->GetDim(0)); // 0:Dim B
77	        sparseValuesShape->SetDim(1, queryShape->GetDim(1)); // 1:Dim S
78	        sparseValuesShape->SetDim(2, keyShape->GetDim(2));   // 2:Dim N
79	        sparseValuesShape->SetDim(3, selected_count);        // 3:Dim K
80	    } else {
81	        OPS_ERR_IF(
82	            queryShape->GetDimNum() != 3,
83	            OP_LOGE(context, "Layout TND, queryDims (%zu) must be 3!", queryShape->GetDimNum()),
84	            return ge::GRAPH_FAILED);
85	        sparseIndicesShape->SetDim(0, queryShape->GetDim(0));                      // 0:Dim T
86	        int32_t nDimIndex = (inputLayoutKeyPtrStr == "PA_BSND") ? 2 : 1; // 2:Key Dim N
87	        sparseIndicesShape->SetDim(1, keyShape->GetDim(nDimIndex));                // 1:Dim N
88	        sparseIndicesShape->SetDim(2, selected_count);                             // 2:Dim K
89	
90	        sparseValuesShape->SetDim(0, queryShape->GetDim(0));                      // 0:Dim T
91	        sparseValuesShape->SetDim(1, keyShape->GetDim(nDimIndex));                // 1:Dim N
92	        sparseValuesShape->SetDim(2, selected_count);                             // 2:Dim K
93	    }
94	    OP_LOGD(context->GetNodeName(), "LightningIndexerEnhance InferShape end.");
95	
96	    return ge::GRAPH_SUCCESS;
97	}
