102	               return ge::GRAPH_FAILED);
103	    OP_LOGD(context->GetNodeName(), "Enter LightningIndexerEnhance InferDataType impl.");
104	    // default set q's dtype as fia's output type
105	    ge::DataType sparseIndicesType = context->GetInputDataType(ge::DT_INT32);
106	    ge::DataType queryType = context->GetInputDataType(QUERY_INDEX);
107	    // attention_out, outidx:0
108	    context->SetOutputDataType(0, sparseIndicesType);
109	    context->SetOutputDataType(1, queryType);
110	    OP_LOGD(context->GetNodeName(), "LightningIndexerEnhance InferDataType end.");
111	    return GRAPH_SUCCESS;
112	}
