/*!
 * \file lightning_indexer_enhance_proto.cpp
 * \brief
 */
#include <graph/utils/type_utils.h>
#include <register/op_impl_registry.h>
#include "err/ops_err.h"


using namespace ge;

namespace ops {
constexpr uint32_t QUERY_INDEX = 0;
constexpr uint32_t KEY_INDEX = 1;
constexpr uint32_t ACTUAL_SEQ_K_INDEX = 4;
constexpr uint32_t ATTR_QUERY_LAYOUT_INDEX = 0;
constexpr uint32_t ATTR_KEY_LAYOUT_INDEX = 1;
constexpr uint32_t ATTR_SPARSE_COUNT_INDEX = 2;
constexpr uint32_t ATTR_RETURN_VALUE_INDEX = 6;
constexpr uint32_t ATTR_SPARSE_BLOCK_SIZE_INDEX = 7;

static ge::graphStatus InferShapeLightningIndexerEnhance(gert::InferShapeContext *context)
{
    OPS_ERR_IF(context == nullptr, OP_LOGE("LightningIndexerEnhance", "InferShapeContext is nullptr!"),
               return ge::GRAPH_FAILED);
    const gert::Shape *queryShape = context->GetInputShape(QUERY_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context, queryShape);
    const gert::Shape *keyShape = context->GetInputShape(KEY_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context, keyShape);
    gert::Shape *sparseIndicesShape = context->GetOutputShape(0);
    OP_CHECK_NULL_WITH_CONTEXT(context, sparseIndicesShape);
    gert::Shape *sparseValuesShape = context->GetOutputShape(1);
    OP_CHECK_NULL_WITH_CONTEXT(context, sparseValuesShape);

    auto attrs = context->GetAttrs();
    OP_CHECK_NULL_WITH_CONTEXT(context, attrs);
    const char *inputLayoutQueryPtr = attrs->GetAttrPointer<char>(ATTR_QUERY_LAYOUT_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context, inputLayoutQueryPtr);
    const char *inputLayoutKeyPtr = attrs->GetAttrPointer<char>(ATTR_KEY_LAYOUT_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context, inputLayoutKeyPtr);
    const int64_t *sparse_count = attrs->GetInt(ATTR_SPARSE_COUNT_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context, sparse_count);
    const int64_t *sparse_block_size = attrs->GetInt(ATTR_SPARSE_BLOCK_SIZE_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context, sparse_block_size);
    const int64_t selected_count = (*sparse_count + *sparse_block_size - 1) / *sparse_block_size;
    std::string inputLayoutQueryPtrStr = std::string(inputLayoutQueryPtr);
    std::string inputLayoutKeyPtrStr = std::string(inputLayoutKeyPtr);
    OPS_ERR_IF(
        inputLayoutQueryPtrStr != "TND" && inputLayoutQueryPtrStr != "BSND",
        OP_LOGE(context, "The attr layout_query should be TND or BSND, but got %s.", inputLayoutQueryPtrStr.c_str()),
        return ge::GRAPH_FAILED);

    sparseIndicesShape->SetDimNum(queryShape->GetDimNum());
    sparseValuesShape->SetDimNum(queryShape->GetDimNum());

    if (inputLayoutQueryPtrStr == "BSND") {
        OPS_ERR_IF(
            queryShape->GetDimNum() != 4,
            OP_LOGE(context, "Layout BSND, queryDims (%zu) must be 4!", queryShape->GetDimNum()),
            return ge::GRAPH_FAILED);
        sparseIndicesShape->SetDim(0, queryShape->GetDim(0)); // 0:Dim B
        sparseIndicesShape->SetDim(1, queryShape->GetDim(1)); // 1:Dim S
        sparseIndicesShape->SetDim(2, keyShape->GetDim(2));   // 2:Dim N
        sparseIndicesShape->SetDim(3, selected_count);        // 3:Dim K

        sparseValuesShape->SetDim(0, queryShape->GetDim(0)); // 0:Dim B
        sparseValuesShape->SetDim(1, queryShape->GetDim(1)); // 1:Dim S
        sparseValuesShape->SetDim(2, keyShape->GetDim(2));   // 2:Dim N
        sparseValuesShape->SetDim(3, selected_count);        // 3:Dim K
    } else {
        OPS_ERR_IF(
            queryShape->GetDimNum() != 3,
            OP_LOGE(context, "Layout TND, queryDims (%zu) must be 3!", queryShape->GetDimNum()),
            return ge::GRAPH_FAILED);
        sparseIndicesShape->SetDim(0, queryShape->GetDim(0));                      // 0:Dim T
        int32_t nDimIndex = (inputLayoutKeyPtrStr == "PA_BSND") ? 2 : 1; // 2:Key Dim N
        sparseIndicesShape->SetDim(1, keyShape->GetDim(nDimIndex));                // 1:Dim N
        sparseIndicesShape->SetDim(2, selected_count);                             // 2:Dim K

        sparseValuesShape->SetDim(0, queryShape->GetDim(0));                      // 0:Dim T
        sparseValuesShape->SetDim(1, keyShape->GetDim(nDimIndex));                // 1:Dim N
        sparseValuesShape->SetDim(2, selected_count);                             // 2:Dim K
    }
    OP_LOGD(context->GetNodeName(), "LightningIndexerEnhance InferShape end.");

    return ge::GRAPH_SUCCESS;
}

static ge::graphStatus InferDataTypeLightningIndexerEnhance(gert::InferDataTypeContext *context)
{
    OP_CHECK_IF(context == nullptr, OP_LOGE("LightningIndexerEnhance", "InferDataTypeContext is nullptr!"),
               return ge::GRAPH_FAILED);
    OP_LOGD(context->GetNodeName(), "Enter LightningIndexerEnhance InferDataType impl.");
    // default set q's dtype as fia's output type
    ge::DataType sparseIndicesType = context->GetInputDataType(ge::DT_INT32);
    ge::DataType queryType = context->GetInputDataType(QUERY_INDEX);
    // attention_out, outidx:0
    context->SetOutputDataType(0, sparseIndicesType);
    context->SetOutputDataType(1, queryType);
    OP_LOGD(context->GetNodeName(), "LightningIndexerEnhance InferDataType end.");
    return GRAPH_SUCCESS;
}

IMPL_OP_INFERSHAPE(LightningIndexerEnhance)
    .InferShape(InferShapeLightningIndexerEnhance)
    .InferDataType(InferDataTypeLightningIndexerEnhance);
} // namespace ops

