/*!
 * \file lightning_indexer_enhance.cpp
 * \brief
 */

#include "kernel_operator.h"
#include "lib/matmul_intf.h"
#include "lightning_indexer_enhance_template_tiling_key.h"
#include "lightning_indexer_enhance_kernel.h"

using namespace LIKernel;

#define INVOKE_LI_NO_KFC_OP_IMPL(templateClass, ...)                                                                   \
    do {                                                                                                               \
        templateClass<LIType<__VA_ARGS__>> op;                                                                         \
        LI_COPY_TILING_DATA(LITilingData, tiling);                                                                     \
        op.Init(query,                                                                                                 \
                key,                                                                                                   \
                weights,                                                                                               \
                actualSeqLengthsQ,                                                                                     \
                actualSeqLengths,                                                                                      \
                blocktable,                                                                                            \
                sparseIndices,                                                                                         \
                sparseValues,                                                                                          \
                user,                                                                                                  \
                tiling_data,                                                                                           \
                &tPipe);                                                                                               \
        op.Process();                                                                                                  \
    } while (0)

#define LI_COPY_TILING_DATA(tilingDataStruct, tiling)                                                                  \
    GET_TILING_DATA_WITH_STRUCT(tilingDataStruct, tiling_data_in, tiling);                                             \
    const tilingDataStruct *__restrict tiling_data = &tiling_data_in;

template <int DT_Q, int DT_K, int DT_OUT, int PAGE_ATTENTION, int LAYOUT_T, int K_LAYOUT_T>
__global__ __aicore__ void lightning_indexer_enhance(__gm__ uint8_t *query,
                                                     __gm__ uint8_t *key,
                                                     __gm__ uint8_t *weights,
                                                     __gm__ uint8_t *actualSeqLengthsQ,
                                                     __gm__ uint8_t *actualSeqLengths,
                                                     __gm__ uint8_t *blocktable,
                                                     __gm__ uint8_t *sparseIndices,
                                                     __gm__ uint8_t *sparseValues,
                                                     __gm__ uint8_t *workspace,
                                                     __gm__ uint8_t *tiling)
{
#if (__CCE_AICORE__ == 310) || (defined __DAV_310R6__) || (__CCE_AICORE__ == 200)

#else
    TPipe tPipe;
    __gm__ uint8_t *user = GetUserWorkspace(workspace);
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);

    if constexpr (DT_Q == LI_TPL_FP16 && DT_K == LI_TPL_FP16 && DT_OUT == LI_TPL_INT32) {
        INVOKE_LI_NO_KFC_OP_IMPL(
            LIPreload, half, half, int32_t, PAGE_ATTENTION, LI_LAYOUT(LAYOUT_T), LI_LAYOUT(K_LAYOUT_T));
    } else {
        INVOKE_LI_NO_KFC_OP_IMPL(
            LIPreload, bfloat16_t, bfloat16_t, int32_t, PAGE_ATTENTION, LI_LAYOUT(LAYOUT_T), LI_LAYOUT(K_LAYOUT_T));
    }
#endif
}

