172	    constInfo.batchSize = tilingData->bSize;
173	    constInfo.qHeadNum = constInfo.gSize = tilingData->gSize;
174	    constInfo.kSeqSize = tilingData->s2Size;
175	    constInfo.qSeqSize = tilingData->s1Size;
176	    constInfo.attenMaskFlag = (tilingData->sparseMode == 3);
177	    constInfo.kCacheBlockSize = tilingData->blockSize;
178	    constInfo.kCacheStride = tilingData->kCacheStride;
179	    constInfo.maxBlockNumPerBatch = tilingData->maxBlockNumPerBatch;
180	    constInfo.sparseCount = tilingData->sparseCount;
181	    constInfo.preTokens = tilingData->preTokens;
182	    constInfo.nextTokens = tilingData->nextTokens;
183	    constInfo.returnValue = tilingData->returnValue;
184	    constInfo.outputLayout = LAYOUT_T; // 输出和输入形状一致
185	    constInfo.sparseBlockSize = tilingData->sparseBlockSize;
186	    constInfo.sparseBlockMode = tilingData->sparseBlockMode;
187	    if (LAYOUT_T == LI_LAYOUT::TND) {
