194	    constInfo.kHeadNum = K_HEAD_NUM;
195	    constInfo.headDim = HEAD_DIM;
196	    constInfo.s2BaseSize = S2_BASE_SIZE;
197	    constInfo.realSparseCount = (constInfo.sparseCount + constInfo.sparseBlockSize - 1) / constInfo.sparseBlockSize;
198	    constInfo.sparseCountFlag =
199	        (constInfo.realSparseCount <= BASE_TOPK && constInfo.sparseBlockSize == 1) ? false : true;
200	
201	    constInfo.s1BaseSize =
202	        (constInfo.sparseBlockSize != 1)
203	            ? S1_BASE_SIZE
204	            : (constInfo.sparseCountFlag ? (8192 / constInfo.realSparseCount * 2) : tilingData->s1BaseSize);
205	    constInfo.mBaseSize = constInfo.s1BaseSize * constInfo.gSize;
206	
207	    constInfo.isAverageLD = tilingData->isAverageLD;
208	}
