262	template <typename LIT>
263	__aicore__ inline uint32_t
264	LIPreload<LIT>::GetS2BaseBlockNumOnMask(uint32_t s1gIdx, uint32_t actS1Size, uint32_t actS2Size)
265	{
266	    if (actS2Size == 0) {
267	        return 0;
268	    }
269	    uint32_t s1Offset = constInfo.s1BaseSize * s1gIdx;
270	    int32_t validS2LenBase = static_cast<int32_t>(actS2Size) - static_cast<int32_t>(actS1Size);
271	    int32_t validS2Len = s1Offset + validS2LenBase + constInfo.s1BaseSize;
272	    validS2Len = Min(validS2Len, static_cast<int32_t>(actS2Size));
273	    validS2Len = Max(validS2Len, 1);
274	    return (validS2Len + constInfo.s2BaseSize - 1) / constInfo.s2BaseSize;
275	}
