277	template <typename LIT> __aicore__ inline uint32_t LIPreload<LIT>::GetTotalBaseBlockNum()
278	{
279	    uint32_t totalBlockNum = 0;
280	    uint32_t actS1Size, actS2Size;
281	    uint32_t s1GBaseNum, s2BaseNum;
282	    for (uint32_t bIdx = 0; bIdx < constInfo.batchSize; bIdx++) {
283	        GetS1S2ActualSeqLen(bIdx, actS1Size, actS2Size);
284	        s1GBaseNum = CeilDiv(actS1Size, constInfo.s1BaseSize);
285	        if (!constInfo.attenMaskFlag) {
286	            s2BaseNum = constInfo.sparseCountFlag ? (actS2Size > 0 ? 1 : 0) : CeilDiv(actS2Size, constInfo.s2BaseSize);
287	            totalBlockNum += s1GBaseNum * s2BaseNum * constInfo.kHeadNum;
288	            continue;
289	        }
290	        for (uint32_t s1gIdx = 0; s1gIdx < s1GBaseNum; s1gIdx++) {
291	            s2BaseNum = constInfo.sparseCountFlag ? (actS2Size > 0 ? 1 : 0)
292	                                                  : GetS2BaseBlockNumOnMask(s1gIdx, actS1Size, actS2Size);
293	            totalBlockNum += s2BaseNum * constInfo.kHeadNum;
294	        }
295	    }
296	    return totalBlockNum;
297	}
