299	template <typename LIT>
300	__aicore__ inline void
301	LIPreload<LIT>::SplitCoreNormalLD(uint32_t curCoreIdx, uint32_t &coreNum, LICommon::SplitCoreInfo &info)
302	{
303	    uint32_t totalBlockNum = GetTotalBaseBlockNum();
304	    uint32_t minBlockPerCore = totalBlockNum / coreNum;
305	    uint32_t deal1MoreBlockCoreNum = totalBlockNum % coreNum;
306	    uint32_t coreIdx = 0;
307	    uint32_t lastGS1RemainBlockCnt = 0;
308	    uint32_t coreDealBlockCnt = coreIdx < deal1MoreBlockCoreNum ? minBlockPerCore + 1 : minBlockPerCore;
309	    coreNum = minBlockPerCore == 0 ? deal1MoreBlockCoreNum : coreNum;
310	
311	    bool findLastCoreEnd = true;
312	    uint32_t actS1Size, actS2Size;
313	    uint32_t s1GBaseNum, s2BaseNum, s2Loop;
314	    for (uint32_t bN2Idx = 0; bN2Idx < constInfo.batchSize * constInfo.kHeadNum; bN2Idx++) {
315	        uint32_t bIdx = bN2Idx / constInfo.kHeadNum;
316	        if (bN2Idx % constInfo.kHeadNum == 0) {
317	            GetS1S2ActualSeqLen(bIdx, actS1Size, actS2Size);
318	            s1GBaseNum = CeilDiv(actS1Size, constInfo.s1BaseSize);
319	            s2BaseNum = CeilDiv(actS2Size, constInfo.s2BaseSize);
320	        }
321	        if constexpr (LAYOUT_T == LI_LAYOUT::BSND) {
322	            if (findLastCoreEnd && (s1GBaseNum == 0U || s2BaseNum == 0U)) {
323	                info.bN2Start = bN2Idx;
324	                info.gS1Start = 0;
325	                info.s2Start = 0;
326	                findLastCoreEnd = false;
327	            }
328	        }
329	        for (uint32_t gS1Idx = 0; gS1Idx < s1GBaseNum; gS1Idx++) {
330	            if (constInfo.attenMaskFlag) {
331	                s2BaseNum = GetS2BaseBlockNumOnMask(gS1Idx, actS1Size, actS2Size);
332	            }
333	            if (findLastCoreEnd && s2BaseNum == 0U) {
334	                info.bN2Start = bN2Idx;
335	                info.gS1Start = gS1Idx;
336	                info.s2Start = 0;
337	                findLastCoreEnd = false;
338	            }
339	            s2Loop = constInfo.sparseCountFlag ? (actS2Size > 0 ? 1 : 0) : s2BaseNum;
340	            for (uint32_t s2Idx = 0; s2Idx < s2Loop;) {
341	                if (findLastCoreEnd) {
342	                    info.bN2Start = bN2Idx;
343	                    info.gS1Start = gS1Idx;
344	                    info.s2Start = s2Idx;
345	                    findLastCoreEnd = false;
346	                }
347	                uint32_t s2RemainBaseNum = s2Loop - s2Idx;
348	                if (lastGS1RemainBlockCnt + s2RemainBaseNum >= coreDealBlockCnt) {
349	                    info.bN2End = bN2Idx;
350	                    info.gS1End = gS1Idx;
351	                    info.s2End = constInfo.sparseCountFlag ? s2BaseNum - 1
352	                                                           : s2Idx + coreDealBlockCnt - lastGS1RemainBlockCnt - 1;
353	
354	                    if (coreIdx == curCoreIdx) {
355	                        info.isLD = (s2Idx == 0 && info.s2End + 1 < s2BaseNum);
356	                        if (coreIdx == coreNum - 1 && info.bN2End != constInfo.batchSize - 1) {
357	                            info.bN2End = constInfo.batchSize - 1;
358	                            info.gS1End = 0;
359	                            info.s2End = 0;
360	                        }
361	                        return;
362	                    }
363	                    coreIdx++;
364	                    findLastCoreEnd = true;
365	                    s2Idx = info.s2End + 1;
366	                    lastGS1RemainBlockCnt = 0;
367	                    coreDealBlockCnt = coreIdx < deal1MoreBlockCoreNum ? minBlockPerCore + 1 : minBlockPerCore;
368	                } else {
369	                    lastGS1RemainBlockCnt += s2RemainBaseNum;
370	                    break;
371	                }
372	            }
373	        }
374	    }
375	}
