377	template <typename LIT>
378	__aicore__ inline void LIPreload<LIT>::AppendAverageLDTask(LICommon::SplitCoreInfo &info,
379	                                                           uint32_t groupFirstCoreIdx,
380	                                                           uint32_t coreIdx,
381	                                                           uint32_t gS1Idx,
382	                                                           uint32_t s1GBaseNum,
383	                                                           uint32_t actS1Size,
384	                                                           uint32_t predictedGroupCores,
385	                                                           bool groupIsSplit)
386	{
387	    uint32_t rankInGroup = coreIdx - groupFirstCoreIdx;
388	    uint32_t cuS1ProcNum = gS1Idx == s1GBaseNum - 1 ? (actS1Size - gS1Idx * constInfo.s1BaseSize)
389	                                                    : static_cast<uint32_t>(constInfo.s1BaseSize);
390	    uint32_t ldNeededCores = CeilDiv(cuS1ProcNum, 2U);
391	    uint32_t ldTotalCores = ldNeededCores < predictedGroupCores ? ldNeededCores : predictedGroupCores;
392	    bool shouldAppend = rankInGroup < ldTotalCores && (groupIsSplit || rankInGroup > 0);
393	    if (shouldAppend && info.ldTaskNum < LICommon::SplitCoreInfo::LD_TASK_CAPACITY) {
394	        info.ldFirstCubeId[info.ldTaskNum] = groupFirstCoreIdx;
395	        info.ldCoreRank[info.ldTaskNum] = rankInGroup;
396	        info.ldTotalCores[info.ldTaskNum] = ldTotalCores;
397	        info.ldTaskNum++;
398	    }
399	}
