401	template <typename LIT>
402	__aicore__ void inline LIPreload<LIT>::SplitCoreAverageLD(uint32_t curCoreIdx,
403	                                                          uint32_t &coreNum,
404	                                                          LICommon::SplitCoreInfo &info)
405	{
406	    uint32_t totalBlockNum = GetTotalBaseBlockNum();
407	    uint32_t minBlockPerCore = totalBlockNum / coreNum;
408	    uint32_t deal1MoreBlockCoreNum = totalBlockNum % coreNum;
409	    uint32_t coreIdx = 0;
410	    uint32_t lastGS1RemainBlockCnt = 0;
411	    uint32_t coreDealBlockCnt = coreIdx < deal1MoreBlockCoreNum ? minBlockPerCore + 1 : minBlockPerCore;
412	    coreNum = minBlockPerCore == 0 ? deal1MoreBlockCoreNum : coreNum;
413	    uint32_t predictedBlockPerCore = minBlockPerCore == 0 ? 1U : minBlockPerCore;
414	
415	    bool findLastCoreEnd = true;
416	    uint32_t actS1Size, actS2Size;
417	    uint32_t s1GBaseNum, s2BaseNum, s2Loop;
418	    uint32_t groupFirstCoreIdx = 0;
419	    for (uint32_t bN2Idx = 0; bN2Idx < constInfo.batchSize * constInfo.kHeadNum; bN2Idx++) {
420	        uint32_t bIdx = bN2Idx / constInfo.kHeadNum;
421	        if (bN2Idx % constInfo.kHeadNum == 0) {
422	            GetS1S2ActualSeqLen(bIdx, actS1Size, actS2Size);
423	            s1GBaseNum = CeilDiv(actS1Size, constInfo.s1BaseSize);
424	            s2BaseNum = CeilDiv(actS2Size, constInfo.s2BaseSize);
425	        }
426	        if constexpr (LAYOUT_T == LI_LAYOUT::BSND) {
427	            if (findLastCoreEnd && (s1GBaseNum == 0U || s2BaseNum == 0U)) {
428	                info.bN2Start = bN2Idx;
429	                info.gS1Start = 0;
430	                info.s2Start = 0;
431	                findLastCoreEnd = false;
432	            }
433	        }
434	        for (uint32_t gS1Idx = 0; gS1Idx < s1GBaseNum; gS1Idx++) {
435	            groupFirstCoreIdx = coreIdx;
436	            uint32_t groupEnterRemainBlockCnt = lastGS1RemainBlockCnt;
437	            if (constInfo.attenMaskFlag) {
438	                s2BaseNum = GetS2BaseBlockNumOnMask(gS1Idx, actS1Size, actS2Size);
439	            }
440	            if (findLastCoreEnd && s2BaseNum == 0U) {
441	                info.bN2Start = bN2Idx;
442	                info.gS1Start = gS1Idx;
443	                info.s2Start = 0;
444	                findLastCoreEnd = false;
445	            }
446	            s2Loop = constInfo.sparseCountFlag ? (actS2Size > 0 ? 1 : 0) : s2BaseNum;
447	            uint32_t totalBlocksInGroup = groupEnterRemainBlockCnt + s2Loop;
448	            // AverageLD 允许高估参与核数，后续再在 decode 阶段回收无效 rank。
449	            uint32_t predictedGroupCores = (totalBlocksInGroup + predictedBlockPerCore - 1) / predictedBlockPerCore;
450	            predictedGroupCores = predictedGroupCores == 0 ? 1 : predictedGroupCores;
451	            for (uint32_t s2Idx = 0; s2Idx < s2Loop;) {
452	                if (findLastCoreEnd) {
453	                    info.bN2Start = bN2Idx;
454	                    info.gS1Start = gS1Idx;
455	                    info.s2Start = s2Idx;
456	                    findLastCoreEnd = false;
457	                }
458	                uint32_t s2RemainBaseNum = s2Loop - s2Idx;
459	                if (lastGS1RemainBlockCnt + s2RemainBaseNum >= coreDealBlockCnt) {
460	                    info.bN2End = bN2Idx;
461	                    info.gS1End = gS1Idx;
462	                    info.s2End = constInfo.sparseCountFlag ? s2BaseNum - 1
463	                                                           : s2Idx + coreDealBlockCnt - lastGS1RemainBlockCnt - 1;
464	
465	                    if (coreIdx == curCoreIdx) {
466	                        bool groupIsSplit = info.s2End + 1 < s2BaseNum;
467	                        AppendAverageLDTask(info,
468	                                            groupFirstCoreIdx,
469	                                            coreIdx,
470	                                            gS1Idx,
471	                                            s1GBaseNum,
472	                                            actS1Size,
473	                                            predictedGroupCores,
474	                                            groupIsSplit);
475	                        if (coreIdx == coreNum - 1 && info.bN2End != constInfo.batchSize - 1) {
476	                            info.bN2End = constInfo.batchSize - 1;
477	                            info.gS1End = 0;
478	                            info.s2End = 0;
479	                        }
480	                        return;
481	                    }
482	                    coreIdx++;
483	                    findLastCoreEnd = true;
484	                    s2Idx = info.s2End + 1;
485	                    lastGS1RemainBlockCnt = 0;
486	                    coreDealBlockCnt = coreIdx < deal1MoreBlockCoreNum ? minBlockPerCore + 1 : minBlockPerCore;
487	                } else {
488	                    if (coreIdx == curCoreIdx && groupEnterRemainBlockCnt > 0) {
489	                        AppendAverageLDTask(info,
490	                                            groupFirstCoreIdx,
491	                                            coreIdx,
492	                                            gS1Idx,
493	                                            s1GBaseNum,
494	                                            actS1Size,
495	                                            predictedGroupCores,
496	                                            false);
497	                    }
498	                    lastGS1RemainBlockCnt += s2RemainBaseNum;
499	                    break;
500	                }
501	            }
502	        }
503	    }
504	}
