506	template <typename LIT>
507	__aicore__ void inline LIPreload<LIT>::SplitCore(uint32_t curCoreIdx, uint32_t &coreNum, LICommon::SplitCoreInfo &info)
508	{
509	    // 保持普通 LD 与 AverageLD 的分核逻辑完全解耦，避免互相影响性能路径。
510	    if (!constInfo.isAverageLD) {
511	        SplitCoreNormalLD(curCoreIdx, coreNum, info);
512	        return;
513	    }
514	    SplitCoreAverageLD(curCoreIdx, coreNum, info);
515	}
