517	template <typename LIT>
518	__aicore__ inline void LIPreload<LIT>::DealActSeqLenIsZero(uint32_t bIdx, uint32_t n2Idx, uint32_t s1Start)
519	{
520	    if ASCEND_IS_AIV {
521	        if (constInfo.outputLayout == LI_LAYOUT::TND) {
522	            uint32_t tSize = actualSeqLengthsGmQ.GetValue(constInfo.batchSize - 1);
523	            uint32_t tBase = bIdx == 0 ? 0 : actualSeqLengthsGmQ.GetValue(bIdx - 1);
524	            uint32_t s1Count = tempLoopInfo.actS1Size;
525	
526	            for (uint32_t s1Idx = s1Start; s1Idx < s1Count; s1Idx++) {
527	                uint64_t indiceOutOffset =
528	                    (tBase + s1Idx) * constInfo.kHeadNum * constInfo.realSparseCount + // T轴、s1轴偏移
529	                    n2Idx * constInfo.realSparseCount; // N2轴偏移
530	                vectorService.CleanInvalidOutput(indiceOutOffset);
531	            }
532	        } else if (constInfo.outputLayout == LI_LAYOUT::BSND) {
533	            for (uint32_t s1Idx = s1Start; s1Idx < constInfo.qSeqSize; s1Idx++) {
534	                // B,S1,N2,K
535	                uint64_t indiceOutOffset = bIdx * constInfo.qSeqSize * constInfo.kHeadNum * constInfo.realSparseCount +
536	                                           s1Idx * constInfo.kHeadNum * constInfo.realSparseCount + // B轴、S1轴偏移
537	                                           n2Idx * constInfo.realSparseCount; // N2轴偏移
538	                vectorService.CleanInvalidOutput(indiceOutOffset);
539	            }
540	        }
541	    }
542	}
