544	template <typename LIT>
545	__aicore__ inline void LIPreload<LIT>::Init(__gm__ uint8_t *query,
546	                                            __gm__ uint8_t *key,
547	                                            __gm__ uint8_t *weights,
548	                                            __gm__ uint8_t *actualSeqLengthsQ,
549	                                            __gm__ uint8_t *actualSeqLengths,
550	                                            __gm__ uint8_t *blockTable,
551	                                            __gm__ uint8_t *sparseIndices,
552	                                            __gm__ uint8_t *sparseValues,
553	                                            __gm__ uint8_t *workspace,
554	                                            const LITilingData *__restrict tiling,
555	                                            TPipe *tPipe)
556	{
557	    if ASCEND_IS_AIV {
558	        tmpBlockIdx = GetBlockIdx(); // vec:0-47
559	        aiCoreIdx = tmpBlockIdx / 2;
560	    } else {
561	        tmpBlockIdx = GetBlockIdx(); // cube:0-23
562	        aiCoreIdx = tmpBlockIdx;
563	    }
564	
565	    InitTilingData(tiling);
566	    InitActualSeqLen(actualSeqLengthsQ, actualSeqLengths);
567	
568	    // 计算分核
569	    SplitCore(aiCoreIdx, usedCoreNum, splitCoreInfo);
570	
571	    pipe = tPipe;
572	    // workspace 内存排布
573	    // |mm1ResGm(存S)|vec1ResGm(存LD中间结果)|vec1ParamGm(存LD参数)
574	    // |Core0_mm1ResDB0-Core0_mm1ResDB1-Core1_mm1ResDB0....Core23_mm1ResDB0-Core23_mm1ResDB1|Core0_vec1Res...
575	    uint64_t offset = 0;
576	
577	    // mm1开DoubleBuffer
578	    uint64_t singleCoreMm1ResSize = WS_DOBULE * constInfo.mBaseSize * constInfo.s2BaseSize * sizeof(MM1_OUT_T);
579	    mm1ResGm.SetGlobalBuffer((__gm__ MM1_OUT_T *)(workspace + offset + aiCoreIdx * singleCoreMm1ResSize));
580	    offset += GetBlockNum() * singleCoreMm1ResSize;
581	
582	    // ld流程需要ws大小: [aicnum, 2, CeilDiv(constInfo.mBaseSize, constInfo.gSize), topkOut_*2]
583	    // (aic, 8, 2, 2, 2048)
584	    // (aic, s1_cube, 头尾, idx/value, K)
585	    vec1ResGm.SetGlobalBuffer((__gm__ float *)(workspace + offset));
586	    offset += GetBlockNum() * constInfo.s1BaseSize * WS_DOBULE * WS_DOBULE * BASE_TOPK * sizeof(float);
587	
588	    // (aic, 8, 2, 16)
589	    // (aic, s1_cube, 头尾，16ele)
590	    vec1ParamGm.SetGlobalBuffer((__gm__ int64_t *)(workspace + offset));
591	    offset += GetBlockNum() * constInfo.s1BaseSize * WS_DOBULE * LD_PARAM_NUM * sizeof(int64_t);
592	
593	    if ASCEND_IS_AIV {
594	        vectorService.InitParams(constInfo, tiling);
595	        indiceOutGm.SetGlobalBuffer((__gm__ int32_t *)sparseIndices);
596	        valueOutGm.SetGlobalBuffer((__gm__ K_T *)sparseValues);
597	        weightsGm.SetGlobalBuffer((__gm__ K_T *)weights);
598	        vectorService.InitVec1GlobalTensor(mm1ResGm, vec1ResGm, vec1ParamGm, weightsGm, indiceOutGm, valueOutGm);
599	    } else {
600	        matmulService.InitParams(constInfo);
601	        queryGm.SetGlobalBuffer((__gm__ Q_T *)query);
602	        if constexpr (PAGE_ATTENTION) {
603	            blockTableGm.SetGlobalBuffer((__gm__ int32_t *)blockTable);
604	        }
605	        keyGm.SetGlobalBuffer((__gm__ K_T *)key);
606	        matmulService.InitMm1GlobalTensor(blockTableGm, keyGm, queryGm, mm1ResGm);
607	    }
608	    InitBuffers();
609	}
