618	template <typename LIT>
619	__aicore__ inline void LIPreload<LIT>::CalcS2LoopParams(uint32_t bN2LoopIdx, uint32_t gS1LoopIdx)
620	{
621	    tempLoopInfo.gS1Idx = gS1LoopIdx;
622	    tempLoopInfo.actMBaseSize = constInfo.mBaseSize;
623	    uint32_t remainedGS1Size = tempLoopInfo.actS1Size * constInfo.gSize - tempLoopInfo.gS1Idx * constInfo.mBaseSize;
624	    if (remainedGS1Size <= constInfo.mBaseSize && remainedGS1Size > 0) {
625	        tempLoopInfo.actMBaseSize = tempLoopInfo.mBasicSizeTail;
626	    }
627	
628	    bool isEnd = (bN2LoopIdx == splitCoreInfo.bN2End) && (gS1LoopIdx == splitCoreInfo.gS1End);
629	    uint32_t s2BlockNum;
630	    if (constInfo.attenMaskFlag) {
631	        s2BlockNum = GetS2BaseBlockNumOnMask(gS1LoopIdx, tempLoopInfo.actS1Size, tempLoopInfo.actS2Size);
632	    } else {
633	        s2BlockNum = (tempLoopInfo.actS2Size + constInfo.s2BaseSize - 1) / constInfo.s2BaseSize;
634	    }
635	    tempLoopInfo.s2LoopEnd = isEnd ? splitCoreInfo.s2End : s2BlockNum - 1;
636	}
