638	template <typename LIT> __aicore__ inline void LIPreload<LIT>::CalcGS1LoopParams(uint32_t bN2LoopIdx)
639	{
640	    GetBN2Idx(bN2LoopIdx);
641	    GetS1S2ActualSeqLen(tempLoopInfo.bIdx, tempLoopInfo.actS1Size, tempLoopInfo.actS2Size);
642	    if ((tempLoopInfo.actS2Size == 0) || (tempLoopInfo.actS1Size == 0)) {
643	        tempLoopInfo.curActSeqLenIsZero = true;
644	        return;
645	    }
646	    tempLoopInfo.curActSeqLenIsZero = false;
647	    tempLoopInfo.s2BasicSizeTail = tempLoopInfo.actS2Size % constInfo.s2BaseSize;
648	    tempLoopInfo.s2BasicSizeTail =
649	        (tempLoopInfo.s2BasicSizeTail == 0) ? constInfo.s2BaseSize : tempLoopInfo.s2BasicSizeTail;
650	    tempLoopInfo.mBasicSizeTail = (tempLoopInfo.actS1Size * constInfo.gSize) % constInfo.mBaseSize;
651	    tempLoopInfo.mBasicSizeTail =
652	        (tempLoopInfo.mBasicSizeTail == 0) ? constInfo.mBaseSize : tempLoopInfo.mBasicSizeTail;
653	
654	    uint32_t gS1SplitNum = (tempLoopInfo.actS1Size * constInfo.gSize + constInfo.mBaseSize - 1) / constInfo.mBaseSize;
655	    tempLoopInfo.gS1LoopEnd = (bN2LoopIdx == splitCoreInfo.bN2End) ? splitCoreInfo.gS1End : gS1SplitNum - 1;
656	    if constexpr (LAYOUT_T == LI_LAYOUT::BSND) {
657	        if (tempLoopInfo.gS1LoopEnd == gS1SplitNum - 1 && constInfo.qSeqSize > tempLoopInfo.actS1Size) {
658	            tempLoopInfo.needDealActS1LessThanS1 = true;
659	        }
660	    }
661	}
662	
663	template <typename LIT>
664	__aicore__ inline void LIPreload<LIT>::CalcRunInfo(uint32_t loop, uint32_t s2LoopIdx, LICommon::RunInfo &runInfo)
665	{
666	    runInfo.loop = loop;
667	    runInfo.bIdx = tempLoopInfo.bIdx;
668	    runInfo.gS1Idx = tempLoopInfo.gS1Idx;
669	    runInfo.s2Idx = s2LoopIdx;
670	    runInfo.bN2Idx = tempLoopInfo.bN2Idx;
671	
672	    runInfo.actS1Size = tempLoopInfo.actS1Size;
673	    runInfo.actS2Size = tempLoopInfo.actS2Size;
674	    // 计算实际基本块size
675	    runInfo.actMBaseSize = tempLoopInfo.actMBaseSize;
676	    runInfo.actualSingleProcessSInnerSize = constInfo.s2BaseSize;
677	    uint32_t s2SplitNum = (tempLoopInfo.actS2Size + constInfo.s2BaseSize - 1) / constInfo.s2BaseSize;
678	    if (runInfo.s2Idx == s2SplitNum - 1) {
679	        runInfo.actualSingleProcessSInnerSize = tempLoopInfo.s2BasicSizeTail;
680	    }
681	    runInfo.actualSingleProcessSInnerSizeAlign =
682	        LICommon::Align((uint32_t)runInfo.actualSingleProcessSInnerSize, LICommon::ConstInfo::BUFFER_SIZE_BYTE_32B);
683	
684	    runInfo.isFirstS2InnerLoop = s2LoopIdx == splitCoreInfo.s2Start;
685	    runInfo.isLastS2InnerLoop = s2LoopIdx == tempLoopInfo.s2LoopEnd;
686	    runInfo.isAllLoopEnd = (runInfo.bN2Idx == splitCoreInfo.bN2End) && (runInfo.gS1Idx == splitCoreInfo.gS1End) &&
687	                           (runInfo.s2Idx == splitCoreInfo.s2End);
688	
689	    if (runInfo.isFirstS2InnerLoop) {
690	        uint64_t actualSeqQPrefixSum;
691	        uint64_t actualSeqKPrefixSum;
692	        if constexpr (LAYOUT_T == LI_LAYOUT::TND) {
693	            actualSeqQPrefixSum = (runInfo.bIdx <= 0) ? 0 : actualSeqLengthsGmQ.GetValue(runInfo.bIdx - 1);
694	            actualSeqKPrefixSum = (runInfo.bIdx <= 0) ? 0 : actualSeqLengthsGm.GetValue(runInfo.bIdx - 1);
695	        } else { // BSND
696	            actualSeqQPrefixSum = (runInfo.bIdx <= 0) ? 0 : runInfo.bIdx * constInfo.qSeqSize;
697	            actualSeqKPrefixSum = (runInfo.bIdx <= 0) ? 0 : runInfo.bIdx * constInfo.kSeqSize;
698	        }
699	        uint64_t tndBIdxOffset = actualSeqQPrefixSum * constInfo.qHeadNum * constInfo.headDim;
700	        uint64_t tndKeyBIdxOffset = actualSeqKPrefixSum * constInfo.kHeadNum * constInfo.headDim;
701	        // B,S1,N1(N2,G),D
702	        queryCoreOffset = tndBIdxOffset + runInfo.gS1Idx * constInfo.mBaseSize * constInfo.headDim;
703	        keyCoreOffset = tndKeyBIdxOffset + runInfo.n2Idx * constInfo.headDim;
704	        // B,S1,N1(N2,G)/T,N1(N2,G)
705	        weightsCoreOffset = actualSeqQPrefixSum * constInfo.qHeadNum + runInfo.n2Idx * constInfo.gSize;
706	        // B,S1,N2,k/T,N2,k
707	        indiceOutCoreOffset = actualSeqQPrefixSum * constInfo.kHeadNum * constInfo.realSparseCount +
708	                              runInfo.n2Idx * constInfo.realSparseCount;
709	    }
710	    runInfo.tensorQueryOffset = queryCoreOffset;
711	    runInfo.tensorKeyOffset =
712	        keyCoreOffset + runInfo.s2Idx * constInfo.s2BaseSize * constInfo.kHeadNum * constInfo.headDim;
713	    runInfo.tensorWeightsOffset = weightsCoreOffset;
714	    runInfo.indiceOutOffset = indiceOutCoreOffset;
715	}
716	
717	template <typename LIT> __aicore__ inline void LIPreload<LIT>::Process()
718	{
719	    if (usedCoreNum == 0) {
720	        // 没有计算任务，直接清理输出
721	        ProcessInvalid();
722	        return;
723	    }
724	    ProcessMain();
725	    ProcessDecode();
726	}
727	
728	template <typename LIT> __aicore__ inline void LIPreload<LIT>::ProcessInvalid()
729	{
730	    if ASCEND_IS_AIV {
731	        uint32_t aivCoreNum = GetBlockNum() * 2; // 2 means c:v = 1:2
732	        uint64_t totalOutputSize =
733	            constInfo.batchSize * constInfo.qSeqSize * constInfo.kHeadNum * constInfo.realSparseCount;
734	        uint64_t singleCoreSize =
735	            LICommon::Align((totalOutputSize + aivCoreNum - 1) / aivCoreNum, GM_ALIGN_BYTES / sizeof(OUT_T));
736	        uint64_t baseSize = tmpBlockIdx * singleCoreSize;
737	        if (baseSize < totalOutputSize) {
738	            uint64_t dealSize =
739	                (baseSize + singleCoreSize > totalOutputSize) ? singleCoreSize : totalOutputSize - baseSize;
740	            GlobalTensor<OUT_T> indiceOut = indiceOutGm[baseSize];
741	            AscendC::InitGlobalMemory(indiceOut, dealSize, constInfo.INVALID_IDX);
742	            if (constInfo.returnValue) {
743	                event_t eventIDMTE3ToV = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE3_V));
744	                SetFlag<HardEvent::MTE3_V>(eventIDMTE3ToV);
745	                WaitFlag<HardEvent::MTE3_V>(eventIDMTE3ToV);
746	
747	                GlobalTensor<uint16_t> valueOutGmTmp;
748	                valueOutGmTmp.SetGlobalBuffer((__gm__ uint16_t *)valueOutGm.GetPhyAddr());
749	                GlobalTensor<uint16_t> valueOut = valueOutGmTmp[baseSize];
750	
751	                uint16_t negInf = 0;
752	                if constexpr (std::is_same<K_T, float16_t>::value) {
753	                    negInf = 0xFC00;
754	                } else {
755	                    negInf = 0xFF80;
756	                }
757	                AscendC::InitGlobalMemory(valueOut, dealSize, negInf);
758	            }
759	        }
760	    }
761	}
762	
763	template <typename LIT> __aicore__ inline void LIPreload<LIT>::ProcessMain()
764	{
765	    if (aiCoreIdx >= usedCoreNum) {
766	        // 无任务核直接返回
767	        return;
768	    }
769	
770	    if ASCEND_IS_AIV {
771	        vectorService.AllocEventID();
772	        CrossCoreSetFlag<LICommon::ConstInfo::FIA_SYNC_MODE2, PIPE_MTE2>(constInfo.syncV1C1);
773	        CrossCoreSetFlag<LICommon::ConstInfo::FIA_SYNC_MODE2, PIPE_MTE2>(constInfo.syncV1C1);
774	    } else {
775	        matmulService.AllocEventID();
776	    }
777	
778	    LICommon::RunInfo runInfo;
779	    uint32_t gloop = 0;
780	    for (uint32_t bN2LoopIdx = splitCoreInfo.bN2Start; bN2LoopIdx <= splitCoreInfo.bN2End; bN2LoopIdx++) {
781	        CalcGS1LoopParams(bN2LoopIdx);
782	        if (tempLoopInfo.curActSeqLenIsZero) {
783	            DealActSeqLenIsZero(tempLoopInfo.bIdx, tempLoopInfo.n2Idx, 0U);
784	            continue;
785	        }
786	        for (uint32_t gS1LoopIdx = splitCoreInfo.gS1Start; gS1LoopIdx <= tempLoopInfo.gS1LoopEnd; gS1LoopIdx++) {
787	            CalcS2LoopParams(bN2LoopIdx, gS1LoopIdx);
788	            for (int s2LoopIdx = splitCoreInfo.s2Start; s2LoopIdx <= tempLoopInfo.s2LoopEnd; s2LoopIdx++) {
789	                ProcessBaseBlock(gloop, s2LoopIdx, runInfo);
790	                ++gloop;
791	            }
792	            splitCoreInfo.s2Start = 0;
793	        }
794	        if (tempLoopInfo.needDealActS1LessThanS1) {
795	            DealActSeqLenIsZero(tempLoopInfo.bIdx, tempLoopInfo.n2Idx, tempLoopInfo.actS1Size);
796	        }
797	        splitCoreInfo.gS1Start = 0;
798	    }
799	
800	    if ASCEND_IS_AIV {
801	        vectorService.FreeEventID();
802	    } else {
803	        matmulService.FreeEventID();
804	        CrossCoreWaitFlag(constInfo.syncV1C1);
805	        CrossCoreWaitFlag(constInfo.syncV1C1);
806	    }
807	}
808	
809	template <typename LIT>
810	__aicore__ inline void LIPreload<LIT>::ProcessBaseBlock(uint32_t loop, uint64_t s2LoopIdx, LICommon::RunInfo &runInfo)
811	{
812	    CalcRunInfo(loop, s2LoopIdx, runInfo);
813	    if ASCEND_IS_AIC {
814	        CrossCoreWaitFlag(constInfo.syncV1C1);
815	        matmulService.ComputeMm1(runInfo);
816	        CrossCoreSetFlag<LICommon::ConstInfo::FIA_SYNC_MODE2, PIPE_FIX>(constInfo.syncC1V1);
817	    } else {
818	        CrossCoreWaitFlag(constInfo.syncC1V1);
819	        vectorService.ProcessVec(runInfo);
820	        CrossCoreSetFlag<LICommon::ConstInfo::FIA_SYNC_MODE2, PIPE_MTE2>(constInfo.syncV1C1);
821	    }
822	}
823	
824	template <typename LIT> __aicore__ inline void LIPreload<LIT>::ProcessDecode()
825	{
826	    if ASCEND_IS_AIV {
827	        vectorService.InitLDBuffers(pipe);
828	        ICachePreLoad(LD_PREFETCH_LEN);
829	        SyncAll();
830	        if (!constInfo.isAverageLD && splitCoreInfo.isLD) {
831	            vectorService.ProcessLD();
832	        } else if (constInfo.isAverageLD) {
833	            for (uint32_t taskIdx = 0; taskIdx < splitCoreInfo.ldTaskNum; taskIdx++) {
834	                vectorService.ProcessAverageLD(splitCoreInfo.ldFirstCubeId[taskIdx],
835	                                               splitCoreInfo.ldCoreRank[taskIdx],
836	                                               splitCoreInfo.ldTotalCores[taskIdx]);
837	            }
838	        }
839	    }
840	}
841	} // namespace LIKernel
842	#endif // LIGHTNING_INDEXER_ENHANCE_KERNEL_H
843

