25	namespace LIKernel {
26	using namespace LICommon;
27	template <typename LIT>
28	class LIMatmul {
29	public:
30	    using Q_T = typename LIT::queryType;
31	    using K_T = typename LIT::keyType;
32	
33	    __aicore__ inline LIMatmul(){};
34	    __aicore__ inline void InitBuffers(TPipe *pipe);
35	    __aicore__ inline void InitMm1GlobalTensor(const GlobalTensor<int32_t> &blkTableGm, const GlobalTensor<K_T> &keyGm,
36	                                               const GlobalTensor<Q_T> &queryGm, const GlobalTensor<float> &mm1ResGm);
37	    __aicore__ inline void InitParams(const ConstInfo &constInfo);
38	    __aicore__ inline void AllocEventID();
39	    __aicore__ inline void FreeEventID();
40	    __aicore__ inline void ComputeMm1(const LICommon::RunInfo &runInfo);
41	
42	    static constexpr IsResetLoad3dConfig LOAD3DV2_CONFIG = {true, true}; // isSetFMatrix isSetPadding;
43	    static constexpr uint64_t KEY_BUF_NUM = 3;
44	    static constexpr uint64_t QUERY_BUF_NUM = 2;
45	    static constexpr uint64_t L0_BUF_NUM = 2;
46	
47	    static constexpr uint32_t KEY_MTE1_MTE2_EVENT = EVENT_ID2;
48	    static constexpr uint32_t QUERY_MTE1_MTE2_EVENT = EVENT_ID5;         // KEY_MTE1_MTE2_EVENT + KEY_BUF_NUM;
49	    static constexpr uint32_t M_MTE1_EVENT = EVENT_ID3;
50	
51	    static constexpr uint32_t MTE2_MTE1_EVENT = EVENT_ID2;
52	    static constexpr uint32_t MTE1_M_EVENT = EVENT_ID2;
53	
54	    static constexpr uint64_t M_BASIC_BLOCK = 256;
55	    static constexpr uint64_t D_BASIC_BLOCK = 128;
56	    static constexpr uint64_t S2_BASIC_BLOCK = 256;
57	
58	    static constexpr uint64_t M_BASIC_BLOCK_L0 = 128;
59	    static constexpr uint64_t D_BASIC_BLOCK_L0 = 128;
60	    static constexpr uint64_t S2_BASIC_BLOCK_L0 = 128;
61	
62	    static constexpr uint64_t QUERY_BUFFER_OFFSET = M_BASIC_BLOCK * D_BASIC_BLOCK;
63	    static constexpr uint64_t KEY_BUFFER_OFFSET = S2_BASIC_BLOCK * D_BASIC_BLOCK;
64	    static constexpr uint64_t L0AB_BUFFER_OFFSET = M_BASIC_BLOCK_L0 * D_BASIC_BLOCK_L0;
65	    static constexpr uint64_t L0C_BUFFER_OFFSET = M_BASIC_BLOCK_L0 * S2_BASIC_BLOCK_L0;
66	
67	protected:
68	    __aicore__ inline void Fixp(uint64_t s1gGmOffset, uint64_t s2GmOffset, uint64_t s1gL0RealSize,
69	                                uint64_t s2L0RealSize, const LICommon::RunInfo &runInfo);
70	    __aicore__ inline void ComuteL0c(uint64_t s1gL0RealSize, uint64_t s2L0RealSize, const LICommon::RunInfo &runInfo);
71	    __aicore__ inline void LoadKeyToL0b(uint64_t s2L0Offset, uint64_t s2L1RealSize, uint64_t s2L0RealSize,
72	                                        const LICommon::RunInfo &runInfo);
73	    __aicore__ inline void LoadQueryToL0a(uint64_t s1gL1Offset, uint64_t s1gL0Offset, uint64_t s1gL1RealSize,
74	                                          uint64_t s1gL0RealSize, const LICommon::RunInfo &runInfo);
75	    __aicore__ inline void QueryNd2Nz(uint64_t s1gL1RealSize, uint64_t s1gL1Offset, const LICommon::RunInfo &runInfo);
76	    __aicore__ inline void KeyNd2Nz(uint64_t s2L1RealSize, uint64_t s2GmOffset, const LICommon::RunInfo &runInfo);
77	    __aicore__ inline void KeyNd2NzForPA(uint64_t s2L1RealSize, uint64_t s2GmOffset, const LICommon::RunInfo &runInfo);
78	    GlobalTensor<int32_t> blkTableGm_;
79	    GlobalTensor<K_T> keyGm_;
80	    GlobalTensor<Q_T> queryGm_;
81	    GlobalTensor<float> mm1ResGm_;
82	
83	    TBuf<TPosition::A1> bufQL1_;
84	    LocalTensor<Q_T> queryL1_;
85	    TBuf<TPosition::B1> bufKeyL1_;
86	    LocalTensor<K_T> keyL1_;
87	
88	    TBuf<TPosition::A2> bufQL0_;
89	    LocalTensor<Q_T> queryL0_;
90	    TBuf<TPosition::B2> bufKeyL0_;
91	    LocalTensor<K_T> keyL0_;
92	
93	    TBuf<TPosition::CO1> bufL0C_;
94	    LocalTensor<float> cL0_;
95	
96	    uint64_t keyL1BufIdx_ = 0;
97	    uint64_t queryL1Mte2BufIdx_ = 0;
98	    uint64_t queryL1Mte1BufIdx_ = 0;
99	    uint64_t l0BufIdx_ = 0;
100	
101	    ConstInfo constInfo_;
102	
103	private:
104	    static constexpr bool PAGE_ATTENTION = LIT::pageAttention;
105	};
106	
107	template <typename LIT>
108	__aicore__ inline void LIMatmul<LIT>::InitParams(const ConstInfo &constInfo)
109	{
110	    constInfo_ = constInfo;
111	}
112	
113	template <typename LIT>
114	__aicore__ inline void LIMatmul<LIT>::InitBuffers(TPipe *pipe)
115	{
116	    pipe->InitBuffer(bufQL1_, QUERY_BUF_NUM * M_BASIC_BLOCK * D_BASIC_BLOCK * sizeof(Q_T));
117	    queryL1_ = bufQL1_.Get<Q_T>();
118	    pipe->InitBuffer(bufKeyL1_, KEY_BUF_NUM * S2_BASIC_BLOCK * D_BASIC_BLOCK * sizeof(K_T));
119	    keyL1_ = bufKeyL1_.Get<K_T>();
120	
121	    pipe->InitBuffer(bufQL0_, L0_BUF_NUM * M_BASIC_BLOCK_L0 * D_BASIC_BLOCK_L0 * sizeof(Q_T));
122	    queryL0_ = bufQL0_.Get<Q_T>();
123	    pipe->InitBuffer(bufKeyL0_, L0_BUF_NUM * D_BASIC_BLOCK_L0 * S2_BASIC_BLOCK_L0 * sizeof(K_T));
124	    keyL0_ = bufKeyL0_.Get<K_T>();
125	
126	    pipe->InitBuffer(bufL0C_, L0_BUF_NUM * M_BASIC_BLOCK_L0 * S2_BASIC_BLOCK_L0 * sizeof(float));
127	    cL0_ = bufL0C_.Get<float>();
128	}
129	
130	template <typename LIT>
131	__aicore__ inline void
132	LIMatmul<LIT>::InitMm1GlobalTensor(const GlobalTensor<int32_t> &blkTableGm, const GlobalTensor<K_T> &keyGm,
133	                                   const GlobalTensor<Q_T> &queryGm, const GlobalTensor<float> &mm1ResGm)
134	{
135	    blkTableGm_ = blkTableGm;
136	    keyGm_ = keyGm;
137	    queryGm_ = queryGm;
138	    mm1ResGm_ = mm1ResGm;
139	}
140	
141	template <typename LIT>
142	__aicore__ inline void LIMatmul<LIT>::ComputeMm1(const LICommon::RunInfo &runInfo)
143	{
144	    uint64_t s2GmBaseOffset = runInfo.s2Idx * constInfo_.s2BaseSize;
145	    uint64_t s1gProcessSize = runInfo.actMBaseSize;
146	    uint64_t s2ProcessSize = runInfo.actualSingleProcessSInnerSize;
147	    for (uint64_t s2GmOffset = 0; s2GmOffset < s2ProcessSize; s2GmOffset += S2_BASIC_BLOCK) {
148	        WaitFlag<HardEvent::MTE1_MTE2>(KEY_MTE1_MTE2_EVENT + keyL1BufIdx_ % KEY_BUF_NUM);
149	        uint64_t s2L1RealSize =
150	            s2GmOffset + S2_BASIC_BLOCK > s2ProcessSize ? s2ProcessSize - s2GmOffset : S2_BASIC_BLOCK;
151	        if (PAGE_ATTENTION) {
152	            KeyNd2NzForPA(s2L1RealSize, s2GmBaseOffset + s2GmOffset, runInfo);
153	        }else {
154	            KeyNd2Nz(s2L1RealSize, s2GmOffset, runInfo);
155	        }
156	
157	        SetFlag<HardEvent::MTE2_MTE1>(MTE2_MTE1_EVENT);
158	        WaitFlag<HardEvent::MTE2_MTE1>(MTE2_MTE1_EVENT);
159	        // s1gProcessSize当前必定不会超过2倍的s1g basic block
160	        for (uint64_t s1gGmOffset = 0; s1gGmOffset < s1gProcessSize; s1gGmOffset += M_BASIC_BLOCK) {
161	            uint64_t s1gL1RealSize =
162	                s1gGmOffset + M_BASIC_BLOCK > s1gProcessSize ? s1gProcessSize - s1gGmOffset : M_BASIC_BLOCK;
163	            if (runInfo.isFirstS2InnerLoop && s2GmOffset == 0) {
164	                queryL1Mte2BufIdx_++;
165	                queryL1Mte1BufIdx_ = queryL1Mte2BufIdx_;
166	                WaitFlag<HardEvent::MTE1_MTE2>(QUERY_MTE1_MTE2_EVENT + queryL1Mte2BufIdx_ % QUERY_BUF_NUM);
167	                QueryNd2Nz(s1gL1RealSize, s1gGmOffset, runInfo);
168	                SetFlag<HardEvent::MTE2_MTE1>(MTE2_MTE1_EVENT);
169	                WaitFlag<HardEvent::MTE2_MTE1>(MTE2_MTE1_EVENT);
170	            } else {
171	                queryL1Mte1BufIdx_ =
172	                    queryL1Mte2BufIdx_ - (CeilDiv(s1gProcessSize, M_BASIC_BLOCK) - 1 - (s1gGmOffset > 0));
173	            }
174	            for (uint64_t s2L1Offset = 0; s2L1Offset < s2L1RealSize; s2L1Offset += S2_BASIC_BLOCK_L0) {
175	                uint64_t s2L0RealSize =
176	                    s2L1Offset + S2_BASIC_BLOCK_L0 > s2L1RealSize ? s2L1RealSize - s2L1Offset : S2_BASIC_BLOCK_L0;
177	                for (uint64_t s1gL1Offset = 0; s1gL1Offset < s1gL1RealSize; s1gL1Offset += M_BASIC_BLOCK_L0) {
178	                    WaitFlag<HardEvent::M_MTE1>(M_MTE1_EVENT + l0BufIdx_ % L0_BUF_NUM);
179	                    uint64_t s1gL0RealSize =
180	                        s1gL1Offset + M_BASIC_BLOCK_L0 > s1gL1RealSize ? s1gL1RealSize - s1gL1Offset : M_BASIC_BLOCK_L0;
181	                    LoadQueryToL0a(s1gGmOffset, s1gL1Offset, s1gL1RealSize, s1gL0RealSize, runInfo);
182	                    LoadKeyToL0b(s2L1Offset, s2L1RealSize, s2L0RealSize, runInfo);
183	
184	                    SetFlag<HardEvent::MTE1_M>(MTE1_M_EVENT);
185	                    WaitFlag<HardEvent::MTE1_M>(MTE1_M_EVENT);
186	
187	                    ComuteL0c(s1gL0RealSize, s2L0RealSize, runInfo);
188	
189	                    SetFlag<HardEvent::M_MTE1>(M_MTE1_EVENT + l0BufIdx_ % L0_BUF_NUM);
190	
191	                    Fixp(s1gGmOffset + s1gL1Offset, s2GmOffset + s2L1Offset, s1gL0RealSize, s2L0RealSize, runInfo);
192	                    l0BufIdx_++;
193	                }
194	            }
195	            if (s2GmOffset + S2_BASIC_BLOCK >= s2ProcessSize && runInfo.isLastS2InnerLoop) {
196	                SetFlag<HardEvent::MTE1_MTE2>(QUERY_MTE1_MTE2_EVENT + queryL1Mte1BufIdx_ % QUERY_BUF_NUM);
197	            }
198	        }
199	
200	        SetFlag<HardEvent::MTE1_MTE2>(KEY_MTE1_MTE2_EVENT + keyL1BufIdx_ % KEY_BUF_NUM);
201	        keyL1BufIdx_++;
202	    }
203	}
204	
205	template <typename LIT>
206	__aicore__ inline void LIMatmul<LIT>::KeyNd2Nz(uint64_t s2L1RealSize, uint64_t s2GmOffset,
207	                                                    const LICommon::RunInfo &runInfo)
208	{
209	    uint64_t s2L1Offset = 0;
210	    while (s2L1Offset < s2L1RealSize) {
211	        uint64_t keyGmOffset = runInfo.tensorKeyOffset + (s2GmOffset + s2L1Offset) * constInfo_.headDim;
212	        // 搬运按照S2_BASIC_BLOCK_L0*D_BASIC_BLOCK_L0的方式在l1上排布, 方便后续mte1
213	        // 根据s2的offset判断当前属于前一个L0分型还是后一个L0分型，暂时只支持两个分型
214	        uint64_t s2Mte2Size = (s2L1RealSize <= S2_BASIC_BLOCK_L0 || s2L1Offset >= S2_BASIC_BLOCK_L0) ?
215	                                  s2L1RealSize - s2L1Offset :
216	                                  S2_BASIC_BLOCK_L0 - s2L1Offset;
217	
218	        Nd2NzParams nd2nzPara;
219	        nd2nzPara.ndNum = 1;
220	        nd2nzPara.nValue = s2Mte2Size; // 行数
221	        nd2nzPara.dValue = constInfo_.headDim;
222	        nd2nzPara.srcDValue = constInfo_.headDim;
223	        nd2nzPara.dstNzC0Stride = s2L1Offset >= S2_BASIC_BLOCK_L0 ?
224	                                      CeilAlign(s2L1RealSize - S2_BASIC_BLOCK_L0, (uint64_t)BLOCK_CUBE) :
225	                                      (s2L1RealSize > S2_BASIC_BLOCK_L0 ?
226	                                           S2_BASIC_BLOCK_L0 :
227	                                           CeilAlign(s2L1RealSize, (uint64_t)BLOCK_CUBE)); // 对齐到16 单位block
228	        nd2nzPara.dstNzNStride = 1;
229	        nd2nzPara.srcNdMatrixStride = 0;
230	        nd2nzPara.dstNzMatrixStride = 0;
231	        DataCopy(keyL1_[(keyL1BufIdx_ % KEY_BUF_NUM) * KEY_BUFFER_OFFSET +
232	                        (s2L1Offset >= S2_BASIC_BLOCK_L0 ?
233	                             S2_BASIC_BLOCK_L0 * D_BASIC_BLOCK_L0 + (s2L1Offset - S2_BASIC_BLOCK_L0) * BLOCK_CUBE :
234	                             s2L1Offset * BLOCK_CUBE)],
235	                 keyGm_[keyGmOffset], nd2nzPara);
236	
237	        s2L1Offset += s2Mte2Size;
238	    }
239	}
240	
241	// blkNum, blkSize, N2, D
242	template <typename LIT>
243	__aicore__ inline void LIMatmul<LIT>::KeyNd2NzForPA(uint64_t s2L1RealSize, uint64_t s2GmOffset,
244	                                                    const LICommon::RunInfo &runInfo)
245	{
246	    uint64_t s2L1Offset = 0;
247	    while (s2L1Offset < s2L1RealSize) {
248	        uint64_t s2BlkId = (s2L1Offset + s2GmOffset) / constInfo_.kCacheBlockSize;
249	        uint64_t s2BlkOffset = (s2L1Offset + s2GmOffset) % constInfo_.kCacheBlockSize;
250	        // 使用 kCacheStride 支持非连续 cache 存储
251	        uint64_t keyGmOffset = blkTableGm_.GetValue(runInfo.bIdx * constInfo_.maxBlockNumPerBatch + s2BlkId) *
252	                                   constInfo_.kCacheStride + s2BlkOffset * constInfo_.headDim;
253	        // 搬运按照S2_BASIC_BLOCK_L0*D_BASIC_BLOCK_L0的方式在l1上排布, 方便后续mte1
254	        // 根据s2的offset判断当前属于前一个L0分型还是后一个L0分型，暂时只支持两个分型
255	        uint64_t s2Mte2Size = (s2L1RealSize <= S2_BASIC_BLOCK_L0 || s2L1Offset >= S2_BASIC_BLOCK_L0) ?
256	                                  s2L1RealSize - s2L1Offset :
257	                                  S2_BASIC_BLOCK_L0 - s2L1Offset;
258	        s2Mte2Size = s2BlkOffset + s2Mte2Size >= constInfo_.kCacheBlockSize ? constInfo_.kCacheBlockSize - s2BlkOffset :
259	                                                                              s2Mte2Size;
260	        Nd2NzParams nd2nzPara;
261	        nd2nzPara.ndNum = 1;
262	        nd2nzPara.nValue = s2Mte2Size; // 行数
263	        nd2nzPara.dValue = constInfo_.headDim;
264	        nd2nzPara.srcDValue = constInfo_.headDim;
265	        nd2nzPara.dstNzC0Stride = s2L1Offset >= S2_BASIC_BLOCK_L0 ?
266	                                      CeilAlign(s2L1RealSize - S2_BASIC_BLOCK_L0, (uint64_t)BLOCK_CUBE) :
267	                                      (s2L1RealSize > S2_BASIC_BLOCK_L0 ?
268	                                           S2_BASIC_BLOCK_L0 :
269	                                           CeilAlign(s2L1RealSize, (uint64_t)BLOCK_CUBE)); // 对齐到16 单位block
270	        nd2nzPara.dstNzNStride = 1;
271	        nd2nzPara.srcNdMatrixStride = 0;
272	        nd2nzPara.dstNzMatrixStride = 0;
273	        DataCopy(keyL1_[(keyL1BufIdx_ % KEY_BUF_NUM) * KEY_BUFFER_OFFSET +
274	                        (s2L1Offset >= S2_BASIC_BLOCK_L0 ?
275	                             S2_BASIC_BLOCK_L0 * D_BASIC_BLOCK_L0 + (s2L1Offset - S2_BASIC_BLOCK_L0) * BLOCK_CUBE :
276	                             s2L1Offset * BLOCK_CUBE)],
277	                 keyGm_[keyGmOffset], nd2nzPara);
278	
279	        s2L1Offset += s2Mte2Size;
280	    }
281	}
282	
283	// batch, s1, n2, g, d
284	template <typename LIT>
285	__aicore__ inline void LIMatmul<LIT>::QueryNd2Nz(uint64_t s1gL1RealSize, uint64_t s1gGmOffset,
286	                                                 const LICommon::RunInfo &runInfo)
287	{
288	    Nd2NzParams nd2nzPara;
289	    nd2nzPara.ndNum = 1;
290	    nd2nzPara.nValue = s1gL1RealSize; // 行数
291	    nd2nzPara.dValue = constInfo_.headDim;
292	    nd2nzPara.srcDValue = constInfo_.headDim;
293	    nd2nzPara.dstNzC0Stride = CeilAlign(s1gL1RealSize, (uint64_t)BLOCK_CUBE); // 对齐到16 单位block
294	    nd2nzPara.dstNzNStride = 1;
295	    nd2nzPara.srcNdMatrixStride = 0;
296	    nd2nzPara.dstNzMatrixStride = 0;
297	    // 默认一块buf最多放两份
298	    DataCopy(queryL1_[(queryL1Mte2BufIdx_ % QUERY_BUF_NUM) * QUERY_BUFFER_OFFSET],
299	             queryGm_[runInfo.tensorQueryOffset + s1gGmOffset * constInfo_.headDim], nd2nzPara);
300	}
301	
302	template <typename LIT>
303	__aicore__ inline void LIMatmul<LIT>::LoadQueryToL0a(uint64_t s1gGmOffset, uint64_t s1gL1Offset, uint64_t s1gL1RealSize,
304	                                                     uint64_t s1gL0RealSize, const LICommon::RunInfo &runInfo)
305	{
306	    LoadData3DParamsV2<Q_T> loadData3DParams;
307	    // SetFmatrixParams
308	    loadData3DParams.l1H = CeilDiv(s1gL1RealSize, BLOCK_CUBE); // Hin=M1=8
309	    loadData3DParams.l1W = BLOCK_CUBE;                         // Win=M0
310	    loadData3DParams.channelSize = constInfo_.headDim;         // Cin=K
311	
312	    loadData3DParams.padList[0] = 0;
313	    loadData3DParams.padList[1] = 0;
314	    loadData3DParams.padList[2] = 0;
315	    loadData3DParams.padList[3] = 255; // 尾部数据不影响滑窗的结果
316	
317	    // SetLoadToA0Params
318	    loadData3DParams.mExtension = CeilAlign(s1gL0RealSize, BLOCK_CUBE); // M height维度目的
319	    loadData3DParams.kExtension = constInfo_.headDim;                   // K width维度目的
320	    loadData3DParams.mStartPt = s1gL1Offset;
321	    loadData3DParams.kStartPt = 0;
322	    loadData3DParams.strideW = 1;
323	    loadData3DParams.strideH = 1;
324	    loadData3DParams.filterW = 1;
325	    loadData3DParams.filterSizeW = (1 >> 8) & 255;
326	    loadData3DParams.filterH = 1;
327	    loadData3DParams.filterSizeH = (1 >> 8) & 255;
328	    loadData3DParams.dilationFilterW = 1;
329	    loadData3DParams.dilationFilterH = 1;
330	    loadData3DParams.enTranspose = 0;
331	    loadData3DParams.fMatrixCtrl = 0;
332	
333	    LoadData<Q_T, LOAD3DV2_CONFIG>(queryL0_[(l0BufIdx_ % L0_BUF_NUM) * L0AB_BUFFER_OFFSET],
334	                                   queryL1_[(queryL1Mte1BufIdx_ % QUERY_BUF_NUM) * QUERY_BUFFER_OFFSET],
335	                                   loadData3DParams);
336	}
337	
338	template <typename LIT>
339	__aicore__ inline void LIMatmul<LIT>::LoadKeyToL0b(uint64_t s2L1Offset, uint64_t s2L1RealSize, uint64_t s2L0RealSize,
340	                                                   const LICommon::RunInfo &runInfo)
341	{
342	    uint64_t keyL1Offset = s2L1Offset >= S2_BASIC_BLOCK_L0 ? S2_BASIC_BLOCK_L0 * D_BASIC_BLOCK_L0 : 0;
343	    LoadData2DParams loadData2DParams;
344	    loadData2DParams.startIndex = 0;
345	    loadData2DParams.repeatTimes = CeilDiv(s2L0RealSize, BLOCK_CUBE) * CeilDiv(constInfo_.headDim, BLOCK_CUBE);
346	    loadData2DParams.srcStride = 1;
347	    loadData2DParams.dstGap = 0;
348	    loadData2DParams.ifTranspose = false;
349	    LoadData(keyL0_[(l0BufIdx_ % L0_BUF_NUM) * L0AB_BUFFER_OFFSET],
350	             keyL1_[(keyL1BufIdx_ % KEY_BUF_NUM) * KEY_BUFFER_OFFSET + keyL1Offset], loadData2DParams);
351	}
352	
353	template <typename LIT>
354	__aicore__ inline void LIMatmul<LIT>::ComuteL0c(uint64_t s1gL0RealSize, uint64_t s2L0RealSize,
355	                                                const LICommon::RunInfo &runInfo)
356	{
357	    MmadParams mmadParams;
358	    mmadParams.m = CeilAlign(s1gL0RealSize, BLOCK_CUBE);
359	    mmadParams.n = s2L0RealSize;
360	    mmadParams.k = constInfo_.headDim;
361	    mmadParams.cmatrixInitVal = true;
362	    mmadParams.cmatrixSource = false;
363	    mmadParams.unitFlag = 0b11;
364	    Mmad(cL0_[(l0BufIdx_ % L0_BUF_NUM) * L0C_BUFFER_OFFSET], queryL0_[(l0BufIdx_ % L0_BUF_NUM) * L0AB_BUFFER_OFFSET],
365	         keyL0_[(l0BufIdx_ % L0_BUF_NUM) * L0AB_BUFFER_OFFSET], mmadParams);
366	    if ((mmadParams.m / 16) * (mmadParams.n / 16) < 10) {
367	        PipeBarrier<PIPE_M>();
368	    }
369	}
370	
371	template <typename LIT>
372	__aicore__ inline void LIMatmul<LIT>::Fixp(uint64_t s1gGmOffset, uint64_t s2GmOffset, uint64_t s1gL0RealSize,
373	                                           uint64_t s2L0RealSize, const LICommon::RunInfo &runInfo)
374	{
375	    AscendC::DataCopyCO12DstParams intriParams;
376	    intriParams.mSize = CeilAlign(s1gL0RealSize, BLOCK_CUBE);
377	    intriParams.nSize = s2L0RealSize;
378	    intriParams.dstStride = runInfo.actualSingleProcessSInnerSizeAlign;
379	    intriParams.srcStride = CeilAlign(s1gL0RealSize, BLOCK_CUBE);
380	    // set mode according to dtype
381	    intriParams.quantPre = QuantMode_t::NoQuant;
382	    intriParams.nz2ndEn = true;
383	    intriParams.unitFlag = 0b11; // 3 unitflag
384	    intriParams.reluPre = 1;
385	    AscendC::SetFixpipeNz2ndFlag(1, 1, 1);
386	    AscendC::DataCopy(mm1ResGm_[(runInfo.loop % 2) * constInfo_.mBaseSize * constInfo_.s2BaseSize +
387	                                s1gGmOffset * intriParams.dstStride + s2GmOffset],
388	                      cL0_[(l0BufIdx_ % L0_BUF_NUM) * L0C_BUFFER_OFFSET], intriParams);
389	}
390	
391	template <typename LIT>
392	__aicore__ inline void LIMatmul<LIT>::AllocEventID()
393	{
394	    SetMMLayoutTransform(true);
395	    SetFlag<HardEvent::MTE1_MTE2>(KEY_MTE1_MTE2_EVENT + 0);
396	    SetFlag<HardEvent::MTE1_MTE2>(KEY_MTE1_MTE2_EVENT + 1);
397	    SetFlag<HardEvent::MTE1_MTE2>(KEY_MTE1_MTE2_EVENT + 2);
398	
399	    SetFlag<HardEvent::MTE1_MTE2>(QUERY_MTE1_MTE2_EVENT + 0);
400	    SetFlag<HardEvent::MTE1_MTE2>(QUERY_MTE1_MTE2_EVENT + 1);
401	
402	    SetFlag<HardEvent::M_MTE1>(M_MTE1_EVENT + 0);
403	    SetFlag<HardEvent::M_MTE1>(M_MTE1_EVENT + 1);
404	}
405	
406	template <typename LIT>
407	__aicore__ inline void LIMatmul<LIT>::FreeEventID()
408	{
409	    SetMMLayoutTransform(false);
410	    WaitFlag<HardEvent::MTE1_MTE2>(KEY_MTE1_MTE2_EVENT + 0);
411	    WaitFlag<HardEvent::MTE1_MTE2>(KEY_MTE1_MTE2_EVENT + 1);
412	    WaitFlag<HardEvent::MTE1_MTE2>(KEY_MTE1_MTE2_EVENT + 2);
413	
414	    WaitFlag<HardEvent::MTE1_MTE2>(QUERY_MTE1_MTE2_EVENT + 0);
415	    WaitFlag<HardEvent::MTE1_MTE2>(QUERY_MTE1_MTE2_EVENT + 1);
416	
417	    WaitFlag<HardEvent::M_MTE1>(M_MTE1_EVENT + 0);
418	    WaitFlag<HardEvent::M_MTE1>(M_MTE1_EVENT + 1);
419	}
420	} // namespace LIKernel
421	#endif

