26	namespace LIKernel {
27	using namespace LICommon;
28	using namespace LIServiceVec;
29	constexpr uint32_t BASE_TOPK = 2048;
30	constexpr uint32_t LD_PARAM_NUM = 16;
31	
32	template <typename LIT> class LIVector {
33	  public:
34	    // =================================类型定义区=================================
35	    // 中间计算数据类型为float，高精度模式
36	    using K_T = typename LIT::keyType;
37	    static constexpr LI_LAYOUT LAYOUT_T = LIT::layout;
38	
39	    // MM输出数据类型, 当前只支持float
40	    using MM1_OUT_T = float;
41	
42	    __aicore__ inline LIVector(){};
43	    __aicore__ inline void ProcessVec(const LICommon::RunInfo &info);
44	    __aicore__ inline void ProcessLD();
45	    __aicore__ inline void ProcessAverageLD(uint32_t ldFirstCubeId, uint32_t ldCoreRank, uint32_t ldTotalCores);
46	    __aicore__ inline void InitBuffers(TPipe *pipe);
47	    __aicore__ inline void InitParams(const struct LICommon::ConstInfo &constInfo,
48	                                      const LITilingData *__restrict tilingData);
49	    __aicore__ inline void InitVec1GlobalTensor(GlobalTensor<MM1_OUT_T> mm1ResGm,
50	                                                GlobalTensor<float> vec1ResGm,
51	                                                GlobalTensor<int64_t> vec1ParamGm,
52	                                                GlobalTensor<K_T> weightsGm,
53	                                                GlobalTensor<int32_t> indiceOutGm,
54	                                                GlobalTensor<K_T> valueOutGm);
55	    __aicore__ inline void CleanInvalidOutput(int64_t invalidS1offset);
56	    __aicore__ inline void AllocEventID();
57	    __aicore__ inline void FreeEventID();
58	    __aicore__ inline void InitLDBuffers(TPipe *pipe);
59	
60	  protected:
61	    GlobalTensor<MM1_OUT_T> mm1ResGm;
62	    GlobalTensor<float> vec1ResGm;
63	    GlobalTensor<int64_t> vec1ParamGm;
64	    GlobalTensor<K_T> weightsGm;
65	    GlobalTensor<int32_t> indiceOutGm;
66	    GlobalTensor<K_T> valueOutGm;
67	    // =================================常量区=================================
68	
69	  private:
70	    // ================================Local Buffer区====================================
71	    // queue
72	    TQue<QuePosition::VECOUT, 1> outQueue_;
73	
74	    // tmp buff for vector
75	    TBuf<TPosition::VECCALC> sortOutBuf_;
76	    TBuf<TPosition::VECCALC> tmpBuf_;
77	    TBuf<TPosition::VECCALC> indexBuf_;
78	    TBuf<TPosition::VECCALC> reduceOutBuf_;
79	    TBuf<TPosition::VECCALC> brcBuf_;
80	    TBuf<TPosition::VECCALC> paramBuf_;
81	    TBuf<TPosition::VECCALC> reduceMaxBuf_;
82	    TBuf<TPosition::VECCALC> reduceTmpBuf_;
83	
84	    // tmp buff for LD
85	    TBuf<> ldToBeMrgBuf_;
86	    TBuf<> ldTmpBuf_;
87	    TBuf<> ldOutValueBuf_;
88	    TBuf<> ldOutIdxBuf_;
89	
90	    LocalTensor<float> tmpUb_;
91	    LocalTensor<int32_t> globalTopkIndice_;
92	    LocalTensor<float> globalTopkUb_;
93	    LocalTensor<float> SortedBasicBlock_;
94	
95	    int32_t blockId_ = -1;
96	    // para for vector
97	    int32_t groupInner_ = 0;
98	    int32_t globalTopkNum_ = 0;
99	    int64_t blockS2StartIdx_ = 0;
100	    int32_t gSize_ = 0;
101	    int32_t kHeadNum_ = 0;
102	    int32_t s1BaseSize_ = 0;
103	    int32_t s2BaseSize_ = 0;
104	
105	    // para for LD
106	    uint32_t mrgListNum_ = 4;
107	    uint32_t paramNum_ = 16;
108	    int32_t virTopK = 0;
109	
110	    constexpr static uint32_t REDUCE_BANK_CONFLICT_OFFSETS = 256;
111	    constexpr static uint32_t REDUCE_BANK_CONFLICT_NUM = REDUCE_BANK_CONFLICT_OFFSETS / sizeof(float);
112	
113	    struct LICommon::ConstInfo constInfo_;
114	    event_t eventIdVToMTE2Tmp;
115	    event_t eventIdVToMTE2Ping;
116	    event_t eventIdVToMTE2Pong;
117	    event_t eventIdVToMTE2PingPong[2];
118	    event_t eventIdMTE2ToVPing;
119	    event_t eventIdMTE2ToVPong;
120	    event_t eventIdMTE2ToVPingPong[2];
121	};
122	
123	template <typename LIT> __aicore__ inline void LIVector<LIT>::InitBuffers(TPipe *pipe)
124	{
125	    uint32_t outNeedBufSize = (BASE_TOPK * 2) * 2 * sizeof(float);
126	    uint32_t reduceCacheSize = REDUCE_BANK_CONFLICT_OFFSETS + groupInner_ * s2BaseSize_ * sizeof(float);
127	    uint32_t sortOutBufSize = BASE_TOPK * 8 * sizeof(float);
128	    outNeedBufSize = reduceCacheSize > outNeedBufSize ? reduceCacheSize : outNeedBufSize;
129	
130	    virTopK = constInfo_.sparseCountFlag && (constInfo_.sparseBlockSize == 1) ? constInfo_.realSparseCount : BASE_TOPK;
131	
132	    pipe->InitBuffer(outQueue_, 1, outNeedBufSize); // 32KB
133	    pipe->InitBuffer(tmpBuf_,
134	                     (groupInner_ * s2BaseSize_ + s2BaseSize_) * 2 *
135	                         sizeof(float)); // 68KB                                 // 32KB  extract
136	    pipe->InitBuffer(sortOutBuf_, sortOutBufSize); // 64KB
137	    pipe->InitBuffer(indexBuf_, s2BaseSize_ * sizeof(int32_t)); // 2KB
138	    pipe->InitBuffer(reduceOutBuf_, s2BaseSize_ * 2 * sizeof(float)); // 4KB
139	    pipe->InitBuffer(brcBuf_, groupInner_ * 8 * sizeof(float));
140	    pipe->InitBuffer(paramBuf_, LD_PARAM_NUM * sizeof(int64_t));
141	    // sparseBlockSize=1时不分配block中间结果buffer，避免额外UB占用压缩tiling参数导致性能劣化
142	    if (constInfo_.sparseBlockSize > 1) {
143	        pipe->InitBuffer(reduceMaxBuf_, CeilDiv(s1BaseSize_, 2) * s2BaseSize_ * sizeof(float)); // 8KB
144	        pipe->InitBuffer(reduceTmpBuf_, s2BaseSize_ * sizeof(float)); // 2KB
145	    }
146	
147	    tmpUb_ = tmpBuf_.Get<float>();
148	    globalTopkIndice_ = indexBuf_.Get<int32_t>();
149	    globalTopkUb_ = sortOutBuf_.Get<float>();
150	    SortedBasicBlock_ = globalTopkUb_[virTopK * 2 * 2];
151	    globalTopkNum_ = 0;
152	
153	    // 基本块执行前初始化UB和GM
154	    // step1. 初始化一个有序索引 0 - s2BaseSize_
155	    ArithProgression<int32_t>(globalTopkIndice_, 0, 1, s2BaseSize_);
156	    // step2. globalTopkUb_ [CeilDiv(s1BaseSize_, 2), BASE_TOPK, 2]   -inf,-1
157	    InitSortOutBuf(globalTopkUb_, CeilDiv(s1BaseSize_, 2) * virTopK * 2);
158	
159	    // step3. 初始化vec1ParamGm，是否进行LD的标志位设为-1(needFd=-1)
160	    // vec1ResIn32Gm = [aic, 2, s1BaseSize_, 16] int32
161	    // ws清零 [needFd, s2AcSeq, s2Start, s2End, isS2End, bn2idx, s1Idx, ......]
162	    LocalTensor<float> tmpfBuff = outQueue_.AllocTensor<float>();
163	    Duplicate(tmpfBuff.template ReinterpretCast<int32_t>(), -1, 2 * (s1BaseSize_ / 2) * paramNum_ * 2);
164	    SetWaitFlag<HardEvent::V_MTE3>(HardEvent::V_MTE3);
165	    int64_t wsInfoOffset = (blockId_ / 2) * s1BaseSize_ * 2 * paramNum_ + // 2个AIV共同地址偏移
166	                           (blockId_ % 2) * (s1BaseSize_ / 2) * 2 * paramNum_; // 每个AIV的地址偏移，S1方向
167	    DataCopyPad(vec1ParamGm[wsInfoOffset],
168	                tmpfBuff.template ReinterpretCast<int64_t>(),
169	                {1, static_cast<uint16_t>((s1BaseSize_ / 2) * 2 * paramNum_ * sizeof(int64_t)), 0, 0});
170	    SetWaitFlag<HardEvent::MTE3_V>(HardEvent::MTE3_V);
171	    outQueue_.FreeTensor(tmpfBuff);
172	}
173	
174	template <typename LIT> __aicore__ inline void LIVector<LIT>::InitLDBuffers(TPipe *pipe)
175	{
176	    pipe->Reset();
177	    pipe->InitBuffer(ldToBeMrgBuf_, 2 * BASE_TOPK * mrgListNum_ * sizeof(float)); // 2：value + index
178	    pipe->InitBuffer(ldTmpBuf_, 2 * BASE_TOPK * mrgListNum_ * sizeof(float)); // 2：value + index
179	    pipe->InitBuffer(ldOutValueBuf_, BASE_TOPK * sizeof(float));
180	    pipe->InitBuffer(ldOutIdxBuf_, BASE_TOPK * sizeof(int32_t));
181	}
182	
183	template <typename LIT>
184	__aicore__ inline void LIVector<LIT>::InitParams(const struct LICommon::ConstInfo &constInfo,
185	                                                 const LITilingData *__restrict tilingData)
186	{
187	    this->constInfo_ = constInfo;
188	    blockS2StartIdx_ = 0;
189	    gSize_ = constInfo.gSize;
190	    // define N2 para
191	    kHeadNum_ = constInfo.kHeadNum;
192	    // define MMBase para
193	    s1BaseSize_ = constInfo.s1BaseSize;
194	    s2BaseSize_ = constInfo.s2BaseSize;
195	
196	    // group ub 切分因子当前按照UB空间强制为16
197	    groupInner_ = 16;
198	
199	    blockId_ = GetBlockIdx();
200	}
