202	template <typename LIT>
203	__aicore__ inline void LIVector<LIT>::InitVec1GlobalTensor(GlobalTensor<MM1_OUT_T> mm1ResGm,
204	                                                           GlobalTensor<float> vec1ResGm,
205	                                                           GlobalTensor<int64_t> vec1ParamGm,
206	                                                           GlobalTensor<K_T> weightsGm,
207	                                                           GlobalTensor<int32_t> indiceOutGm,
208	                                                           GlobalTensor<K_T> valueOutGm)
209	{
210	    this->mm1ResGm = mm1ResGm;
211	    this->vec1ResGm = vec1ResGm;
212	    this->vec1ParamGm = vec1ParamGm;
213	    this->weightsGm = weightsGm;
214	    this->indiceOutGm = indiceOutGm;
215	    this->valueOutGm = valueOutGm;
216	}
