218	template <typename LIT> __aicore__ inline void LIVector<LIT>::AllocEventID()
219	{
220	    eventIdVToMTE2Tmp = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::V_MTE2>());
221	    eventIdVToMTE2Ping = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::V_MTE2>());
222	    eventIdVToMTE2Pong = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::V_MTE2>());
223	    eventIdVToMTE2PingPong[0] = eventIdVToMTE2Ping;
224	    eventIdVToMTE2PingPong[1] = eventIdVToMTE2Pong;
225	    eventIdMTE2ToVPing = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE2_V>());
226	    eventIdMTE2ToVPong = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE2_V>());
227	    eventIdMTE2ToVPingPong[0] = eventIdMTE2ToVPing;
228	    eventIdMTE2ToVPingPong[1] = eventIdMTE2ToVPong;
229	    SetFlag<HardEvent::V_MTE2>(eventIdVToMTE2Tmp);
230	    SetFlag<HardEvent::V_MTE2>(eventIdVToMTE2Ping);
231	    SetFlag<HardEvent::V_MTE2>(eventIdVToMTE2Pong);
232	}
