234	template <typename LIT> __aicore__ inline void LIVector<LIT>::FreeEventID()
235	{
236	    WaitFlag<HardEvent::V_MTE2>(eventIdVToMTE2Tmp);
237	    WaitFlag<HardEvent::V_MTE2>(eventIdVToMTE2Ping);
238	    WaitFlag<HardEvent::V_MTE2>(eventIdVToMTE2Pong);
239	    GetTPipePtr()->ReleaseEventID<HardEvent::V_MTE2>(eventIdVToMTE2Tmp);
240	    GetTPipePtr()->ReleaseEventID<HardEvent::V_MTE2>(eventIdVToMTE2Ping);
241	    GetTPipePtr()->ReleaseEventID<HardEvent::V_MTE2>(eventIdVToMTE2Pong);
242	    GetTPipePtr()->ReleaseEventID<HardEvent::MTE2_V>(eventIdMTE2ToVPing);
243	    GetTPipePtr()->ReleaseEventID<HardEvent::MTE2_V>(eventIdMTE2ToVPong);
244	}
245	
246	template <typename LIT> __aicore__ inline void LIVector<LIT>::CleanInvalidOutput(int64_t invalidS1offset)
247	{
248	    // init -1 and copy to output
249	    LocalTensor<float> indiceULocal = outQueue_.AllocTensor<float>();
250	    LocalTensor<int32_t> idxULocal1 = indiceULocal.template ReinterpretCast<int32_t>();
251	    Duplicate(idxULocal1, constInfo_.INVALID_IDX, constInfo_.realSparseCount);
252	    outQueue_.EnQue<float>(indiceULocal);
253	    indiceULocal = outQueue_.DeQue<float>();
254	    LIServiceVec::CopyOut(indiceOutGm[invalidS1offset], idxULocal1, constInfo_.realSparseCount);
255	    outQueue_.FreeTensor(indiceULocal);
256	
257	    if (constInfo_.returnValue) {
258	        uint16_t negInf = 0;
259	        if constexpr (std::is_same<K_T, float16_t>::value) {
260	            negInf = 0xFC00;
261	        } else {
262	            negInf = 0xFF80;
263	        }
264	        LocalTensor<uint16_t> valueULocal = outQueue_.AllocTensor<uint16_t>();
265	        Duplicate(valueULocal, negInf, constInfo_.realSparseCount);
266	        outQueue_.EnQue<uint16_t>(valueULocal);
267	        valueULocal = outQueue_.DeQue<uint16_t>();
268	
269	        GlobalTensor<uint16_t> valueOutGmTmp;
270	        valueOutGmTmp.SetGlobalBuffer((__gm__ uint16_t *)valueOutGm.GetPhyAddr());
271	        LIServiceVec::CopyOut(valueOutGmTmp[invalidS1offset], valueULocal, constInfo_.realSparseCount);
272	        outQueue_.FreeTensor(valueULocal);
273	    }
274	}
275	
276	template <typename LIT> __aicore__ inline void LIVector<LIT>::ProcessVec(const LICommon::RunInfo &info)
277	{
278	    int32_t cuBaseS1Idx = info.gS1Idx * s1BaseSize_;
279	    int32_t cuBaseS2Idx = info.s2Idx * s2BaseSize_;
280	    int32_t cuBaseS2BlockIdx = (info.s2Idx / constInfo_.sparseBlockSize) * s2BaseSize_;
281	
282	    // 计算基本块基地址偏移 偶数循环 -> 0 + aic_offset  奇数循环 -> 512*512 + aic_offset
283	    int64_t mmGmOffset = (info.loop % 2) * ((s1BaseSize_ * gSize_) * s2BaseSize_);
284	    // (B,S1,N1,1);(T,N1,1) -> (B,S1,N2,G,1) 当前只切分到S1轴
285	    int64_t weightGmOffset = info.tensorWeightsOffset + cuBaseS1Idx * kHeadNum_ * gSize_;
286	
287	    PipeBarrier<PIPE_V>();
288	    // cuS1BeginIdxPerAiv: 每个AIV的S1起始偏移
289	    int32_t cuS1BeginIdxPerAiv = cuBaseS1Idx;
290	    int32_t cuS1ProcNum =
291	        cuS1BeginIdxPerAiv + s1BaseSize_ > info.actS1Size ? info.actS1Size % s1BaseSize_ : s1BaseSize_;
292	    // cuS1ProcNumPerAiv: 每个AIv的S1计算量
293	    int32_t cuS1ProcNumPerAiv = blockId_ % 2 == 0 ? CeilDiv(cuS1ProcNum, 2) : (cuS1ProcNum / 2);
294	    cuS1BeginIdxPerAiv += (blockId_ % 2) * CeilDiv(cuS1ProcNum, 2);
295	
296	    // 基本块基地址偏移奇数核加一个S1地址偏移
297	    weightGmOffset += (blockId_ % 2) * CeilDiv(cuS1ProcNum, 2) * kHeadNum_ * gSize_;
298	    mmGmOffset += (blockId_ % 2) * CeilDiv(cuS1ProcNum, 2) * gSize_ * info.actualSingleProcessSInnerSizeAlign;
299	
300	    // cut G
301	    int32_t outerG = CeilDiv(gSize_, groupInner_);
302	
303	    // 非首个基本块, M(S1)轴发生切换需要初始化
304	    if (info.loop != 0 && info.s2Idx == 0) {
305	        // globalTopkUb_ value,index=-inf,-1
306	        InitSortOutBuf(globalTopkUb_, CeilDiv(s1BaseSize_, 2) * virTopK * 2);
307	        blockS2StartIdx_ = 0;
308	    } else if (info.loop == 0) {
309	        blockS2StartIdx_ = info.s2Idx;
310	    }
311	    // cuRealAcSeq: 当前基本块S1对应的AcSeq
312	    int32_t cuRealAcSeq = info.actS2Size;
313	    if (constInfo_.attenMaskFlag) {
314	        // attenMask true场景
315	        cuRealAcSeq = info.actS2Size - (info.actS1Size - cuS1BeginIdxPerAiv);
316	    }
317	    LocalTensor<float> reduceOutBuff = reduceOutBuf_.Get<float>();
318	    LocalTensor<float> brcBuf = brcBuf_.Get<float>();
319	
320	    // LD输出S1方向偏移，保证2个Vector输出的内容连续
321	    uint32_t ldS1Offset = (blockId_ % 2 == 0) ? s1BaseSize_ / 2 - cuS1ProcNumPerAiv : 0;
322	    for (int innerS1Idx = 0; innerS1Idx < cuS1ProcNumPerAiv; innerS1Idx++) {
323	        if (constInfo_.attenMaskFlag) {
324	            cuRealAcSeq += 1;
325	        }
326	        int32_t cuS2Len = cuBaseS2Idx + s2BaseSize_ >= cuRealAcSeq ? cuRealAcSeq - cuBaseS2Idx : s2BaseSize_;
327	        int32_t cuS1Idx = cuS1BeginIdxPerAiv + innerS1Idx;
328	        if (cuRealAcSeq > 0 && cuS2Len > 0) {
329	            int32_t cuS2LenVecAlign = CeilDiv(cuS2Len, s2BaseSize_) * s2BaseSize_;
330	            int32_t mmUbStride = (cuS2LenVecAlign - info.actualSingleProcessSInnerSizeAlign) / B32_BLOCK_ALIGN_NUM;
331	            LocalTensor<float> reduceOutInner = reduceOutBuff[s2BaseSize_];
332	            PipeBarrier<PIPE_V>();
333	            LocalTensor<float> reduceCacheBuf = outQueue_.AllocTensor<float>();
334	            WaitFlag<HardEvent::V_MTE2>(eventIdVToMTE2Tmp);
335	            for (int outerGidx = 0; outerGidx < outerG; outerGidx++) {
336	                int32_t procGnum = outerGidx != outerG - 1 ? groupInner_ : gSize_ - outerGidx * groupInner_;
