725	        } else if (cuRealAcSeq <= 0) {
726	            CleanInvalidOutput(info.indiceOutOffset + cuS1Idx * constInfo_.realSparseCount);
727	        }
728	    }
729	
730	    // BNSD场景无效S1 输出-1
731	    if (LAYOUT_T == LI_LAYOUT::BSND) {
732	        // 最后一个S1的基本块, 需要 >= info.actS1Size
733	        bool isS1LoopEnd = (cuBaseS1Idx + s1BaseSize_) >= info.actS1Size;
734	        int32_t invalidS1Num = constInfo_.qSeqSize - info.actS1Size;
735	        // blockS2StartIdx_ == 0 控制S2从开始的核去做冗余清理
736	        if (invalidS1Num > 0 && isS1LoopEnd && blockS2StartIdx_ == 0) {
737	            int32_t s1NumPerAiv = blockId_ % 2 == 0 ? CeilDiv(invalidS1Num, 2) : (invalidS1Num / 2);
738	            int32_t s1OffsetPerAiv = info.actS1Size + (blockId_ % 2) * CeilDiv(invalidS1Num, 2);
739	            for (int innerS1Idx = 0; innerS1Idx < s1NumPerAiv; innerS1Idx++) {
740	                CleanInvalidOutput(info.indiceOutOffset + (s1OffsetPerAiv + innerS1Idx) * constInfo_.realSparseCount);
741	            }
742	        }
743	
744	        int32_t invalidS1Num2 = info.actS1Size - info.actS2Size;
745	        if (invalidS1Num2 > 0 && isS1LoopEnd && blockS2StartIdx_ == 0 && constInfo_.attenMaskFlag) {
746	            int32_t s1NumPerAiv = blockId_ % 2 == 0 ? CeilDiv(invalidS1Num2, 2) : (invalidS1Num2 / 2);
747	            int32_t s1OffsetPerAiv = (blockId_ % 2) * CeilDiv(invalidS1Num2, 2);
748	            for (int innerS1Idx = 0; innerS1Idx < s1NumPerAiv; innerS1Idx++) {
749	                CleanInvalidOutput((info.bN2Idx * constInfo_.qSeqSize + s1OffsetPerAiv + innerS1Idx) *
750	                                   constInfo_.realSparseCount);
751	            }
752	        }
753	    }
754	
755	    if (info.isLastS2InnerLoop) {
756	        // S2最后一个Loop后, 下一个基本块初始从0开始
757	        blockS2StartIdx_ = 0;
758	    }
759	}
