761	template <typename LIT> __aicore__ inline void LIVector<LIT>::ProcessLD()
762	{
763	    int32_t curCubeId = blockId_ / 2;
764	    int32_t tmpCubeId = curCubeId;
765	
766	    int64_t isS2End;
767	    uint32_t acc_list_num = 0;
768	    int64_t needFd;
769	    int64_t wsOffset;
770	    int64_t wsInfoOffset = 0;
771	    int64_t valueOffset = 0;
772	    int64_t outOffset = 0;
773	
774	    LocalTensor<float> curValueIdxUb = ldToBeMrgBuf_.Get<float>();
775	    LocalTensor<float> tmpUb = ldTmpBuf_.Get<float>();
776	
777	    // S2开头信息
778	    // 开始必然没有头规约，因此从尾规约开始处理，while循环读取下一个核的头规约
779	    // 存满4个list或者遇到S2结尾，则做merge，直到做完S2
780	    // 每个核都忽略自己的头规约，因为必然由前面的核做完
781	    uint32_t s1LdStartIdx = 0;
782	    uint32_t s1ProcNum = 0;
783	    uint64_t paramGmCoreOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_;
784	    for (uint32_t innerS1Idx = 0; innerS1Idx < s1BaseSize_; innerS1Idx++) {
785	        needFd = vec1ParamGm.GetValue(paramGmCoreOffset + innerS1Idx * 2 * paramNum_ + paramNum_);
786	        if (needFd == 1) {
787	            s1LdStartIdx = (s1ProcNum == 0) ? innerS1Idx : s1LdStartIdx;
788	            s1ProcNum++;
789	        }
790	    }
791	
792	    if (s1ProcNum == 0) {
793	        return;
794	    }
795	
796	    uint32_t s1VecNum = CeilDiv(s1ProcNum, 2U);
797	    if (blockId_ % 2 == 1) {
798	        s1LdStartIdx = s1LdStartIdx + s1VecNum;
799	        s1VecNum = s1ProcNum - s1VecNum;
800	    }
801	    for (uint32_t innerS1Idx = s1LdStartIdx; innerS1Idx < s1LdStartIdx + s1VecNum; innerS1Idx++) {
802	        tmpCubeId = curCubeId;
803	        acc_list_num = 0;
804	        valueOffset = 0;
805	
806	        wsOffset = tmpCubeId * s1BaseSize_ * 2 * 2 * BASE_TOPK + innerS1Idx * 2 * 2 * BASE_TOPK + 2 * BASE_TOPK;
807	        SetWaitFlag<HardEvent::V_MTE2>(HardEvent::V_MTE2);
808	        SetWaitFlag<HardEvent::S_MTE2>(HardEvent::S_MTE2);
809	        DataCopyPad(curValueIdxUb,
810	                    vec1ResGm[wsOffset],
811	                    {1, static_cast<uint16_t>(2 * BASE_TOPK * sizeof(int32_t)), 0, 0},
812	                    {true, 0, 0, 0});
813	        acc_list_num++;
814	        valueOffset += 2 * BASE_TOPK;
815	
816	        tmpCubeId++;
817	        wsInfoOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_ + innerS1Idx * 2 * paramNum_;
818	        needFd = vec1ParamGm.GetValue(wsInfoOffset);
819	        isS2End = vec1ParamGm.GetValue(wsInfoOffset + 4);
820	        outOffset = vec1ParamGm.GetValue(wsInfoOffset + 8);
821	
822	        while (needFd == 1) {
823	            wsOffset = tmpCubeId * s1BaseSize_ * 2 * 2 * BASE_TOPK + innerS1Idx * 2 * 2 * BASE_TOPK;
824	            SetWaitFlag<HardEvent::V_MTE2>(HardEvent::V_MTE2);
825	            SetWaitFlag<HardEvent::S_MTE2>(HardEvent::S_MTE2);
826	            DataCopyPad(curValueIdxUb[valueOffset],
827	                        vec1ResGm[wsOffset],
828	                        {1, static_cast<uint16_t>(2 * BASE_TOPK * sizeof(int32_t)), 0, 0},
829	                        {true, 0, 0, 0});
830	            valueOffset += 2 * BASE_TOPK;
831	            acc_list_num++;
832	
833	            if (acc_list_num == mrgListNum_) {
834	                AscendC::MrgSort4Info params;
835	                params.elementLengths[0] = BASE_TOPK;
836	                params.elementLengths[1] = BASE_TOPK;
837	                params.elementLengths[2] = BASE_TOPK;
838	                params.elementLengths[3] = BASE_TOPK;
839	                params.ifExhaustedSuspension = true;
840	                params.validBit = 0b1111;
841	                params.repeatTimes = 1;
842	
843	                AscendC::MrgSortSrcList<float> srcList;
844	                srcList.src1 = curValueIdxUb[0];
845	                srcList.src2 = curValueIdxUb[2 * BASE_TOPK];
846	                srcList.src3 = curValueIdxUb[4 * BASE_TOPK];
847	                srcList.src4 = curValueIdxUb[6 * BASE_TOPK];
848	                SetWaitFlag<HardEvent::MTE2_V>(HardEvent::MTE2_V);
849	                MrgSort(tmpUb, srcList, params);
850	                PipeBarrier<PIPE_V>();
851	                DataCopy(curValueIdxUb, tmpUb, 2 * BASE_TOPK);
852	                PipeBarrier<PIPE_V>();
853	                acc_list_num = 1;
854	                valueOffset = 2 * BASE_TOPK;
855	            }
856	
857	            if (isS2End == 1) {
858	                break;
859	            }
860	
861	            tmpCubeId++;
862	            wsInfoOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_ + innerS1Idx * 2 * paramNum_;
863	            needFd = vec1ParamGm.GetValue(wsInfoOffset);
864	            isS2End = vec1ParamGm.GetValue(wsInfoOffset + 4);
865	        }
866	
867	        if (acc_list_num != 1) {
868	            AscendC::MrgSort4Info params;
869	            params.elementLengths[0] = BASE_TOPK;
870	            params.elementLengths[1] = BASE_TOPK;
871	            params.elementLengths[2] = BASE_TOPK;
872	            params.elementLengths[3] = BASE_TOPK;
873	            params.ifExhaustedSuspension = true;
874	            params.validBit = acc_list_num == 2 ? 0b0011 : 0b0111;
875	            params.repeatTimes = 1;
876	
877	            AscendC::MrgSortSrcList<float> srcList;
878	            srcList.src1 = curValueIdxUb[0];
879	            srcList.src2 = curValueIdxUb[2 * BASE_TOPK];
880	            srcList.src3 = curValueIdxUb[4 * BASE_TOPK];
881	            srcList.src4 = curValueIdxUb[6 * BASE_TOPK];
882	            SetWaitFlag<HardEvent::MTE2_V>(HardEvent::MTE2_V);
883	            MrgSort(tmpUb, srcList, params);
884	            PipeBarrier<PIPE_V>();
885	            DataCopy(curValueIdxUb, tmpUb, 2 * BASE_TOPK);
886	            PipeBarrier<PIPE_V>();
887	        }
888	
889	        LocalTensor<float> outValueUb = ldOutValueBuf_.Get<float>();
890	        LocalTensor<uint32_t> outIdxUb = ldOutIdxBuf_.Get<uint32_t>();
891	        if (!constInfo_.returnValue) {
892	            Extract(outValueUb, outIdxUb, curValueIdxUb, (BASE_TOPK / 32));
893	            LocalTensor<int32_t> idxULocal1 = outIdxUb.template ReinterpretCast<int32_t>();
894	            SetWaitFlag<HardEvent::V_MTE3>(HardEvent::V_MTE3);
895	            SetWaitFlag<HardEvent::S_MTE3>(HardEvent::S_MTE3);
896	            DataCopyPad(indiceOutGm[outOffset],
897	                        idxULocal1,
898	                        {1, static_cast<uint16_t>(constInfo_.realSparseCount * sizeof(int32_t)), 0, 0});
899	            SetWaitFlag<HardEvent::MTE3_V>(HardEvent::MTE3_V);
900	        } else {
901	            Extract(outValueUb, outIdxUb, curValueIdxUb, (BASE_TOPK / 32));
902	            PipeBarrier<PIPE_V>();
903	            LocalTensor<int32_t> idxULocal1 = outIdxUb.template ReinterpretCast<int32_t>();
904	            LocalTensor<K_T> valueULocal1 = outValueUb.template ReinterpretCast<K_T>();
905	            Cast(valueULocal1, outValueUb, RoundMode::CAST_ROUND, constInfo_.realSparseCount);
906	            PipeBarrier<PIPE_V>();
907	            SetWaitFlag<HardEvent::V_MTE3>(HardEvent::V_MTE3);
908	            SetWaitFlag<HardEvent::S_MTE3>(HardEvent::S_MTE3);
909	            DataCopyPad(indiceOutGm[outOffset],
910	                        idxULocal1,
911	                        {1, static_cast<uint16_t>(constInfo_.realSparseCount * sizeof(int32_t)), 0, 0});
912	            DataCopyPad(valueOutGm[outOffset],
913	                        valueULocal1,
914	                        {1, static_cast<uint16_t>(constInfo_.realSparseCount * sizeof(K_T)), 0, 0});
915	            SetWaitFlag<HardEvent::MTE3_V>(HardEvent::MTE3_V);
916	        }
917	    }
918	}
