920	template <typename LIT>
921	__aicore__ inline void
922	LIVector<LIT>::ProcessAverageLD(uint32_t ldFirstCubeId, uint32_t ldCoreRank, uint32_t ldTotalCores)
923	{
924	    int32_t curCubeId = static_cast<int32_t>(ldFirstCubeId);
925	    int32_t tmpCubeId = curCubeId;
926	
927	    int64_t isS2End;
928	    int64_t bn2Idx;
929	    int64_t s1Idx;
930	    uint32_t acc_list_num = 0;
931	    int64_t needFd;
932	    int64_t wsOffset;
933	    int64_t wsInfoOffset = 0;
934	    int64_t valueOffset = 0;
935	    int64_t outOffset = 0;
936	
937	    LocalTensor<float> curValueIdxUb = ldToBeMrgBuf_.Get<float>();
938	    LocalTensor<float> tmpUb = ldTmpBuf_.Get<float>();
939	
940	    // S2开头信息
941	    // 开始必然没有头规约，因此从尾规约开始处理，while循环读取下一个核的头规约
942	    // 存满4个list或者遇到S2结尾，则做merge，直到做完S2
943	    // 每个核都忽略自己的头规约，因为必然由前面的核做完
944	    uint32_t s1LdStartIdx = 0;
945	    uint32_t s1ProcNum = 0;
946	    uint64_t paramGmCoreOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_;
947	    for (uint32_t innerS1Idx = 0; innerS1Idx < s1BaseSize_; innerS1Idx++) {
948	        needFd = vec1ParamGm.GetValue(paramGmCoreOffset + innerS1Idx * 2 * paramNum_ + paramNum_);
949	        if (needFd == 1) {
950	            s1LdStartIdx = (s1ProcNum == 0) ? innerS1Idx : s1LdStartIdx;
951	            s1ProcNum++;
952	        }
953	    }
954	
955	    if (s1ProcNum == 0) {
956	        return;
957	    }
958	    // SplitCore 侧只提供了参与核数的上界。
959	    // 某些边界核虽然仍保留了当前 group 的头片段，但尾片段已经被后续 group 复用，
960	    // 如果仍按静态 ldTotalCores 分行，会把部分行分给实际上不再属于当前 group 的核。
961	    // 这里按最长行链重新扫描工作区，把参与核数收敛到解码阶段真实可见的数量。
962	    uint32_t maxLdCoresByRow = CeilDiv(s1ProcNum, 2U);
963	    uint32_t effectiveLdCores = (ldTotalCores < maxLdCoresByRow) ? ldTotalCores : maxLdCoresByRow;
964	    if (effectiveLdCores == 0) {
965	        return;
966	    }
967	
968	    uint32_t lastLdRowIdx = s1LdStartIdx + s1ProcNum - 1;
969	    int64_t lastRowBn2Idx = 0;
970	    int64_t lastRowS1Idx = 0;
971	    int64_t lastRowOutOffset = 0;
972	    int64_t candidateTailNeedFd = 0;
973	    int64_t candidateTailBn2Idx = 0;
974	    int64_t candidateTailS1Idx = 0;
975	    int64_t candidateTailOutOffset = 0;
976	    wsInfoOffset = curCubeId * s1BaseSize_ * 2 * paramNum_ + lastLdRowIdx * 2 * paramNum_ + paramNum_;
977	    lastRowBn2Idx = vec1ParamGm.GetValue(wsInfoOffset + 5);
978	    lastRowS1Idx = vec1ParamGm.GetValue(wsInfoOffset + 6);
979	    lastRowOutOffset = vec1ParamGm.GetValue(wsInfoOffset + 8);
980	    uint32_t scannedLdCores = 1;
981	    tmpCubeId = curCubeId;
982	    while (scannedLdCores < effectiveLdCores) {
983	        tmpCubeId++;
984	        wsInfoOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_ + lastLdRowIdx * 2 * paramNum_;
985	        needFd = vec1ParamGm.GetValue(wsInfoOffset);
986	        bn2Idx = vec1ParamGm.GetValue(wsInfoOffset + 5);
987	        s1Idx = vec1ParamGm.GetValue(wsInfoOffset + 6);
988	        outOffset = vec1ParamGm.GetValue(wsInfoOffset + 8);
989	        if (needFd != 1 || bn2Idx != lastRowBn2Idx || s1Idx != lastRowS1Idx || outOffset != lastRowOutOffset) {
990	            break;
991	        }
992	        // 边界核可能仍在 slot0 保留当前 group 的头片段，但 slot1 已经写入下一个 gS1 group 的尾片段。
993	        // 这种核不能继续计入当前 group 的 LD 参与者，否则会把当前行分配给下一个 group 的归约执行者。
994	        int64_t candidateTailWsInfoOffset =
995	            tmpCubeId * s1BaseSize_ * 2 * paramNum_ + lastLdRowIdx * 2 * paramNum_ + paramNum_;
996	        candidateTailNeedFd = vec1ParamGm.GetValue(candidateTailWsInfoOffset);
997	        candidateTailBn2Idx = vec1ParamGm.GetValue(candidateTailWsInfoOffset + 5);
998	        candidateTailS1Idx = vec1ParamGm.GetValue(candidateTailWsInfoOffset + 6);
999	        candidateTailOutOffset = vec1ParamGm.GetValue(candidateTailWsInfoOffset + 8);
1000	        if (candidateTailNeedFd == 1 && (candidateTailBn2Idx != lastRowBn2Idx || candidateTailS1Idx != lastRowS1Idx ||
1001	                                         candidateTailOutOffset != lastRowOutOffset)) {
1002	            break;
1003	        }
1004	        scannedLdCores++;
1005	        isS2End = vec1ParamGm.GetValue(wsInfoOffset + 4);
1006	        if (isS2End == 1) {
1007	            break;
1008	        }
1009	    }
1010	    effectiveLdCores = scannedLdCores;
1011	    if (ldCoreRank >= effectiveLdCores) {
1012	        return;
1013	    }
1014	
1015	    uint32_t totalAivs = effectiveLdCores * 2;
1016	    uint32_t aivRank = ldCoreRank * 2 + (blockId_ % 2); // 当前 AIV 在该 LD 任务中的全局序号
1017	    uint32_t baseRows = s1ProcNum / totalAivs;
1018	    uint32_t extraRows = s1ProcNum % totalAivs;
1019	    uint32_t myStartOffset = aivRank * baseRows + ((aivRank < extraRows) ? aivRank : extraRows);
1020	    uint32_t s1VecNum = baseRows + ((aivRank < extraRows) ? 1 : 0);
1021	    s1LdStartIdx = s1LdStartIdx + myStartOffset;
1022	    for (uint32_t innerS1Idx = s1LdStartIdx; innerS1Idx < s1LdStartIdx + s1VecNum; innerS1Idx++) {
1023	        // 重置偏移
1024	        tmpCubeId = curCubeId;
1025	        acc_list_num = 0;
1026	        valueOffset = 0;
1027	        int64_t expectedBn2Idx = 0;
1028	        int64_t expectedS1Idx = 0;
1029	        int64_t expectedOutOffset = 0;
1030	
1031	        // 搬入数据
1032	        wsOffset = tmpCubeId * s1BaseSize_ * 2 * 2 * BASE_TOPK + // 2个AIV共同地址偏移
1033	                   innerS1Idx * 2 * 2 * BASE_TOPK + 2 * BASE_TOPK;
1034	        SetWaitFlag<HardEvent::V_MTE2>(HardEvent::V_MTE2);
1035	        SetWaitFlag<HardEvent::S_MTE2>(HardEvent::S_MTE2);
1036	        DataCopyPad(curValueIdxUb,
1037	                    vec1ResGm[wsOffset],
1038	                    {1, static_cast<uint16_t>(2 * BASE_TOPK * sizeof(int32_t)), 0, 0},
1039	                    {true, 0, 0, 0});
1040	        acc_list_num++;
1041	        valueOffset += 2 * BASE_TOPK;
1042	        wsInfoOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_ + innerS1Idx * 2 * paramNum_ + paramNum_;
1043	        expectedBn2Idx = vec1ParamGm.GetValue(wsInfoOffset + 5);
1044	        expectedS1Idx = vec1ParamGm.GetValue(wsInfoOffset + 6);
1045	        expectedOutOffset = vec1ParamGm.GetValue(wsInfoOffset + 8);
1046	        outOffset = expectedOutOffset;
1047	
1048	        // 获取下一个核规约信息
1049	        tmpCubeId++;
1050	        wsInfoOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_ + innerS1Idx * 2 * paramNum_;
1051	        needFd = vec1ParamGm.GetValue(wsInfoOffset);
1052	        isS2End = vec1ParamGm.GetValue(wsInfoOffset + 4);
1053	        bn2Idx = vec1ParamGm.GetValue(wsInfoOffset + 5);
1054	        s1Idx = vec1ParamGm.GetValue(wsInfoOffset + 6);
1055	        outOffset = vec1ParamGm.GetValue(wsInfoOffset + 8);
1056	
1057	        while (needFd == 1 && bn2Idx == expectedBn2Idx && s1Idx == expectedS1Idx && outOffset == expectedOutOffset) {
1058	            // 搬入头规约数据
1059	            wsOffset = tmpCubeId * s1BaseSize_ * 2 * 2 * BASE_TOPK + // 2个AIV共同地址偏移
1060	                       innerS1Idx * 2 * 2 * BASE_TOPK;
1061	            SetWaitFlag<HardEvent::V_MTE2>(HardEvent::V_MTE2);
1062	            SetWaitFlag<HardEvent::S_MTE2>(HardEvent::S_MTE2);
1063	            DataCopyPad(curValueIdxUb[valueOffset],
1064	                        vec1ResGm[wsOffset],
1065	                        {1, static_cast<uint16_t>(2 * BASE_TOPK * sizeof(int32_t)), 0, 0},
1066	                        {true, 0, 0, 0});
1067	            valueOffset += 2 * BASE_TOPK;
1068	            acc_list_num++;
1069	
1070	            // 每满4个list，聚合  前2K为mrg结果
1071	            if (acc_list_num == mrgListNum_) {
1072	                // MrgSort 四条2048的队列，Mrg成一条
1073	                AscendC::MrgSort4Info params;
1074	                params.elementLengths[0] = BASE_TOPK;
1075	                params.elementLengths[1] = BASE_TOPK;
1076	                params.elementLengths[2] = BASE_TOPK;
1077	                params.elementLengths[3] = BASE_TOPK;
1078	                params.ifExhaustedSuspension = true;
1079	                params.validBit = 0b1111;
1080	                params.repeatTimes = 1;
1081	
1082	                AscendC::MrgSortSrcList<float> srcList;
1083	                srcList.src1 = curValueIdxUb[0];
1084	                srcList.src2 = curValueIdxUb[2 * BASE_TOPK];
1085	                srcList.src3 = curValueIdxUb[4 * BASE_TOPK];
1086	                srcList.src4 = curValueIdxUb[6 * BASE_TOPK];
1087	                SetWaitFlag<HardEvent::MTE2_V>(HardEvent::MTE2_V);
1088	                MrgSort(tmpUb, srcList, params);
1089	                PipeBarrier<PIPE_V>();
1090	                DataCopy(curValueIdxUb, tmpUb, 2 * BASE_TOPK);
1091	                PipeBarrier<PIPE_V>();
1092	                acc_list_num = 1;
1093	                valueOffset = 2 * BASE_TOPK;
1094	            }
1095	
1096	            // reduce到S2末尾，则跳出
1097	            if (isS2End == 1) {
1098	                break;
1099	            }
1100	
1101	            tmpCubeId++;
1102	            wsInfoOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_ + innerS1Idx * 2 * paramNum_;
1103	            needFd = vec1ParamGm.GetValue(wsInfoOffset);
1104	            isS2End = vec1ParamGm.GetValue(wsInfoOffset + 4);
1105	            bn2Idx = vec1ParamGm.GetValue(wsInfoOffset + 5);
1106	            s1Idx = vec1ParamGm.GetValue(wsInfoOffset + 6);
1107	            outOffset = vec1ParamGm.GetValue(wsInfoOffset + 8);
1108	        }
1109	
1110	        // mrg不足4个list的数据
1111	        if (acc_list_num != 1) {
1112	            AscendC::MrgSort4Info params;
1113	            params.elementLengths[0] = BASE_TOPK;
1114	            params.elementLengths[1] = BASE_TOPK;
1115	            params.elementLengths[2] = BASE_TOPK;
1116	            params.elementLengths[3] = BASE_TOPK;
1117	            params.ifExhaustedSuspension = true;
1118	            params.validBit = acc_list_num == 2 ? 0b0011 : 0b0111;
1119	            params.repeatTimes = 1;
1120	
1121	            AscendC::MrgSortSrcList<float> srcList;
1122	            srcList.src1 = curValueIdxUb[0];
1123	            srcList.src2 = curValueIdxUb[2 * BASE_TOPK];
1124	            srcList.src3 = curValueIdxUb[4 * BASE_TOPK];
1125	            srcList.src4 = curValueIdxUb[6 * BASE_TOPK];
1126	            SetWaitFlag<HardEvent::MTE2_V>(HardEvent::MTE2_V);
1127	            MrgSort(tmpUb, srcList, params);
1128	            PipeBarrier<PIPE_V>();
1129	            DataCopy(curValueIdxUb, tmpUb, 2 * BASE_TOPK);
1130	            PipeBarrier<PIPE_V>();
1131	        }
1132	
1133	        // 搬出
1134	        LocalTensor<float> outValueUb = ldOutValueBuf_.Get<float>();
1135	        LocalTensor<uint32_t> outIdxUb = ldOutIdxBuf_.Get<uint32_t>();
1136	        if (!constInfo_.returnValue) {
1137	            Extract(outValueUb, outIdxUb, curValueIdxUb, (BASE_TOPK / 32));
1138	            LocalTensor<int32_t> idxULocal1 = outIdxUb.template ReinterpretCast<int32_t>();
1139	            SetWaitFlag<HardEvent::V_MTE3>(HardEvent::V_MTE3);
1140	            SetWaitFlag<HardEvent::S_MTE3>(HardEvent::S_MTE3);
1141	            DataCopyPad(indiceOutGm[outOffset],
1142	                        idxULocal1,
1143	                        {1, static_cast<uint16_t>(constInfo_.realSparseCount * sizeof(int32_t)), 0, 0});
1144	            SetWaitFlag<HardEvent::MTE3_V>(HardEvent::MTE3_V);
1145	        } else {
1146	            Extract(outValueUb, outIdxUb, curValueIdxUb, (BASE_TOPK / 32));
1147	            PipeBarrier<PIPE_V>();
1148	            LocalTensor<int32_t> idxULocal1 = outIdxUb.template ReinterpretCast<int32_t>();
1149	            LocalTensor<K_T> valueULocal1 = outValueUb.template ReinterpretCast<K_T>();
1150	            Cast(valueULocal1, outValueUb, RoundMode::CAST_ROUND, constInfo_.realSparseCount);
1151	            PipeBarrier<PIPE_V>();
1152	            SetWaitFlag<HardEvent::V_MTE3>(HardEvent::V_MTE3);
1153	            SetWaitFlag<HardEvent::S_MTE3>(HardEvent::S_MTE3);
1154	            DataCopyPad(indiceOutGm[outOffset],
1155	                        idxULocal1,
1156	                        {1, static_cast<uint16_t>(constInfo_.realSparseCount * sizeof(int32_t)), 0, 0});
1157	            DataCopyPad(valueOutGm[outOffset],
1158	                        valueULocal1,
1159	                        {1, static_cast<uint16_t>(constInfo_.realSparseCount * sizeof(K_T)), 0, 0});
1160	            SetWaitFlag<HardEvent::MTE3_V>(HardEvent::MTE3_V);
1161	        }
1162	    }
1163	}
1164	} // namespace LIKernel
1165	#endif
