/*!
 * \file lightning_indexer_enhance_service_vector.h
 * \brief
 */
#ifndef LIGHTNING_INDEXER_ENHANCE_SERVICE_VECTOR_H
#define LIGHTNING_INDEXER_ENHANCE_SERVICE_VECTOR_H

#include "kernel_operator.h"
#include "kernel_operator_list_tensor_intf.h"
#include "kernel_tiling/kernel_tiling.h"
#include "lib/matmul_intf.h"
#include "lib/matrix/matmul/tiling.h"
#include "lightning_indexer_enhance_common.h"
#include "lightning_indexer_enhance_vector.h"

namespace LIKernel {
using namespace LICommon;
using namespace LIServiceVec;
constexpr uint32_t BASE_TOPK = 2048;
constexpr uint32_t LD_PARAM_NUM = 16;

template <typename LIT> class LIVector {
  public:
    // =================================类型定义区=================================
    // 中间计算数据类型为float，高精度模式
    using K_T = typename LIT::keyType;
    static constexpr LI_LAYOUT LAYOUT_T = LIT::layout;

    // MM输出数据类型, 当前只支持float
    using MM1_OUT_T = float;

    __aicore__ inline LIVector(){};
    __aicore__ inline void ProcessVec(const LICommon::RunInfo &info);
    __aicore__ inline void ProcessLD();
    __aicore__ inline void ProcessAverageLD(uint32_t ldFirstCubeId, uint32_t ldCoreRank, uint32_t ldTotalCores);
    __aicore__ inline void InitBuffers(TPipe *pipe);
    __aicore__ inline void InitParams(const struct LICommon::ConstInfo &constInfo,
                                      const LITilingData *__restrict tilingData);
    __aicore__ inline void InitVec1GlobalTensor(GlobalTensor<MM1_OUT_T> mm1ResGm,
                                                GlobalTensor<float> vec1ResGm,
                                                GlobalTensor<int64_t> vec1ParamGm,
                                                GlobalTensor<K_T> weightsGm,
                                                GlobalTensor<int32_t> indiceOutGm,
                                                GlobalTensor<K_T> valueOutGm);
    __aicore__ inline void CleanInvalidOutput(int64_t invalidS1offset);
    __aicore__ inline void AllocEventID();
    __aicore__ inline void FreeEventID();
    __aicore__ inline void InitLDBuffers(TPipe *pipe);

  protected:
    GlobalTensor<MM1_OUT_T> mm1ResGm;
    GlobalTensor<float> vec1ResGm;
    GlobalTensor<int64_t> vec1ParamGm;
    GlobalTensor<K_T> weightsGm;
    GlobalTensor<int32_t> indiceOutGm;
    GlobalTensor<K_T> valueOutGm;
    // =================================常量区=================================

  private:
    // ================================Local Buffer区====================================
    // queue
    TQue<QuePosition::VECOUT, 1> outQueue_;

    // tmp buff for vector
    TBuf<TPosition::VECCALC> sortOutBuf_;
    TBuf<TPosition::VECCALC> tmpBuf_;
    TBuf<TPosition::VECCALC> indexBuf_;
    TBuf<TPosition::VECCALC> reduceOutBuf_;
    TBuf<TPosition::VECCALC> brcBuf_;
    TBuf<TPosition::VECCALC> paramBuf_;
    TBuf<TPosition::VECCALC> reduceMaxBuf_;
    TBuf<TPosition::VECCALC> reduceTmpBuf_;

    // tmp buff for LD
    TBuf<> ldToBeMrgBuf_;
    TBuf<> ldTmpBuf_;
    TBuf<> ldOutValueBuf_;
    TBuf<> ldOutIdxBuf_;

    LocalTensor<float> tmpUb_;
    LocalTensor<int32_t> globalTopkIndice_;
    LocalTensor<float> globalTopkUb_;
    LocalTensor<float> SortedBasicBlock_;

    int32_t blockId_ = -1;
    // para for vector
    int32_t groupInner_ = 0;
    int32_t globalTopkNum_ = 0;
    int64_t blockS2StartIdx_ = 0;
    int32_t gSize_ = 0;
    int32_t kHeadNum_ = 0;
    int32_t s1BaseSize_ = 0;
    int32_t s2BaseSize_ = 0;

    // para for LD
    uint32_t mrgListNum_ = 4;
    uint32_t paramNum_ = 16;
    int32_t virTopK = 0;

    constexpr static uint32_t REDUCE_BANK_CONFLICT_OFFSETS = 256;
    constexpr static uint32_t REDUCE_BANK_CONFLICT_NUM = REDUCE_BANK_CONFLICT_OFFSETS / sizeof(float);

    struct LICommon::ConstInfo constInfo_;
    event_t eventIdVToMTE2Tmp;
    event_t eventIdVToMTE2Ping;
    event_t eventIdVToMTE2Pong;
    event_t eventIdVToMTE2PingPong[2];
    event_t eventIdMTE2ToVPing;
    event_t eventIdMTE2ToVPong;
    event_t eventIdMTE2ToVPingPong[2];
};

template <typename LIT> __aicore__ inline void LIVector<LIT>::InitBuffers(TPipe *pipe)
{
    uint32_t outNeedBufSize = (BASE_TOPK * 2) * 2 * sizeof(float);
    uint32_t reduceCacheSize = REDUCE_BANK_CONFLICT_OFFSETS + groupInner_ * s2BaseSize_ * sizeof(float);
    uint32_t sortOutBufSize = BASE_TOPK * 8 * sizeof(float);
    outNeedBufSize = reduceCacheSize > outNeedBufSize ? reduceCacheSize : outNeedBufSize;

    virTopK = constInfo_.sparseCountFlag && (constInfo_.sparseBlockSize == 1) ? constInfo_.realSparseCount : BASE_TOPK;

    pipe->InitBuffer(outQueue_, 1, outNeedBufSize); // 32KB
    pipe->InitBuffer(tmpBuf_,
                     (groupInner_ * s2BaseSize_ + s2BaseSize_) * 2 *
                         sizeof(float)); // 68KB                                 // 32KB  extract
    pipe->InitBuffer(sortOutBuf_, sortOutBufSize); // 64KB
    pipe->InitBuffer(indexBuf_, s2BaseSize_ * sizeof(int32_t)); // 2KB
    pipe->InitBuffer(reduceOutBuf_, s2BaseSize_ * 2 * sizeof(float)); // 4KB
    pipe->InitBuffer(brcBuf_, groupInner_ * 8 * sizeof(float));
    pipe->InitBuffer(paramBuf_, LD_PARAM_NUM * sizeof(int64_t));
    // sparseBlockSize=1时不分配block中间结果buffer，避免额外UB占用压缩tiling参数导致性能劣化
    if (constInfo_.sparseBlockSize > 1) {
        pipe->InitBuffer(reduceMaxBuf_, CeilDiv(s1BaseSize_, 2) * s2BaseSize_ * sizeof(float)); // 8KB
        pipe->InitBuffer(reduceTmpBuf_, s2BaseSize_ * sizeof(float)); // 2KB
    }

    tmpUb_ = tmpBuf_.Get<float>();
    globalTopkIndice_ = indexBuf_.Get<int32_t>();
    globalTopkUb_ = sortOutBuf_.Get<float>();
    SortedBasicBlock_ = globalTopkUb_[virTopK * 2 * 2];
    globalTopkNum_ = 0;

    // 基本块执行前初始化UB和GM
    // step1. 初始化一个有序索引 0 - s2BaseSize_
    ArithProgression<int32_t>(globalTopkIndice_, 0, 1, s2BaseSize_);
    // step2. globalTopkUb_ [CeilDiv(s1BaseSize_, 2), BASE_TOPK, 2]   -inf,-1
    InitSortOutBuf(globalTopkUb_, CeilDiv(s1BaseSize_, 2) * virTopK * 2);

    // step3. 初始化vec1ParamGm，是否进行LD的标志位设为-1(needFd=-1)
    // vec1ResIn32Gm = [aic, 2, s1BaseSize_, 16] int32
    // ws清零 [needFd, s2AcSeq, s2Start, s2End, isS2End, bn2idx, s1Idx, ......]
    LocalTensor<float> tmpfBuff = outQueue_.AllocTensor<float>();
    Duplicate(tmpfBuff.template ReinterpretCast<int32_t>(), -1, 2 * (s1BaseSize_ / 2) * paramNum_ * 2);
    SetWaitFlag<HardEvent::V_MTE3>(HardEvent::V_MTE3);
    int64_t wsInfoOffset = (blockId_ / 2) * s1BaseSize_ * 2 * paramNum_ + // 2个AIV共同地址偏移
                           (blockId_ % 2) * (s1BaseSize_ / 2) * 2 * paramNum_; // 每个AIV的地址偏移，S1方向
    DataCopyPad(vec1ParamGm[wsInfoOffset],
                tmpfBuff.template ReinterpretCast<int64_t>(),
                {1, static_cast<uint16_t>((s1BaseSize_ / 2) * 2 * paramNum_ * sizeof(int64_t)), 0, 0});
    SetWaitFlag<HardEvent::MTE3_V>(HardEvent::MTE3_V);
    outQueue_.FreeTensor(tmpfBuff);
}

template <typename LIT> __aicore__ inline void LIVector<LIT>::InitLDBuffers(TPipe *pipe)
{
    pipe->Reset();
    pipe->InitBuffer(ldToBeMrgBuf_, 2 * BASE_TOPK * mrgListNum_ * sizeof(float)); // 2：value + index
    pipe->InitBuffer(ldTmpBuf_, 2 * BASE_TOPK * mrgListNum_ * sizeof(float)); // 2：value + index
    pipe->InitBuffer(ldOutValueBuf_, BASE_TOPK * sizeof(float));
    pipe->InitBuffer(ldOutIdxBuf_, BASE_TOPK * sizeof(int32_t));
}

template <typename LIT>
__aicore__ inline void LIVector<LIT>::InitParams(const struct LICommon::ConstInfo &constInfo,
                                                 const LITilingData *__restrict tilingData)
{
    this->constInfo_ = constInfo;
    blockS2StartIdx_ = 0;
    gSize_ = constInfo.gSize;
    // define N2 para
    kHeadNum_ = constInfo.kHeadNum;
    // define MMBase para
    s1BaseSize_ = constInfo.s1BaseSize;
    s2BaseSize_ = constInfo.s2BaseSize;

    // group ub 切分因子当前按照UB空间强制为16
    groupInner_ = 16;

    blockId_ = GetBlockIdx();
}

template <typename LIT>
__aicore__ inline void LIVector<LIT>::InitVec1GlobalTensor(GlobalTensor<MM1_OUT_T> mm1ResGm,
                                                           GlobalTensor<float> vec1ResGm,
                                                           GlobalTensor<int64_t> vec1ParamGm,
                                                           GlobalTensor<K_T> weightsGm,
                                                           GlobalTensor<int32_t> indiceOutGm,
                                                           GlobalTensor<K_T> valueOutGm)
{
    this->mm1ResGm = mm1ResGm;
    this->vec1ResGm = vec1ResGm;
    this->vec1ParamGm = vec1ParamGm;
    this->weightsGm = weightsGm;
    this->indiceOutGm = indiceOutGm;
    this->valueOutGm = valueOutGm;
}

template <typename LIT> __aicore__ inline void LIVector<LIT>::AllocEventID()
{
    eventIdVToMTE2Tmp = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::V_MTE2>());
    eventIdVToMTE2Ping = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::V_MTE2>());
    eventIdVToMTE2Pong = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::V_MTE2>());
    eventIdVToMTE2PingPong[0] = eventIdVToMTE2Ping;
    eventIdVToMTE2PingPong[1] = eventIdVToMTE2Pong;
    eventIdMTE2ToVPing = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE2_V>());
    eventIdMTE2ToVPong = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE2_V>());
    eventIdMTE2ToVPingPong[0] = eventIdMTE2ToVPing;
    eventIdMTE2ToVPingPong[1] = eventIdMTE2ToVPong;
    SetFlag<HardEvent::V_MTE2>(eventIdVToMTE2Tmp);
    SetFlag<HardEvent::V_MTE2>(eventIdVToMTE2Ping);
    SetFlag<HardEvent::V_MTE2>(eventIdVToMTE2Pong);
}

template <typename LIT> __aicore__ inline void LIVector<LIT>::FreeEventID()
{
    WaitFlag<HardEvent::V_MTE2>(eventIdVToMTE2Tmp);
    WaitFlag<HardEvent::V_MTE2>(eventIdVToMTE2Ping);
    WaitFlag<HardEvent::V_MTE2>(eventIdVToMTE2Pong);
    GetTPipePtr()->ReleaseEventID<HardEvent::V_MTE2>(eventIdVToMTE2Tmp);
    GetTPipePtr()->ReleaseEventID<HardEvent::V_MTE2>(eventIdVToMTE2Ping);
    GetTPipePtr()->ReleaseEventID<HardEvent::V_MTE2>(eventIdVToMTE2Pong);
    GetTPipePtr()->ReleaseEventID<HardEvent::MTE2_V>(eventIdMTE2ToVPing);
    GetTPipePtr()->ReleaseEventID<HardEvent::MTE2_V>(eventIdMTE2ToVPong);
}

template <typename LIT> __aicore__ inline void LIVector<LIT>::CleanInvalidOutput(int64_t invalidS1offset)
{
    // init -1 and copy to output
    LocalTensor<float> indiceULocal = outQueue_.AllocTensor<float>();
    LocalTensor<int32_t> idxULocal1 = indiceULocal.template ReinterpretCast<int32_t>();
    Duplicate(idxULocal1, constInfo_.INVALID_IDX, constInfo_.realSparseCount);
    outQueue_.EnQue<float>(indiceULocal);
    indiceULocal = outQueue_.DeQue<float>();
    LIServiceVec::CopyOut(indiceOutGm[invalidS1offset], idxULocal1, constInfo_.realSparseCount);
    outQueue_.FreeTensor(indiceULocal);

    if (constInfo_.returnValue) {
        uint16_t negInf = 0;
        if constexpr (std::is_same<K_T, float16_t>::value) {
            negInf = 0xFC00;
        } else {
            negInf = 0xFF80;
        }
        LocalTensor<uint16_t> valueULocal = outQueue_.AllocTensor<uint16_t>();
        Duplicate(valueULocal, negInf, constInfo_.realSparseCount);
        outQueue_.EnQue<uint16_t>(valueULocal);
        valueULocal = outQueue_.DeQue<uint16_t>();

        GlobalTensor<uint16_t> valueOutGmTmp;
        valueOutGmTmp.SetGlobalBuffer((__gm__ uint16_t *)valueOutGm.GetPhyAddr());
        LIServiceVec::CopyOut(valueOutGmTmp[invalidS1offset], valueULocal, constInfo_.realSparseCount);
        outQueue_.FreeTensor(valueULocal);
    }
}

template <typename LIT> __aicore__ inline void LIVector<LIT>::ProcessVec(const LICommon::RunInfo &info)
{
    int32_t cuBaseS1Idx = info.gS1Idx * s1BaseSize_;
    int32_t cuBaseS2Idx = info.s2Idx * s2BaseSize_;
    int32_t cuBaseS2BlockIdx = (info.s2Idx / constInfo_.sparseBlockSize) * s2BaseSize_;

    // 计算基本块基地址偏移 偶数循环 -> 0 + aic_offset  奇数循环 -> 512*512 + aic_offset
    int64_t mmGmOffset = (info.loop % 2) * ((s1BaseSize_ * gSize_) * s2BaseSize_);
    // (B,S1,N1,1);(T,N1,1) -> (B,S1,N2,G,1) 当前只切分到S1轴
    int64_t weightGmOffset = info.tensorWeightsOffset + cuBaseS1Idx * kHeadNum_ * gSize_;

    PipeBarrier<PIPE_V>();
    // cuS1BeginIdxPerAiv: 每个AIV的S1起始偏移
    int32_t cuS1BeginIdxPerAiv = cuBaseS1Idx;
    int32_t cuS1ProcNum =
        cuS1BeginIdxPerAiv + s1BaseSize_ > info.actS1Size ? info.actS1Size % s1BaseSize_ : s1BaseSize_;
    // cuS1ProcNumPerAiv: 每个AIv的S1计算量
    int32_t cuS1ProcNumPerAiv = blockId_ % 2 == 0 ? CeilDiv(cuS1ProcNum, 2) : (cuS1ProcNum / 2);
    cuS1BeginIdxPerAiv += (blockId_ % 2) * CeilDiv(cuS1ProcNum, 2);

    // 基本块基地址偏移奇数核加一个S1地址偏移
    weightGmOffset += (blockId_ % 2) * CeilDiv(cuS1ProcNum, 2) * kHeadNum_ * gSize_;
    mmGmOffset += (blockId_ % 2) * CeilDiv(cuS1ProcNum, 2) * gSize_ * info.actualSingleProcessSInnerSizeAlign;

    // cut G
    int32_t outerG = CeilDiv(gSize_, groupInner_);

    // 非首个基本块, M(S1)轴发生切换需要初始化
    if (info.loop != 0 && info.s2Idx == 0) {
        // globalTopkUb_ value,index=-inf,-1
        InitSortOutBuf(globalTopkUb_, CeilDiv(s1BaseSize_, 2) * virTopK * 2);
        blockS2StartIdx_ = 0;
    } else if (info.loop == 0) {
        blockS2StartIdx_ = info.s2Idx;
    }
    // cuRealAcSeq: 当前基本块S1对应的AcSeq
    int32_t cuRealAcSeq = info.actS2Size;
    if (constInfo_.attenMaskFlag) {
        // attenMask true场景
        cuRealAcSeq = info.actS2Size - (info.actS1Size - cuS1BeginIdxPerAiv);
    }
    LocalTensor<float> reduceOutBuff = reduceOutBuf_.Get<float>();
    LocalTensor<float> brcBuf = brcBuf_.Get<float>();

    // LD输出S1方向偏移，保证2个Vector输出的内容连续
    uint32_t ldS1Offset = (blockId_ % 2 == 0) ? s1BaseSize_ / 2 - cuS1ProcNumPerAiv : 0;
    for (int innerS1Idx = 0; innerS1Idx < cuS1ProcNumPerAiv; innerS1Idx++) {
        if (constInfo_.attenMaskFlag) {
            cuRealAcSeq += 1;
        }
        int32_t cuS2Len = cuBaseS2Idx + s2BaseSize_ >= cuRealAcSeq ? cuRealAcSeq - cuBaseS2Idx : s2BaseSize_;
        int32_t cuS1Idx = cuS1BeginIdxPerAiv + innerS1Idx;
        if (cuRealAcSeq > 0 && cuS2Len > 0) {
            int32_t cuS2LenVecAlign = CeilDiv(cuS2Len, s2BaseSize_) * s2BaseSize_;
            int32_t mmUbStride = (cuS2LenVecAlign - info.actualSingleProcessSInnerSizeAlign) / B32_BLOCK_ALIGN_NUM;
            LocalTensor<float> reduceOutInner = reduceOutBuff[s2BaseSize_];
            PipeBarrier<PIPE_V>();
            LocalTensor<float> reduceCacheBuf = outQueue_.AllocTensor<float>();
            WaitFlag<HardEvent::V_MTE2>(eventIdVToMTE2Tmp);
            for (int outerGidx = 0; outerGidx < outerG; outerGidx++) {
                int32_t procGnum = outerGidx != outerG - 1 ? groupInner_ : gSize_ - outerGidx * groupInner_;
                int32_t pingpong = outerGidx % 2;
                LocalTensor<float> dbTmpUb = tmpUb_[pingpong * (groupInner_ * s2BaseSize_ + s2BaseSize_)];
                LocalTensor<float> weightsInUb = dbTmpUb[procGnum * s2BaseSize_];
                WaitFlag<HardEvent::V_MTE2>(eventIdVToMTE2PingPong[pingpong]);
                LocalTensor<K_T> weightsInTUb = weightsInUb.template ReinterpretCast<K_T>();
                if constexpr (!IsSameType<K_T, float>::value) {
                    weightsInTUb = weightsInTUb[groupInner_];
                }
                LIServiceVec::CopyIn(dbTmpUb,
                                     weightsInTUb,
                                     mm1ResGm,
                                     weightsGm,
                                     mmGmOffset + innerS1Idx * gSize_ * info.actualSingleProcessSInnerSizeAlign +
                                         outerGidx * groupInner_ * info.actualSingleProcessSInnerSizeAlign,
                                     weightGmOffset + innerS1Idx * gSize_ + outerGidx * groupInner_,
                                     procGnum,
                                     info.actualSingleProcessSInnerSizeAlign,
                                     mmUbStride);

                SetFlag<HardEvent::MTE2_V>(eventIdMTE2ToVPingPong[pingpong]);
                WaitFlag<HardEvent::MTE2_V>(eventIdMTE2ToVPingPong[pingpong]);
                weightsInUb = dbTmpUb[procGnum * s2BaseSize_];
                LIServiceVec::DoScale(reduceCacheBuf[REDUCE_BANK_CONFLICT_NUM],
                                      dbTmpUb,
                                      weightsInUb,
                                      weightsInTUb,
                                      brcBuf,
                                      procGnum,
                                      s2BaseSize_,
                                      outerGidx);
                // confused reduceOp in DoScale
                // neednot use LIServiceVec::doReduce(mmInUb, reduceOutInner, procGnum, (s2BaseSize_+8));
                SetFlag<HardEvent::V_MTE2>(eventIdVToMTE2PingPong[pingpong]);
            }

            int32_t gRedCnt = groupInner_ > gSize_ ? gSize_ : groupInner_;
            bool isS2End = cuBaseS2Idx + s2BaseSize_ >= cuRealAcSeq;
            LIServiceVec::DoReduce(reduceCacheBuf[REDUCE_BANK_CONFLICT_NUM], reduceOutInner, gRedCnt, s2BaseSize_);
            outQueue_.FreeTensor(reduceCacheBuf);

            // sparseBlockSize=1 时完全走原始代码逻辑，不引入任何额外开销，恢复原有性能
            if (constInfo_.sparseBlockSize == 1) {
                LocalTensor<float> sortScoreUb = reduceOutBuff;
                LocalTensor<float> sortIndiceUb = reduceOutBuff[cuS2LenVecAlign];
                PipeBarrier<PIPE_V>();
                Duplicate(sortScoreUb.template ReinterpretCast<int32_t>(), LIServiceVec::NEG_INF, cuS2LenVecAlign);
                PipeBarrier<PIPE_V>();
                Adds(sortScoreUb, reduceOutInner, 0.0f, cuS2Len);
                PipeBarrier<PIPE_V>();
                LocalTensor<int32_t> sortIndiceUbInt = sortIndiceUb.template ReinterpretCast<int32_t>();
                // 无效数据索引填充为-1
                if (cuS2LenVecAlign != cuS2Len) {
                    Duplicate(sortIndiceUbInt, -1, cuS2LenVecAlign);
                }
                PipeBarrier<PIPE_V>();
                Adds(sortIndiceUbInt, globalTopkIndice_, static_cast<int32_t>(cuBaseS2Idx), cuS2Len);
                PipeBarrier<PIPE_V>();

                LocalTensor<float> tmpSortBuf = outQueue_.AllocTensor<float>();
                if (info.actS1Size > 4 || constInfo_.sparseCountFlag) {
                    // info.actS1Size > 4 则单个vector核内处理的 s1>2，缓存方案无法处理
                    LIServiceVec::SortAll(reduceOutBuff,
                                          tmpSortBuf,
                                          cuS2LenVecAlign); //  cuS2LenVecAlign <= s2BaseSize_, fill -inf
                    PipeBarrier<PIPE_V>();
                    LIServiceVec::MergeSort(
                        globalTopkUb_[innerS1Idx * virTopK * 2], virTopK, reduceOutBuff, cuS2LenVecAlign, tmpUb_);
                } else {
                    int64_t globalTopkUbCacheIdx = (info.s2Idx - blockS2StartIdx_) % 4;
                    Sort<float, true>(
                        SortedBasicBlock_[innerS1Idx * BASE_TOPK * 2 + globalTopkUbCacheIdx * s2BaseSize_ * 2],
                        reduceOutBuff,
                        sortIndiceUbInt.template ReinterpretCast<uint32_t>(),
                        tmpSortBuf,
                        cuS2LenVecAlign / 32);
                    // 缓存4块512或者S2结束, 需要进行精排
                    if (globalTopkUbCacheIdx == 3 || isS2End || info.isAllLoopEnd) {
                        LocalTensor<float> tt = SortedBasicBlock_[innerS1Idx * BASE_TOPK * 2];
                        // 前4块直接精排覆盖到globalTopkUb_
                        if (info.s2Idx - blockS2StartIdx_ < 4) {
                            MrgBasicBlock(globalTopkUb_[innerS1Idx * BASE_TOPK * 2],
                                          tt,
                                          static_cast<int64_t>(globalTopkUbCacheIdx + 1),
                                          s2BaseSize_);
                        } else { // 后面缓存在 SortedBasicBlock_, 先精排, 再merge到globalTopkUb_
                            if (globalTopkUbCacheIdx > 0) {
                                MrgBasicBlock(
                                    tmpSortBuf, tt, static_cast<int64_t>(globalTopkUbCacheIdx + 1), s2BaseSize_);
                                PipeBarrier<PIPE_V>();
                                DataCopy(SortedBasicBlock_[innerS1Idx * BASE_TOPK * 2],
                                         tmpSortBuf,
                                         (globalTopkUbCacheIdx + 1) * s2BaseSize_ * 2);
                            }
                            PipeBarrier<PIPE_V>();
                            SparseTopK(globalTopkUb_[innerS1Idx * BASE_TOPK * 2],
                                       SortedBasicBlock_[innerS1Idx * BASE_TOPK * 2],
                                       tmpSortBuf,
                                       BASE_TOPK,
                                       s2BaseSize_ * (globalTopkUbCacheIdx + 1));
                        }
                    }
                }
                SetFlag<HardEvent::V_MTE2>(eventIdVToMTE2Tmp);
                PipeBarrier<PIPE_V>();
                outQueue_.FreeTensor(tmpSortBuf);

                bool needCopyOutGm = blockS2StartIdx_ == 0 && isS2End;

                // 中间结果保存
                bool needCopyWsGm = info.isAllLoopEnd || isS2End;

                if (needCopyOutGm) {
                    int64_t offset = (constInfo_.sparseCount <= 4096) ? virTopK : constInfo_.sparseCount / 2;
                    int64_t copyLen =
                        (constInfo_.sparseCount <= 4096) ? constInfo_.sparseCount : constInfo_.sparseCount / 2;
                    int64_t copyNum = (constInfo_.sparseCount <= 4096) ? 1 : 2;
                    for (int64_t i = 0; i < copyNum; i++) {
                        LocalTensor<float> outValueUb = outQueue_.AllocTensor<float>();
                        LocalTensor<uint32_t> outIdxUb = outValueUb[offset].template ReinterpretCast<uint32_t>();
                        Extract(outValueUb,
                                outIdxUb,
                                globalTopkUb_[innerS1Idx * virTopK * 2 + 2 * i * offset],
                                (offset / 32));

                        LocalTensor<K_T> valueULocal1 = outValueUb.template ReinterpretCast<K_T>();
                        if (constInfo_.returnValue) {
                            PipeBarrier<PIPE_V>();
                            Cast(valueULocal1, outValueUb, RoundMode::CAST_ROUND, copyLen);
                            PipeBarrier<PIPE_V>();
                        }

                        LocalTensor<int32_t> idxULocal1 = outValueUb[offset].template ReinterpretCast<int32_t>();
                        outQueue_.EnQue<float>(outValueUb);
                        outValueUb = outQueue_.DeQue<float>();

                        LIServiceVec::CopyOut(
                            indiceOutGm[info.indiceOutOffset + cuS1Idx * constInfo_.sparseCount + i * offset],
                            idxULocal1,
                            copyLen);
                        if (constInfo_.returnValue) {
                            LIServiceVec::CopyOut(
                                valueOutGm[info.indiceOutOffset + cuS1Idx * constInfo_.sparseCount + i * offset],
                                valueULocal1,
                                copyLen);
                        }
                        outQueue_.FreeTensor(outValueUb);
                    }

                } else if (needCopyWsGm) {
                    // vec1Res Gm = [aic, s1BaseSize_, 2, 2, topkOut_] float32
                    // vec1Param Gm = [aic, s1BaseSize_, 2, 16] int64
                    //     16 = [needFd, s2AcSeq, s2Start, s2End, isS2End, bn2idx, s1Idx, S1ProcNum, ......]
                    int64_t wsOffset =
                        (blockId_ / 2) * s1BaseSize_ * 2 * 2 * BASE_TOPK + // 2个AIV共同地址偏移
                        (blockId_ % 2) * (s1BaseSize_ / 2) * 2 * 2 * BASE_TOPK + // 每个AIV的地址偏移，S1方向
                        (ldS1Offset + innerS1Idx) * 2 * 2 * BASE_TOPK;
                    int64_t wsInfoOffset =
                        (blockId_ / 2) * s1BaseSize_ * 2 * paramNum_ + // 2个AIV共同地址偏移
                        (blockId_ % 2) * (s1BaseSize_ / 2) * 2 * paramNum_ + // 每个AIV的地址偏移，S1方向
                        (ldS1Offset + innerS1Idx) * 2 * paramNum_;

                    LocalTensor<int64_t> tmpiBuff = paramBuf_.Get<int64_t>();
                    SetWaitFlag<HardEvent::MTE3_S>(HardEvent::MTE3_S);
                    tmpiBuff.SetValue(0, static_cast<int64_t>(1));
                    tmpiBuff.SetValue(1, static_cast<int64_t>(cuRealAcSeq));
                    tmpiBuff.SetValue(2, static_cast<int64_t>(blockS2StartIdx_));
                    tmpiBuff.SetValue(3, static_cast<int64_t>(cuBaseS2Idx + cuS2Len));
                    tmpiBuff.SetValue(4, static_cast<int64_t>(isS2End));
                    tmpiBuff.SetValue(5, static_cast<int64_t>(info.bN2Idx));
                    tmpiBuff.SetValue(6, static_cast<int64_t>(cuS1Idx));
                    tmpiBuff.SetValue(7, static_cast<int64_t>(cuS1ProcNum));
                    tmpiBuff.SetValue(8, static_cast<int64_t>(info.indiceOutOffset + cuS1Idx * constInfo_.sparseCount));
                    // 写入头尾判断
                    // [head, tail]
                    // head: 与前面规约，与前后规约
                    // tail: 与后面规约
                    bool isTailReduce = blockS2StartIdx_ == 0; // 一定是isLastTile
                    // WS偏移规则 blockS2StartIdx_ != 0
                    // 跟前面块做规约 写到0偏移 不用做计算 blockS2StartIdx_ == 0 and !isS2End
                    // 跟后面块做规约 写到1偏移  需要 + s1BaseSize_, BASE_TOPK*2
                    if (isTailReduce) { // S2不是最后结束的数据就需要往后做规约，放入第二块ws
                        wsInfoOffset += paramNum_;
                        wsOffset += 2 * BASE_TOPK;
                    }
                    SetWaitFlag<HardEvent::S_MTE3>(HardEvent::S_MTE3);
                    LIServiceVec::CopyOut(vec1ParamGm[wsInfoOffset], tmpiBuff, 16);
                    SetWaitFlag<HardEvent::V_MTE3>(HardEvent::V_MTE3);
                    LIServiceVec::CopyOut(
                        vec1ResGm[wsOffset], globalTopkUb_[innerS1Idx * BASE_TOPK * 2], 2 * BASE_TOPK);
                    SetWaitFlag<HardEvent::MTE3_V>(HardEvent::MTE3_V);
                }
            } else {
                // 存blocksize循环处理的中间score值
                LocalTensor<float> reduceMaxBuff = reduceMaxBuf_.Get<float>();

                LocalTensor<float> sortScoreUb = reduceMaxBuff[innerS1Idx * s2BaseSize_];
                PipeBarrier<PIPE_V>();

                // Block逻辑--Reducemax
                uint32_t cuS2Block = CeilDiv(cuS2Len, constInfo_.sparseBlockSize);
                uint32_t cuS2BlockAlign = CeilDiv(cuS2LenVecAlign, constInfo_.sparseBlockSize);

                {
                    LocalTensor<float> reduceTmpBuff = reduceTmpBuf_.Get<float>();
                    Duplicate(reduceTmpBuff.template ReinterpretCast<int32_t>(), LIServiceVec::NEG_INF, s2BaseSize_);
                    PipeBarrier<PIPE_V>();
                    Adds(reduceTmpBuff, reduceOutInner, 0.0f, cuS2Len);
                    PipeBarrier<PIPE_V>();
                    LocalTensor<float> tmpfBuff = outQueue_.AllocTensor<float>();
                    uint32_t s2BlockShape[] = {cuS2Block, constInfo_.sparseBlockSize};
                    constexpr bool isReuse = false;
                    // ReduceMax操作 [[1,s2BaseSize_]] --> [cuS2Block]
                    AscendC::ReduceMax<float, AscendC::Pattern::Reduce::AR, isReuse>(
                        reduceOutInner,
                        reduceTmpBuff,
                        tmpfBuff.template ReinterpretCast<uint8_t>(),
                        s2BlockShape,
                        true);
                    PipeBarrier<PIPE_V>();
                    outQueue_.FreeTensor(tmpfBuff);
                }

                int64_t s2BlockIdx = info.s2Idx % constInfo_.sparseBlockSize;

                if (s2BlockIdx == 0) { // 只有每个block开始初始化分数缓冲区
                    Duplicate(sortScoreUb.template ReinterpretCast<int32_t>(), LIServiceVec::NEG_INF, s2BaseSize_);
                    PipeBarrier<PIPE_V>();
                }

                Adds(sortScoreUb[s2BlockIdx * cuS2BlockAlign], reduceOutInner, 0.0f, cuS2Block);
                PipeBarrier<PIPE_V>();

                if (s2BlockIdx == constInfo_.sparseBlockSize - 1 || isS2End || info.isAllLoopEnd) {
                    // block数量累加到s2basesize或者S2结束，开始进行下面的排序
                    DataCopy(reduceOutBuff, reduceMaxBuff[innerS1Idx * s2BaseSize_], cuS2LenVecAlign);
                    PipeBarrier<PIPE_V>();
                    // 因为G规约需要重复利用索引UB，攒满了再处理索引值
                    LocalTensor<float> sortIndiceUb = reduceOutBuff[cuS2LenVecAlign];
                    LocalTensor<int32_t> sortIndiceUbInt = sortIndiceUb.template ReinterpretCast<int32_t>();
                    if (cuS2LenVecAlign != cuS2Len) {
                        Duplicate(sortIndiceUbInt, -1, cuS2LenVecAlign);
                    }
                    PipeBarrier<PIPE_V>();
                    Adds(sortIndiceUbInt,
                         globalTopkIndice_,
                         static_cast<int32_t>(cuBaseS2BlockIdx),
                         s2BlockIdx * cuS2BlockAlign + cuS2Block);
                    PipeBarrier<PIPE_V>();

                    LocalTensor<float> tmpSortBuf = outQueue_.AllocTensor<float>();
                    if (info.actS1Size > 4 || constInfo_.sparseCountFlag) {
                        // info.actS1Size > 4 则单个vector核内处理的 s1>2，缓存方案无法处理
                        LIServiceVec::SortAll(reduceOutBuff,
                                              tmpSortBuf,
                                              cuS2LenVecAlign); //  cuS2LenVecAlign <= s2BaseSize_, fill -inf
                        PipeBarrier<PIPE_V>();
                        LIServiceVec::MergeSort(
                            globalTopkUb_[innerS1Idx * virTopK * 2], virTopK, reduceOutBuff, cuS2LenVecAlign, tmpUb_);
                    } else {
                        int64_t globalTopkUbCacheIdx = (info.s2Idx - blockS2StartIdx_) % 4;
                        Sort<float, true>(
                            SortedBasicBlock_[innerS1Idx * BASE_TOPK * 2 + globalTopkUbCacheIdx * s2BaseSize_ * 2],
                            reduceOutBuff,
                            sortIndiceUbInt.template ReinterpretCast<uint32_t>(),
                            tmpSortBuf,
                            cuS2LenVecAlign / 32);
                        // 缓存4块512或者S2结束, 需要进行精排
                        if (globalTopkUbCacheIdx == 3 || isS2End || info.isAllLoopEnd) {
                            LocalTensor<float> tt = SortedBasicBlock_[innerS1Idx * BASE_TOPK * 2];
                            // 前4块直接精排覆盖到globalTopkUb_
                            if (info.s2Idx - blockS2StartIdx_ < 4) {
                                MrgBasicBlock(globalTopkUb_[innerS1Idx * BASE_TOPK * 2],
                                              tt,
                                              static_cast<int64_t>(globalTopkUbCacheIdx + 1),
                                              s2BaseSize_);
                            } else { // 后面缓存在 SortedBasicBlock_, 先精排, 再merge到globalTopkUb_
                                if (globalTopkUbCacheIdx > 0) {
                                    MrgBasicBlock(
                                        tmpSortBuf, tt, static_cast<int64_t>(globalTopkUbCacheIdx + 1), s2BaseSize_);
                                    PipeBarrier<PIPE_V>();
                                    DataCopy(SortedBasicBlock_[innerS1Idx * BASE_TOPK * 2],
                                             tmpSortBuf,
                                             (globalTopkUbCacheIdx + 1) * s2BaseSize_ * 2);
                                }
                                PipeBarrier<PIPE_V>();
                                SparseTopK(globalTopkUb_[innerS1Idx * BASE_TOPK * 2],
                                           SortedBasicBlock_[innerS1Idx * BASE_TOPK * 2],
                                           tmpSortBuf,
                                           BASE_TOPK,
                                           s2BaseSize_ * (globalTopkUbCacheIdx + 1));
                            }
                        }
                    }
                    SetFlag<HardEvent::V_MTE2>(eventIdVToMTE2Tmp);
                    PipeBarrier<PIPE_V>();
                    outQueue_.FreeTensor(tmpSortBuf);

                    bool needCopyOutGm = blockS2StartIdx_ == 0 && isS2End;

                    // 中间结果保存
                    bool needCopyWsGm = info.isAllLoopEnd || isS2End;

                    if (needCopyOutGm) {
                        int64_t offset =
                            (constInfo_.realSparseCount <= 4096) ? virTopK : constInfo_.realSparseCount / 2;
                        int64_t copyLen = (constInfo_.realSparseCount <= 4096) ? constInfo_.realSparseCount
                                                                               : constInfo_.realSparseCount / 2;
                        int64_t copyNum = (constInfo_.realSparseCount <= 4096) ? 1 : 2;
                        for (int64_t i = 0; i < copyNum; i++) {
                            LocalTensor<float> outValueUb = outQueue_.AllocTensor<float>();
                            LocalTensor<uint32_t> outIdxUb = outValueUb[offset].template ReinterpretCast<uint32_t>();
                            Extract(outValueUb,
                                    outIdxUb,
                                    globalTopkUb_[innerS1Idx * virTopK * 2 + 2 * i * offset],
                                    (offset / 32));

                            LocalTensor<K_T> valueULocal1 = outValueUb.template ReinterpretCast<K_T>();
                            if (constInfo_.returnValue) {
                                PipeBarrier<PIPE_V>();
                                Cast(valueULocal1, outValueUb, RoundMode::CAST_ROUND, copyLen);
                                PipeBarrier<PIPE_V>();
                            }

                            LocalTensor<int32_t> idxULocal1 = outValueUb[offset].template ReinterpretCast<int32_t>();
                            outQueue_.EnQue<float>(outValueUb);
                            outValueUb = outQueue_.DeQue<float>();

                            LIServiceVec::CopyOut(
                                indiceOutGm[info.indiceOutOffset + cuS1Idx * constInfo_.realSparseCount + i * offset],
                                idxULocal1,
                                copyLen);
                            if (constInfo_.returnValue) {
                                LIServiceVec::CopyOut(valueOutGm[info.indiceOutOffset +
                                                                 cuS1Idx * constInfo_.realSparseCount + i * offset],
                                                      valueULocal1,
                                                      copyLen);
                            }
                            outQueue_.FreeTensor(outValueUb);
                        }

                    } else if (needCopyWsGm) {
                        // vec1Res Gm = [aic, s1BaseSize_, 2, 2, topkOut_] float32
                        // vec1Param Gm = [aic, s1BaseSize_, 2, 16] int64
                        //     16 = [needFd, s2AcSeq, s2Start, s2End, isS2End, bn2idx, s1Idx, S1ProcNum, ......]
                        int64_t wsOffset =
                            (blockId_ / 2) * s1BaseSize_ * 2 * 2 * BASE_TOPK + // 2个AIV共同地址偏移
                            (blockId_ % 2) * (s1BaseSize_ / 2) * 2 * 2 * BASE_TOPK + // 每个AIV的地址偏移，S1方向
                            (ldS1Offset + innerS1Idx) * 2 * 2 * BASE_TOPK;
                        int64_t wsInfoOffset =
                            (blockId_ / 2) * s1BaseSize_ * 2 * paramNum_ + // 2个AIV共同地址偏移
                            (blockId_ % 2) * (s1BaseSize_ / 2) * 2 * paramNum_ + // 每个AIV的地址偏移，S1方向
                            (ldS1Offset + innerS1Idx) * 2 * paramNum_;

                        LocalTensor<int64_t> tmpiBuff = paramBuf_.Get<int64_t>();
                        SetWaitFlag<HardEvent::MTE3_S>(HardEvent::MTE3_S);
                        tmpiBuff.SetValue(0, static_cast<int64_t>(1));
                        tmpiBuff.SetValue(1, static_cast<int64_t>(cuRealAcSeq));
                        tmpiBuff.SetValue(2, static_cast<int64_t>(blockS2StartIdx_));
                        tmpiBuff.SetValue(3, static_cast<int64_t>(cuBaseS2Idx + cuS2Len));
                        tmpiBuff.SetValue(4, static_cast<int64_t>(isS2End));
                        tmpiBuff.SetValue(5, static_cast<int64_t>(info.bN2Idx));
                        tmpiBuff.SetValue(6, static_cast<int64_t>(cuS1Idx));
                        tmpiBuff.SetValue(7, static_cast<int64_t>(cuS1ProcNum));
                        tmpiBuff.SetValue(
                            8, static_cast<int64_t>(info.indiceOutOffset + cuS1Idx * constInfo_.realSparseCount));
                        // 写入头尾判断
                        // [head, tail]
                        // head: 与前面规约，与前后规约
                        // tail: 与后面规约
                        bool isTailReduce = blockS2StartIdx_ == 0; // 一定是isLastTile
                        // WS偏移规则 blockS2StartIdx_ != 0
                        // 跟前面块做规约 写到0偏移 不用做计算 blockS2StartIdx_ == 0 and !isS2End
                        // 跟后面块做规约 写到1偏移  需要 + s1BaseSize_, BASE_TOPK*2
                        if (isTailReduce) { // S2不是最后结束的数据就需要往后做规约，放入第二块ws
                            wsInfoOffset += paramNum_;
                            wsOffset += 2 * BASE_TOPK;
                        }
                        SetWaitFlag<HardEvent::S_MTE3>(HardEvent::S_MTE3);
                        LIServiceVec::CopyOut(vec1ParamGm[wsInfoOffset], tmpiBuff, 16);
                        SetWaitFlag<HardEvent::V_MTE3>(HardEvent::V_MTE3);
                        LIServiceVec::CopyOut(
                            vec1ResGm[wsOffset], globalTopkUb_[innerS1Idx * BASE_TOPK * 2], 2 * BASE_TOPK);
                        SetWaitFlag<HardEvent::MTE3_V>(HardEvent::MTE3_V);
                    }
                } else {
                    SetFlag<HardEvent::V_MTE2>(eventIdVToMTE2Tmp);
                }
            }
        } else if (cuRealAcSeq <= 0) {
            CleanInvalidOutput(info.indiceOutOffset + cuS1Idx * constInfo_.realSparseCount);
        }
    }

    // BNSD场景无效S1 输出-1
    if (LAYOUT_T == LI_LAYOUT::BSND) {
        // 最后一个S1的基本块, 需要 >= info.actS1Size
        bool isS1LoopEnd = (cuBaseS1Idx + s1BaseSize_) >= info.actS1Size;
        int32_t invalidS1Num = constInfo_.qSeqSize - info.actS1Size;
        // blockS2StartIdx_ == 0 控制S2从开始的核去做冗余清理
        if (invalidS1Num > 0 && isS1LoopEnd && blockS2StartIdx_ == 0) {
            int32_t s1NumPerAiv = blockId_ % 2 == 0 ? CeilDiv(invalidS1Num, 2) : (invalidS1Num / 2);
            int32_t s1OffsetPerAiv = info.actS1Size + (blockId_ % 2) * CeilDiv(invalidS1Num, 2);
            for (int innerS1Idx = 0; innerS1Idx < s1NumPerAiv; innerS1Idx++) {
                CleanInvalidOutput(info.indiceOutOffset + (s1OffsetPerAiv + innerS1Idx) * constInfo_.realSparseCount);
            }
        }

        int32_t invalidS1Num2 = info.actS1Size - info.actS2Size;
        if (invalidS1Num2 > 0 && isS1LoopEnd && blockS2StartIdx_ == 0 && constInfo_.attenMaskFlag) {
            int32_t s1NumPerAiv = blockId_ % 2 == 0 ? CeilDiv(invalidS1Num2, 2) : (invalidS1Num2 / 2);
            int32_t s1OffsetPerAiv = (blockId_ % 2) * CeilDiv(invalidS1Num2, 2);
            for (int innerS1Idx = 0; innerS1Idx < s1NumPerAiv; innerS1Idx++) {
                CleanInvalidOutput((info.bN2Idx * constInfo_.qSeqSize + s1OffsetPerAiv + innerS1Idx) *
                                   constInfo_.realSparseCount);
            }
        }
    }

    if (info.isLastS2InnerLoop) {
        // S2最后一个Loop后, 下一个基本块初始从0开始
        blockS2StartIdx_ = 0;
    }
}

template <typename LIT> __aicore__ inline void LIVector<LIT>::ProcessLD()
{
    int32_t curCubeId = blockId_ / 2;
    int32_t tmpCubeId = curCubeId;

    int64_t isS2End;
    uint32_t acc_list_num = 0;
    int64_t needFd;
    int64_t wsOffset;
    int64_t wsInfoOffset = 0;
    int64_t valueOffset = 0;
    int64_t outOffset = 0;

    LocalTensor<float> curValueIdxUb = ldToBeMrgBuf_.Get<float>();
    LocalTensor<float> tmpUb = ldTmpBuf_.Get<float>();

    // S2开头信息
    // 开始必然没有头规约，因此从尾规约开始处理，while循环读取下一个核的头规约
    // 存满4个list或者遇到S2结尾，则做merge，直到做完S2
    // 每个核都忽略自己的头规约，因为必然由前面的核做完
    uint32_t s1LdStartIdx = 0;
    uint32_t s1ProcNum = 0;
    uint64_t paramGmCoreOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_;
    for (uint32_t innerS1Idx = 0; innerS1Idx < s1BaseSize_; innerS1Idx++) {
        needFd = vec1ParamGm.GetValue(paramGmCoreOffset + innerS1Idx * 2 * paramNum_ + paramNum_);
        if (needFd == 1) {
            s1LdStartIdx = (s1ProcNum == 0) ? innerS1Idx : s1LdStartIdx;
            s1ProcNum++;
        }
    }

    if (s1ProcNum == 0) {
        return;
    }

    uint32_t s1VecNum = CeilDiv(s1ProcNum, 2U);
    if (blockId_ % 2 == 1) {
        s1LdStartIdx = s1LdStartIdx + s1VecNum;
        s1VecNum = s1ProcNum - s1VecNum;
    }
    for (uint32_t innerS1Idx = s1LdStartIdx; innerS1Idx < s1LdStartIdx + s1VecNum; innerS1Idx++) {
        tmpCubeId = curCubeId;
        acc_list_num = 0;
        valueOffset = 0;

        wsOffset = tmpCubeId * s1BaseSize_ * 2 * 2 * BASE_TOPK + innerS1Idx * 2 * 2 * BASE_TOPK + 2 * BASE_TOPK;
        SetWaitFlag<HardEvent::V_MTE2>(HardEvent::V_MTE2);
        SetWaitFlag<HardEvent::S_MTE2>(HardEvent::S_MTE2);
        DataCopyPad(curValueIdxUb,
                    vec1ResGm[wsOffset],
                    {1, static_cast<uint16_t>(2 * BASE_TOPK * sizeof(int32_t)), 0, 0},
                    {true, 0, 0, 0});
        acc_list_num++;
        valueOffset += 2 * BASE_TOPK;

        tmpCubeId++;
        wsInfoOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_ + innerS1Idx * 2 * paramNum_;
        needFd = vec1ParamGm.GetValue(wsInfoOffset);
        isS2End = vec1ParamGm.GetValue(wsInfoOffset + 4);
        outOffset = vec1ParamGm.GetValue(wsInfoOffset + 8);

        while (needFd == 1) {
            wsOffset = tmpCubeId * s1BaseSize_ * 2 * 2 * BASE_TOPK + innerS1Idx * 2 * 2 * BASE_TOPK;
            SetWaitFlag<HardEvent::V_MTE2>(HardEvent::V_MTE2);
            SetWaitFlag<HardEvent::S_MTE2>(HardEvent::S_MTE2);
            DataCopyPad(curValueIdxUb[valueOffset],
                        vec1ResGm[wsOffset],
                        {1, static_cast<uint16_t>(2 * BASE_TOPK * sizeof(int32_t)), 0, 0},
                        {true, 0, 0, 0});
            valueOffset += 2 * BASE_TOPK;
            acc_list_num++;

            if (acc_list_num == mrgListNum_) {
                AscendC::MrgSort4Info params;
                params.elementLengths[0] = BASE_TOPK;
                params.elementLengths[1] = BASE_TOPK;
                params.elementLengths[2] = BASE_TOPK;
                params.elementLengths[3] = BASE_TOPK;
                params.ifExhaustedSuspension = true;
                params.validBit = 0b1111;
                params.repeatTimes = 1;

                AscendC::MrgSortSrcList<float> srcList;
                srcList.src1 = curValueIdxUb[0];
                srcList.src2 = curValueIdxUb[2 * BASE_TOPK];
                srcList.src3 = curValueIdxUb[4 * BASE_TOPK];
                srcList.src4 = curValueIdxUb[6 * BASE_TOPK];
                SetWaitFlag<HardEvent::MTE2_V>(HardEvent::MTE2_V);
                MrgSort(tmpUb, srcList, params);
                PipeBarrier<PIPE_V>();
                DataCopy(curValueIdxUb, tmpUb, 2 * BASE_TOPK);
                PipeBarrier<PIPE_V>();
                acc_list_num = 1;
                valueOffset = 2 * BASE_TOPK;
            }

            if (isS2End == 1) {
                break;
            }

            tmpCubeId++;
            wsInfoOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_ + innerS1Idx * 2 * paramNum_;
            needFd = vec1ParamGm.GetValue(wsInfoOffset);
            isS2End = vec1ParamGm.GetValue(wsInfoOffset + 4);
        }

        if (acc_list_num != 1) {
            AscendC::MrgSort4Info params;
            params.elementLengths[0] = BASE_TOPK;
            params.elementLengths[1] = BASE_TOPK;
            params.elementLengths[2] = BASE_TOPK;
            params.elementLengths[3] = BASE_TOPK;
            params.ifExhaustedSuspension = true;
            params.validBit = acc_list_num == 2 ? 0b0011 : 0b0111;
            params.repeatTimes = 1;

            AscendC::MrgSortSrcList<float> srcList;
            srcList.src1 = curValueIdxUb[0];
            srcList.src2 = curValueIdxUb[2 * BASE_TOPK];
            srcList.src3 = curValueIdxUb[4 * BASE_TOPK];
            srcList.src4 = curValueIdxUb[6 * BASE_TOPK];
            SetWaitFlag<HardEvent::MTE2_V>(HardEvent::MTE2_V);
            MrgSort(tmpUb, srcList, params);
            PipeBarrier<PIPE_V>();
            DataCopy(curValueIdxUb, tmpUb, 2 * BASE_TOPK);
            PipeBarrier<PIPE_V>();
        }

        LocalTensor<float> outValueUb = ldOutValueBuf_.Get<float>();
        LocalTensor<uint32_t> outIdxUb = ldOutIdxBuf_.Get<uint32_t>();
        if (!constInfo_.returnValue) {
            Extract(outValueUb, outIdxUb, curValueIdxUb, (BASE_TOPK / 32));
            LocalTensor<int32_t> idxULocal1 = outIdxUb.template ReinterpretCast<int32_t>();
            SetWaitFlag<HardEvent::V_MTE3>(HardEvent::V_MTE3);
            SetWaitFlag<HardEvent::S_MTE3>(HardEvent::S_MTE3);
            DataCopyPad(indiceOutGm[outOffset],
                        idxULocal1,
                        {1, static_cast<uint16_t>(constInfo_.realSparseCount * sizeof(int32_t)), 0, 0});
            SetWaitFlag<HardEvent::MTE3_V>(HardEvent::MTE3_V);
        } else {
            Extract(outValueUb, outIdxUb, curValueIdxUb, (BASE_TOPK / 32));
            PipeBarrier<PIPE_V>();
            LocalTensor<int32_t> idxULocal1 = outIdxUb.template ReinterpretCast<int32_t>();
            LocalTensor<K_T> valueULocal1 = outValueUb.template ReinterpretCast<K_T>();
            Cast(valueULocal1, outValueUb, RoundMode::CAST_ROUND, constInfo_.realSparseCount);
            PipeBarrier<PIPE_V>();
            SetWaitFlag<HardEvent::V_MTE3>(HardEvent::V_MTE3);
            SetWaitFlag<HardEvent::S_MTE3>(HardEvent::S_MTE3);
            DataCopyPad(indiceOutGm[outOffset],
                        idxULocal1,
                        {1, static_cast<uint16_t>(constInfo_.realSparseCount * sizeof(int32_t)), 0, 0});
            DataCopyPad(valueOutGm[outOffset],
                        valueULocal1,
                        {1, static_cast<uint16_t>(constInfo_.realSparseCount * sizeof(K_T)), 0, 0});
            SetWaitFlag<HardEvent::MTE3_V>(HardEvent::MTE3_V);
        }
    }
}

template <typename LIT>
__aicore__ inline void
LIVector<LIT>::ProcessAverageLD(uint32_t ldFirstCubeId, uint32_t ldCoreRank, uint32_t ldTotalCores)
{
    int32_t curCubeId = static_cast<int32_t>(ldFirstCubeId);
    int32_t tmpCubeId = curCubeId;

    int64_t isS2End;
    int64_t bn2Idx;
    int64_t s1Idx;
    uint32_t acc_list_num = 0;
    int64_t needFd;
    int64_t wsOffset;
    int64_t wsInfoOffset = 0;
    int64_t valueOffset = 0;
    int64_t outOffset = 0;

    LocalTensor<float> curValueIdxUb = ldToBeMrgBuf_.Get<float>();
    LocalTensor<float> tmpUb = ldTmpBuf_.Get<float>();

    // S2开头信息
    // 开始必然没有头规约，因此从尾规约开始处理，while循环读取下一个核的头规约
    // 存满4个list或者遇到S2结尾，则做merge，直到做完S2
    // 每个核都忽略自己的头规约，因为必然由前面的核做完
    uint32_t s1LdStartIdx = 0;
    uint32_t s1ProcNum = 0;
    uint64_t paramGmCoreOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_;
    for (uint32_t innerS1Idx = 0; innerS1Idx < s1BaseSize_; innerS1Idx++) {
        needFd = vec1ParamGm.GetValue(paramGmCoreOffset + innerS1Idx * 2 * paramNum_ + paramNum_);
        if (needFd == 1) {
            s1LdStartIdx = (s1ProcNum == 0) ? innerS1Idx : s1LdStartIdx;
            s1ProcNum++;
        }
    }

    if (s1ProcNum == 0) {
        return;
    }
    // SplitCore 侧只提供了参与核数的上界。
    // 某些边界核虽然仍保留了当前 group 的头片段，但尾片段已经被后续 group 复用，
    // 如果仍按静态 ldTotalCores 分行，会把部分行分给实际上不再属于当前 group 的核。
    // 这里按最长行链重新扫描工作区，把参与核数收敛到解码阶段真实可见的数量。
    uint32_t maxLdCoresByRow = CeilDiv(s1ProcNum, 2U);
    uint32_t effectiveLdCores = (ldTotalCores < maxLdCoresByRow) ? ldTotalCores : maxLdCoresByRow;
    if (effectiveLdCores == 0) {
        return;
    }

    uint32_t lastLdRowIdx = s1LdStartIdx + s1ProcNum - 1;
    int64_t lastRowBn2Idx = 0;
    int64_t lastRowS1Idx = 0;
    int64_t lastRowOutOffset = 0;
    int64_t candidateTailNeedFd = 0;
    int64_t candidateTailBn2Idx = 0;
    int64_t candidateTailS1Idx = 0;
    int64_t candidateTailOutOffset = 0;
    wsInfoOffset = curCubeId * s1BaseSize_ * 2 * paramNum_ + lastLdRowIdx * 2 * paramNum_ + paramNum_;
    lastRowBn2Idx = vec1ParamGm.GetValue(wsInfoOffset + 5);
    lastRowS1Idx = vec1ParamGm.GetValue(wsInfoOffset + 6);
    lastRowOutOffset = vec1ParamGm.GetValue(wsInfoOffset + 8);
    uint32_t scannedLdCores = 1;
    tmpCubeId = curCubeId;
    while (scannedLdCores < effectiveLdCores) {
        tmpCubeId++;
        wsInfoOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_ + lastLdRowIdx * 2 * paramNum_;
        needFd = vec1ParamGm.GetValue(wsInfoOffset);
        bn2Idx = vec1ParamGm.GetValue(wsInfoOffset + 5);
        s1Idx = vec1ParamGm.GetValue(wsInfoOffset + 6);
        outOffset = vec1ParamGm.GetValue(wsInfoOffset + 8);
        if (needFd != 1 || bn2Idx != lastRowBn2Idx || s1Idx != lastRowS1Idx || outOffset != lastRowOutOffset) {
            break;
        }
        // 边界核可能仍在 slot0 保留当前 group 的头片段，但 slot1 已经写入下一个 gS1 group 的尾片段。
        // 这种核不能继续计入当前 group 的 LD 参与者，否则会把当前行分配给下一个 group 的归约执行者。
        int64_t candidateTailWsInfoOffset =
            tmpCubeId * s1BaseSize_ * 2 * paramNum_ + lastLdRowIdx * 2 * paramNum_ + paramNum_;
        candidateTailNeedFd = vec1ParamGm.GetValue(candidateTailWsInfoOffset);
        candidateTailBn2Idx = vec1ParamGm.GetValue(candidateTailWsInfoOffset + 5);
        candidateTailS1Idx = vec1ParamGm.GetValue(candidateTailWsInfoOffset + 6);
        candidateTailOutOffset = vec1ParamGm.GetValue(candidateTailWsInfoOffset + 8);
        if (candidateTailNeedFd == 1 && (candidateTailBn2Idx != lastRowBn2Idx || candidateTailS1Idx != lastRowS1Idx ||
                                         candidateTailOutOffset != lastRowOutOffset)) {
            break;
        }
        scannedLdCores++;
        isS2End = vec1ParamGm.GetValue(wsInfoOffset + 4);
        if (isS2End == 1) {
            break;
        }
    }
    effectiveLdCores = scannedLdCores;
    if (ldCoreRank >= effectiveLdCores) {
        return;
    }

    uint32_t totalAivs = effectiveLdCores * 2;
    uint32_t aivRank = ldCoreRank * 2 + (blockId_ % 2); // 当前 AIV 在该 LD 任务中的全局序号
    uint32_t baseRows = s1ProcNum / totalAivs;
    uint32_t extraRows = s1ProcNum % totalAivs;
    uint32_t myStartOffset = aivRank * baseRows + ((aivRank < extraRows) ? aivRank : extraRows);
    uint32_t s1VecNum = baseRows + ((aivRank < extraRows) ? 1 : 0);
    s1LdStartIdx = s1LdStartIdx + myStartOffset;
    for (uint32_t innerS1Idx = s1LdStartIdx; innerS1Idx < s1LdStartIdx + s1VecNum; innerS1Idx++) {
        // 重置偏移
        tmpCubeId = curCubeId;
        acc_list_num = 0;
        valueOffset = 0;
        int64_t expectedBn2Idx = 0;
        int64_t expectedS1Idx = 0;
        int64_t expectedOutOffset = 0;

        // 搬入数据
        wsOffset = tmpCubeId * s1BaseSize_ * 2 * 2 * BASE_TOPK + // 2个AIV共同地址偏移
                   innerS1Idx * 2 * 2 * BASE_TOPK + 2 * BASE_TOPK;
        SetWaitFlag<HardEvent::V_MTE2>(HardEvent::V_MTE2);
        SetWaitFlag<HardEvent::S_MTE2>(HardEvent::S_MTE2);
        DataCopyPad(curValueIdxUb,
                    vec1ResGm[wsOffset],
                    {1, static_cast<uint16_t>(2 * BASE_TOPK * sizeof(int32_t)), 0, 0},
                    {true, 0, 0, 0});
        acc_list_num++;
        valueOffset += 2 * BASE_TOPK;
        wsInfoOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_ + innerS1Idx * 2 * paramNum_ + paramNum_;
        expectedBn2Idx = vec1ParamGm.GetValue(wsInfoOffset + 5);
        expectedS1Idx = vec1ParamGm.GetValue(wsInfoOffset + 6);
        expectedOutOffset = vec1ParamGm.GetValue(wsInfoOffset + 8);
        outOffset = expectedOutOffset;

        // 获取下一个核规约信息
        tmpCubeId++;
        wsInfoOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_ + innerS1Idx * 2 * paramNum_;
        needFd = vec1ParamGm.GetValue(wsInfoOffset);
        isS2End = vec1ParamGm.GetValue(wsInfoOffset + 4);
        bn2Idx = vec1ParamGm.GetValue(wsInfoOffset + 5);
        s1Idx = vec1ParamGm.GetValue(wsInfoOffset + 6);
        outOffset = vec1ParamGm.GetValue(wsInfoOffset + 8);

        while (needFd == 1 && bn2Idx == expectedBn2Idx && s1Idx == expectedS1Idx && outOffset == expectedOutOffset) {
            // 搬入头规约数据
            wsOffset = tmpCubeId * s1BaseSize_ * 2 * 2 * BASE_TOPK + // 2个AIV共同地址偏移
                       innerS1Idx * 2 * 2 * BASE_TOPK;
            SetWaitFlag<HardEvent::V_MTE2>(HardEvent::V_MTE2);
            SetWaitFlag<HardEvent::S_MTE2>(HardEvent::S_MTE2);
            DataCopyPad(curValueIdxUb[valueOffset],
                        vec1ResGm[wsOffset],
                        {1, static_cast<uint16_t>(2 * BASE_TOPK * sizeof(int32_t)), 0, 0},
                        {true, 0, 0, 0});
            valueOffset += 2 * BASE_TOPK;
            acc_list_num++;

            // 每满4个list，聚合  前2K为mrg结果
            if (acc_list_num == mrgListNum_) {
                // MrgSort 四条2048的队列，Mrg成一条
                AscendC::MrgSort4Info params;
                params.elementLengths[0] = BASE_TOPK;
                params.elementLengths[1] = BASE_TOPK;
                params.elementLengths[2] = BASE_TOPK;
                params.elementLengths[3] = BASE_TOPK;
                params.ifExhaustedSuspension = true;
                params.validBit = 0b1111;
                params.repeatTimes = 1;

                AscendC::MrgSortSrcList<float> srcList;
                srcList.src1 = curValueIdxUb[0];
                srcList.src2 = curValueIdxUb[2 * BASE_TOPK];
                srcList.src3 = curValueIdxUb[4 * BASE_TOPK];
                srcList.src4 = curValueIdxUb[6 * BASE_TOPK];
                SetWaitFlag<HardEvent::MTE2_V>(HardEvent::MTE2_V);
                MrgSort(tmpUb, srcList, params);
                PipeBarrier<PIPE_V>();
                DataCopy(curValueIdxUb, tmpUb, 2 * BASE_TOPK);
                PipeBarrier<PIPE_V>();
                acc_list_num = 1;
                valueOffset = 2 * BASE_TOPK;
            }

            // reduce到S2末尾，则跳出
            if (isS2End == 1) {
                break;
            }

            tmpCubeId++;
            wsInfoOffset = tmpCubeId * s1BaseSize_ * 2 * paramNum_ + innerS1Idx * 2 * paramNum_;
            needFd = vec1ParamGm.GetValue(wsInfoOffset);
            isS2End = vec1ParamGm.GetValue(wsInfoOffset + 4);
            bn2Idx = vec1ParamGm.GetValue(wsInfoOffset + 5);
            s1Idx = vec1ParamGm.GetValue(wsInfoOffset + 6);
            outOffset = vec1ParamGm.GetValue(wsInfoOffset + 8);
        }

        // mrg不足4个list的数据
        if (acc_list_num != 1) {
            AscendC::MrgSort4Info params;
            params.elementLengths[0] = BASE_TOPK;
            params.elementLengths[1] = BASE_TOPK;
            params.elementLengths[2] = BASE_TOPK;
            params.elementLengths[3] = BASE_TOPK;
            params.ifExhaustedSuspension = true;
            params.validBit = acc_list_num == 2 ? 0b0011 : 0b0111;
            params.repeatTimes = 1;

            AscendC::MrgSortSrcList<float> srcList;
            srcList.src1 = curValueIdxUb[0];
            srcList.src2 = curValueIdxUb[2 * BASE_TOPK];
            srcList.src3 = curValueIdxUb[4 * BASE_TOPK];
            srcList.src4 = curValueIdxUb[6 * BASE_TOPK];
            SetWaitFlag<HardEvent::MTE2_V>(HardEvent::MTE2_V);
            MrgSort(tmpUb, srcList, params);
            PipeBarrier<PIPE_V>();
            DataCopy(curValueIdxUb, tmpUb, 2 * BASE_TOPK);
            PipeBarrier<PIPE_V>();
        }

        // 搬出
        LocalTensor<float> outValueUb = ldOutValueBuf_.Get<float>();
        LocalTensor<uint32_t> outIdxUb = ldOutIdxBuf_.Get<uint32_t>();
        if (!constInfo_.returnValue) {
            Extract(outValueUb, outIdxUb, curValueIdxUb, (BASE_TOPK / 32));
            LocalTensor<int32_t> idxULocal1 = outIdxUb.template ReinterpretCast<int32_t>();
            SetWaitFlag<HardEvent::V_MTE3>(HardEvent::V_MTE3);
            SetWaitFlag<HardEvent::S_MTE3>(HardEvent::S_MTE3);
            DataCopyPad(indiceOutGm[outOffset],
                        idxULocal1,
                        {1, static_cast<uint16_t>(constInfo_.realSparseCount * sizeof(int32_t)), 0, 0});
            SetWaitFlag<HardEvent::MTE3_V>(HardEvent::MTE3_V);
        } else {
            Extract(outValueUb, outIdxUb, curValueIdxUb, (BASE_TOPK / 32));
            PipeBarrier<PIPE_V>();
            LocalTensor<int32_t> idxULocal1 = outIdxUb.template ReinterpretCast<int32_t>();
            LocalTensor<K_T> valueULocal1 = outValueUb.template ReinterpretCast<K_T>();
            Cast(valueULocal1, outValueUb, RoundMode::CAST_ROUND, constInfo_.realSparseCount);
            PipeBarrier<PIPE_V>();
            SetWaitFlag<HardEvent::V_MTE3>(HardEvent::V_MTE3);
            SetWaitFlag<HardEvent::S_MTE3>(HardEvent::S_MTE3);
            DataCopyPad(indiceOutGm[outOffset],
                        idxULocal1,
                        {1, static_cast<uint16_t>(constInfo_.realSparseCount * sizeof(int32_t)), 0, 0});
            DataCopyPad(valueOutGm[outOffset],
                        valueULocal1,
                        {1, static_cast<uint16_t>(constInfo_.realSparseCount * sizeof(K_T)), 0, 0});
            SetWaitFlag<HardEvent::MTE3_V>(HardEvent::MTE3_V);
        }
    }
}
