24	constexpr int32_t NEG_INF = 0xFF800000;
25	constexpr int32_t INVALID_INDEX = -1;
26	constexpr uint8_t VEC_REPEAT_MAX = 255;
27	constexpr uint8_t B32_VEC_ELM_NUM = 64;
28	constexpr uint8_t B32_BLOCK_ALIGN_NUM = 8;
29	constexpr uint8_t B32_VEC_REPEAT_STRIDE = 8;
30	constexpr uint64_t VEC_REPEAT_BYTES = 256;
31	constexpr int32_t CONST_TWO = 2;
32	constexpr int64_t VALUE_AND_INDEX_NUM = 2;
33	constexpr int64_t BLOCK_BYTES = 32;
34	constexpr int64_t MRG_QUE_0 = 0;
35	constexpr int64_t MRG_QUE_1 = 1;
36	constexpr int64_t MRG_QUE_2 = 2;
37	constexpr int64_t MRG_QUE_3 = 3;
38	constexpr int64_t MRG_BLOCK_2 = 2;
39	constexpr int64_t MRG_BLOCK_3 = 3;
40	constexpr int64_t MRG_BLOCK_4 = 4;
41	
42	template <typename T>
43	__aicore__ inline void CopyIn(LocalTensor<float> &mmOutUb, LocalTensor<T> &weightsUb, GlobalTensor<float> &mMoutGm,
44	                              GlobalTensor<T> &weightScaleGm, int64_t MMout_gmoffset, int64_t weights_gmoffset,
45	                              int64_t groupInner, int64_t s2Inner, int64_t mmUbStride)
46	{
47	    // 将MMout_gmoffset copy到UB上
48	    AscendC::DataCopyPadExtParams<float> padParams{false, 0, 0, 0};
49	    AscendC::DataCopyExtParams dataCopymMoutParams;
50	    dataCopymMoutParams.blockCount = groupInner;
51	    dataCopymMoutParams.blockLen = s2Inner * sizeof(float);
52	    dataCopymMoutParams.srcStride = 0;
53	    dataCopymMoutParams.dstStride = mmUbStride;
54	    dataCopymMoutParams.rsv = 0;
55	    AscendC::DataCopyPad(mmOutUb, mMoutGm[MMout_gmoffset], dataCopymMoutParams, padParams);
56	
57	    // 将weights_gmoffset copy到UB
58	    AscendC::DataCopyPadExtParams<T> padTParams{false, 0, 0, 0};
59	    AscendC::DataCopyExtParams dataCopyweightParams;
60	    dataCopyweightParams.blockCount = 1;
61	    dataCopyweightParams.blockLen = groupInner * sizeof(T);
62	    dataCopyweightParams.srcStride = 0;
63	    dataCopyweightParams.dstStride = 0;
64	    dataCopyweightParams.rsv = 0;
65	    AscendC::DataCopyPad(weightsUb, weightScaleGm[weights_gmoffset], dataCopyweightParams, padTParams);
66	}
