68	
69	template <typename T>
70	__aicore__ inline void CopyOut(const GlobalTensor<T> &dstGm, const LocalTensor<T> &srcUb, int64_t copyCount)
71	{
72	    AscendC::DataCopyParams dataCopyOutyParams;
73	    dataCopyOutyParams.blockCount = 1;
74	    dataCopyOutyParams.blockLen = copyCount * sizeof(T);
75	    dataCopyOutyParams.srcStride = 0;
76	    dataCopyOutyParams.dstStride = 0;
77	    AscendC::DataCopyPad(dstGm, srcUb, dataCopyOutyParams);
78	}
