81	template <typename T>
82	__aicore__ inline void DoScale(const LocalTensor<float> &reduceCacheBuf, LocalTensor<float> &mmOutUb,
83	                               LocalTensor<float> &weightsUb, LocalTensor<T> &weightsTUb, LocalTensor<float> &tmpBuff,
84	                               int64_t groupInner, int64_t s2Inner, int32_t outerGidx)
85	{
86	    // cast bfloat16_t to float
87	    if constexpr (!IsSameType<T, float>::value) {
88	        AscendC::Cast(weightsUb, weightsTUb, RoundMode::CAST_NONE, groupInner);
89	        AscendC::PipeBarrier<PIPE_V>();
90	    }
91	
92	    // weight broadcast: [groupInner, 1] -> [groupInner, 8]
93	    AscendC::Brcb(tmpBuff, weightsUb, LICommon::CeilDiv(groupInner, static_cast<int64_t>(B32_BLOCK_ALIGN_NUM)),
94	                  {1, B32_VEC_REPEAT_STRIDE});
95	    AscendC::PipeBarrier<PIPE_V>();
96	
97	    // do scale: [groupInner, 8] * [groupInner, s2Inner]
98	    uint64_t countPerRepeat = VEC_REPEAT_BYTES / sizeof(float);
99	    uint64_t repeatTimes = s2Inner / countPerRepeat;
100	    for (int32_t i = 0; i < groupInner; i++) {
101	        if (outerGidx == 0) {
102	            AscendC::Mul(reduceCacheBuf[i * s2Inner], mmOutUb[i * s2Inner], tmpBuff[i * B32_BLOCK_ALIGN_NUM],
103	                         countPerRepeat, repeatTimes, {1, 1, 0, B32_VEC_REPEAT_STRIDE, B32_VEC_REPEAT_STRIDE, 0});
104	        } else {
105	            AscendC::Mul(mmOutUb[i * s2Inner], mmOutUb[i * s2Inner], tmpBuff[i * B32_BLOCK_ALIGN_NUM], countPerRepeat,
106	                         repeatTimes, {1, 1, 0, B32_VEC_REPEAT_STRIDE, B32_VEC_REPEAT_STRIDE, 0});
107	        }
108	    }
109	
110	    if (outerGidx != 0) {
111	        AscendC::PipeBarrier<PIPE_V>();
112	        AscendC::Add(reduceCacheBuf, mmOutUb, reduceCacheBuf, groupInner * s2Inner);
113	    }
114	    AscendC::PipeBarrier<PIPE_V>();
115	}
