117	
118	__aicore__ inline uint64_t FindNearestPower2(uint64_t value)
119	{
120	    if (value <= CONST_TWO) {
121	        return value;
122	    } else {
123	        const uint64_t pow = 63 - clz(value); // clz返回前导0的个数，对于64位整数，最大有效位位置 = 63 - 前导0个数
124	        return (1 << pow);
125	    }
126	}
