128	
129	// dstTensor 需要初始化0
130	__aicore__ inline void DoReduce(const LocalTensor<float> &srcTensor, LocalTensor<float> &dstTensor, int32_t rNum,
131	                                int32_t aNum)
132	{
133	    if (rNum == 1) {
134	        AscendC::Adds<float>(dstTensor, srcTensor, 0, aNum);
135	        AscendC::PipeBarrier<PIPE_V>();
136	        return;
137	    }
138	
139	    uint32_t dichotomizeAddPow = FindNearestPower2(rNum);
140	    uint32_t dichotomizeAddDiffSize = rNum - dichotomizeAddPow;
141	    if (dichotomizeAddDiffSize != 0) {
142	        AscendC::Add(srcTensor, srcTensor, srcTensor[dichotomizeAddPow * aNum], dichotomizeAddDiffSize * aNum);
143	        AscendC::PipeBarrier<PIPE_V>();
144	    }
145	    int32_t nowRows = dichotomizeAddPow;
146	    while (nowRows > CONST_TWO) {
147	        nowRows = nowRows / CONST_TWO;
148	        AscendC::Add(srcTensor, srcTensor, srcTensor[nowRows * aNum], nowRows * aNum);
149	        AscendC::PipeBarrier<PIPE_V>();
150	    }
151	    AscendC::Add(dstTensor, srcTensor, srcTensor[aNum], aNum);
152	    AscendC::PipeBarrier<PIPE_V>();
153	}
154	
155	
156	/**
157	  src: 传入的初始化空间
158	  eleNum: 需要初始化的元素个数需为64整数倍，元素将被初始化为交错排布的-inf，-1
159	 */
160	__aicore__ inline void InitSortOutBuf(const LocalTensor<float> &src, int64_t eleNum)
161	{
162	    uint64_t mask1[2] = {0x5555555555555555, 0};
163	    uint64_t mask0[2] = {0xaaaaaaaaaaaaaaaa, 0};
164	    int64_t repeatNum = eleNum / B32_VEC_ELM_NUM;
165	    int64_t forLoop = repeatNum / VEC_REPEAT_MAX;
166	    int64_t forRemain = repeatNum % VEC_REPEAT_MAX;
167	    for (int i = 0; i < forLoop; i++) {
168	        AscendC::Duplicate(src.template ReinterpretCast<int32_t>(), NEG_INF, mask1, VEC_REPEAT_MAX, 1,
169	                           B32_VEC_REPEAT_STRIDE);
170	        AscendC::Duplicate(src.template ReinterpretCast<int32_t>(), INVALID_INDEX, mask0, VEC_REPEAT_MAX, 1,
171	                           B32_VEC_REPEAT_STRIDE);
172	    }
173	    if (forRemain > 0) {
174	        AscendC::Duplicate(src.template ReinterpretCast<int32_t>()[forLoop * VEC_REPEAT_MAX * B32_VEC_ELM_NUM], NEG_INF,
175	                           mask1, forRemain, 1, B32_VEC_REPEAT_STRIDE);
176	        AscendC::Duplicate(src.template ReinterpretCast<int32_t>()[forLoop * VEC_REPEAT_MAX * B32_VEC_ELM_NUM],
177	                           INVALID_INDEX, mask0, forRemain, 1, B32_VEC_REPEAT_STRIDE);
178	    }
179	    AscendC::PipeBarrier<PIPE_V>();
180	}
181	
182	
183	/**
184	  src: logits和索引，前logitsNum为logits，后logitsNum为索引
185	  tmp: 计算使用到的临时空间，大小与src一致
186	  logitsNum: 排序的元素个数, 暂只支持[128,256,384,512,1024,2048]
187	 */
188	__aicore__ inline void SortAll(LocalTensor<float> &src, LocalTensor<float> &tmp, int64_t logitsNum)
189	{
190	    int64_t sort32Repeats = logitsNum / BLOCK_BYTES;
191	    AscendC::Sort32(tmp, src, src[logitsNum].ReinterpretCast<uint32_t>(), sort32Repeats);
192	    AscendC::PipeBarrier<PIPE_V>();
193	
194	    int64_t mrgGroups = sort32Repeats;
195	    int64_t mrgElements = BLOCK_BYTES;
196	    int64_t i = 0;
197	    AscendC::LocalTensor<float> srcTensor;
198	    AscendC::LocalTensor<float> dstTensor;
199	    while (true) {
200	        if (i % CONST_TWO == 0) {
201	            srcTensor = tmp;
202	            dstTensor = src;
203	        } else {
204	            srcTensor = src;
205	            dstTensor = tmp;
206	        }
207	        AscendC::MrgSort4Info params;
208	        params.elementLengths[0] = mrgElements;
209	        params.elementLengths[MRG_QUE_1] = mrgElements;
210	        params.elementLengths[MRG_QUE_2] = mrgElements;
211	        params.elementLengths[MRG_QUE_3] = mrgElements;
212	        params.ifExhaustedSuspension = false;
213	        params.validBit = 0b1111;
214	
215	        AscendC::MrgSortSrcList<float> srcList;
216	        srcList.src1 = srcTensor[0];
217	        srcList.src2 = srcTensor[MRG_QUE_1 * VALUE_AND_INDEX_NUM * mrgElements];
218	        srcList.src3 = srcTensor[MRG_QUE_2 * VALUE_AND_INDEX_NUM * mrgElements];
219	        srcList.src4 = srcTensor[MRG_QUE_3 * VALUE_AND_INDEX_NUM * mrgElements];
220	        if (mrgGroups <= MRG_BLOCK_4) {
221	            params.repeatTimes = 1;
222	            if (mrgGroups == 1) {
223	                break;
224	            } else if (mrgGroups == MRG_BLOCK_2) {
225	                params.validBit = 0b0011;
226	            } else if (mrgGroups == MRG_BLOCK_3) {
227	                params.validBit = 0b0111;
228	            } else if (mrgGroups == MRG_BLOCK_4) {
229	                params.validBit = 0b1111;
230	            }
231	            AscendC::MrgSort<float>(dstTensor, srcList, params);
232	            i += 1;
233	            break;
234	        } else {
235	            params.repeatTimes = mrgGroups / MRG_BLOCK_4;
236	            AscendC::MrgSort<float>(dstTensor, srcList, params);
237	            i += 1;
238	            mrgElements = mrgElements * MRG_BLOCK_4;
239	            mrgGroups = mrgGroups / MRG_BLOCK_4;
240	        }
241	        AscendC::PipeBarrier<PIPE_V>();
242	    }
243	    if (i % CONST_TWO == 0) {
244	        AscendC::DataCopy(src, tmp, logitsNum * VALUE_AND_INDEX_NUM);
245	        AscendC::PipeBarrier<PIPE_V>();
246	    }
247	}
248	
249	
250	/**
251	  dst: 输出全排序的结果，排布方式为value，index
252	  srcValue：输入的待排序浮点数
253	  srcIndex：浮点数的索引
254	  tmp: 计算使用到的临时空间，大小为srcValue+srcIndex
255	  logitsNum: 排序的元素个数
256	 */
257	__aicore__ inline void SortAll(LocalTensor<float> &dst, LocalTensor<float> &srcValue, LocalTensor<uint32_t> &srcIndex,
258	                               LocalTensor<float> &tmpTensor, int64_t logitsNum)
259	{
260	    int64_t sort32Repeats = logitsNum / BLOCK_BYTES;
261	    AscendC::Sort<float, true>(dst, srcValue, srcIndex, tmpTensor, sort32Repeats);
262	    AscendC::PipeBarrier<PIPE_V>();
263	}
264	
265	
266	/**
267	  mrgDst: 合并进的Tensor
268	  mrgSrc: 待合并的Tensor
269	  tmpTensor：空间为mrgDst+mrgSrc
270	 */
271	__aicore__ inline void MergeSort(const LocalTensor<float> &mrgDst, int32_t mrgDstNum, LocalTensor<float> &mrgSrc,
272	                                 int32_t mrgSrcNum, LocalTensor<float> &tmpTensor)
273	{
274	    if (mrgDstNum <= 3072) {
275	        AscendC::MrgSort4Info params;
276	        params.elementLengths[0] = mrgDstNum;
277	        params.elementLengths[1] = mrgSrcNum;
278	        params.ifExhaustedSuspension = false;
279	        params.validBit = 0b0011;
280	        params.repeatTimes = 1;
281	
282	        AscendC::MrgSortSrcList<float> srcList;
283	        srcList.src1 = mrgDst;
284	        srcList.src2 = mrgSrc;
285	
286	        AscendC::MrgSort<float>(tmpTensor, srcList, params);
287	        AscendC::PipeBarrier<PIPE_V>();
288	        AscendC::DataCopy(mrgDst, tmpTensor, mrgDstNum * VALUE_AND_INDEX_NUM);
289	        AscendC::PipeBarrier<PIPE_V>();
290	    } else {
291	        int64_t unitElements = 1024;
292	        int64_t segNum = mrgDstNum / unitElements;
293	        int64_t mrgQuelen_1 = (segNum + 2) / 3;
294	        int64_t mrgQuelen_2 = ((segNum - mrgQuelen_1) + 1) / 2;
295	        int64_t mrgQuelen_3 = segNum - mrgQuelen_1 - mrgQuelen_2;
296	
297	        AscendC::MrgSort4Info params;
298	        params.elementLengths[0] = mrgQuelen_1 * unitElements;
299	        params.elementLengths[1] = mrgQuelen_2 * unitElements;
300	        params.elementLengths[2] = mrgQuelen_3 * unitElements;
301	        params.elementLengths[3] = mrgSrcNum;
302	
303	        params.ifExhaustedSuspension = false;
304	        params.validBit = 0b1111;
305	        params.repeatTimes = 1;
306	
307	        AscendC::MrgSortSrcList<float> srcList;
308	        srcList.src1 = mrgDst[0];
309	        srcList.src2 = mrgDst[mrgQuelen_1 * VALUE_AND_INDEX_NUM * unitElements];
310	        srcList.src3 = mrgDst[(mrgQuelen_1 + mrgQuelen_2) * VALUE_AND_INDEX_NUM * unitElements];
311	        srcList.src4 = mrgSrc;
312	
313	        AscendC::MrgSort<float>(tmpTensor, srcList, params);
314	        AscendC::PipeBarrier<PIPE_V>();
315	        AscendC::DataCopy(mrgDst, tmpTensor, mrgDstNum * VALUE_AND_INDEX_NUM);
316	        AscendC::PipeBarrier<PIPE_V>();
317	    }
318	}
319	
320	
321	/**
322	 * @brief 合并基础块函数
323	 * @param dst 归并后的输出, 大小为blockNum * basicBlockSize * 2 * sizeof(float)
324	 * @param src 基本块输入
325	 * @param blockNum 基本块的数量
326	 * @param basicBlockSize 基础块的大小
327	 * @return 无
328	 */
329	__aicore__ inline void MrgBasicBlock(const LocalTensor<float> &dst, const LocalTensor<float> &src, int64_t blockNum,
330	                                     int64_t basicBlockSize)
331	{
332	    // 初始化合并排序参数
333	    AscendC::MrgSort4Info params;
334	    params.elementLengths[MRG_QUE_0] = basicBlockSize;
335	    params.elementLengths[MRG_QUE_1] = basicBlockSize;
336	    params.elementLengths[MRG_QUE_2] = basicBlockSize;
337	    params.elementLengths[MRG_QUE_3] = basicBlockSize;
338	    params.ifExhaustedSuspension = false;
339	    // 根据块的数量设置有效位
340	    if (blockNum == MRG_BLOCK_2) {
341	        params.validBit = 0b0011;
342	    } else if (blockNum == MRG_BLOCK_3) {
343	        params.validBit = 0b0111;
344	    } else if (blockNum == MRG_BLOCK_4) {
345	        params.validBit = 0b1111;
346	    } else {
347	        AscendC::DataCopy(dst, src, basicBlockSize * VALUE_AND_INDEX_NUM);
348	        return;
349	    }
350	    // 初始化源列表
351	    AscendC::MrgSortSrcList<float> srcList;
352	    srcList.src1 = src[0];
353	    srcList.src2 = src[basicBlockSize * VALUE_AND_INDEX_NUM * MRG_QUE_1];
354	    srcList.src3 = src[basicBlockSize * VALUE_AND_INDEX_NUM * MRG_QUE_2];
355	    srcList.src4 = src[basicBlockSize * VALUE_AND_INDEX_NUM * MRG_QUE_3];
356	    // 执行合并排序
357	    AscendC::MrgSort<float>(dst, srcList, params);
358	}
359	
360	
361	/**
362	 * @brief 从两个队列中选择topk
363	 * @param dst 已经归并好的topk数据
364	 * @param needsMerging 需要合并的有序数据
365	 * @param tmp 临时空间
366	 * @param topk topk的元素个数
367	 * @param mergSize 待合并的元素个数
368	 * @return 无
369	 */
370	template <bool needMrg = true>
371	__aicore__ inline void SparseTopK(const LocalTensor<float> &dst, const LocalTensor<float> &needsMerging,
372	                                  const LocalTensor<float> &tmp, int64_t topk, int64_t mergSize)
373	{
374	    // 如果不需要合并，则直接复制数据
375	    if (!needMrg) {
376	        AscendC::DataCopy(dst, needsMerging, mergSize * VALUE_AND_INDEX_NUM);
377	        return;
378	    }
379	    // 初始化合并排序参数
380	    AscendC::MrgSort4Info params;
381	    params.elementLengths[0] = topk;
382	    params.elementLengths[1] = mergSize;
383	    params.ifExhaustedSuspension = (topk == mergSize);
384	    params.validBit = 0b0011;
385	    // 初始化源列表
386	    AscendC::MrgSortSrcList<float> srcList;
387	    srcList.src1 = dst;
388	    srcList.src2 = needsMerging;
389	    // 执行合并排序
390	    AscendC::MrgSort<float>(tmp, srcList, params);
391	    // 将结果复制到目标张量
392	    AscendC::DataCopy(dst, tmp, topk * VALUE_AND_INDEX_NUM);
393	}
394	
395	
396	__aicore__ inline void ExtractIndex(const LocalTensor<uint32_t> &idxULocal, const LocalTensor<uint32_t> &sortLocal,
397	                                    int64_t extractNum)
398	{
399	    AscendC::GatherMaskParams gatherMaskParams;
400	    gatherMaskParams.repeatTimes = Ceil(extractNum * sizeof(float) * VALUE_AND_INDEX_NUM, VEC_REPEAT_BYTES);
401	    gatherMaskParams.src0BlockStride = 1;
402	    gatherMaskParams.src0RepeatStride = B32_VEC_REPEAT_STRIDE;
403	    gatherMaskParams.src1RepeatStride = 0;
404	    uint64_t rsvdCnt = 0;    // 用于保存筛选后保留下来的元素个数
405	    uint8_t src1Pattern = 2; // 固定模式2,表示筛选出奇数索引的数
406	    AscendC::GatherMask(idxULocal, sortLocal, src1Pattern, false, static_cast<uint32_t>(0), gatherMaskParams, rsvdCnt);
407	    AscendC::PipeBarrier<PIPE_V>();
408	}
409	
410	
411	template <HardEvent event>
412	__aicore__ inline void SetWaitFlag(HardEvent evt)
413	{
414	    event_t eventId = static_cast<event_t>(GetTPipePtr()->FetchEventID(evt));
415	    AscendC::SetFlag<event>(eventId);
416	    AscendC::WaitFlag<event>(eventId);
417	}
418	
419	} // namespace LIServiceVec
420	#endif // LIGHTNING_INDEXER_ENHANCE_VECTOR_H

