153	ge::graphStatus LIInfoParser::GetAndCheckAttrParaInfo()
154	{
155	    auto attrs = context_->GetAttrs();
156	    OP_CHECK_IF(attrs == nullptr,
157	                OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "attrs got from ge is nullptr"),
158	                return ge::GRAPH_FAILED);
159	
160	    OP_LOGI(context_->GetNodeName(), "GetAndCheckAttrParaInfo start");
161	    opParamInfo_.layOut = attrs->GetStr(ATTR_QUERY_LAYOUT_INDEX);
162	    opParamInfo_.layOutKey = attrs->GetStr(ATTR_KEY_LAYOUT_INDEX);
163	    opParamInfo_.sparseCount = attrs->GetAttrPointer<int32_t>(ATTR_SPARSE_COUNT_INDEX);
164	    opParamInfo_.sparseMode = attrs->GetAttrPointer<int32_t>(ATTR_SPARSE_MODE_INDEX);
165	    opParamInfo_.preTokens = attrs->GetAttrPointer<int64_t>(ATTR_PRE_TOKENS_INDEX);
166	    opParamInfo_.nextTokens = attrs->GetAttrPointer<int64_t>(ATTR_NEXT_TOKENS_INDEX);
167	    opParamInfo_.returnValue = attrs->GetAttrPointer<bool>(ATTR_RETURN_VALUE_INDEX);
168	    opParamInfo_.sparseBlockSize = attrs->GetAttrPointer<int32_t>(ATTR_SPARSE_BLOCK_SIZE_INDEX);
169	    opParamInfo_.sparseBlockMode = attrs->GetAttrPointer<int32_t>(ATTR_SPARSE_BLOCK_MODE_INDEX);
170	
171	    if (opParamInfo_.layOut != nullptr) {
172	        OP_LOGI(context_->GetNodeName(), "layout_query is:%s", opParamInfo_.layOut);
173	    }
174	    if (opParamInfo_.layOutKey != nullptr) {
175	        OP_LOGI(context_->GetNodeName(), "layout_key is:%s", opParamInfo_.layOutKey);
176	    }
177	    if (opParamInfo_.sparseCount != nullptr) {
178	        OP_LOGI(context_->GetNodeName(), "selected count is:%d", *opParamInfo_.sparseCount);
179	    }
180	    if (opParamInfo_.sparseMode != nullptr) {
181	        OP_LOGI(context_->GetNodeName(), "sparse mode is:%d", *opParamInfo_.sparseMode);
182	    }
183	    if (opParamInfo_.preTokens != nullptr) {
184	        OP_LOGI(context_->GetNodeName(), "pre tokens is:%d", *opParamInfo_.preTokens);
185	    }
186	    if (opParamInfo_.nextTokens != nullptr) {
187	        OP_LOGI(context_->GetNodeName(), "next tokens is:%d", *opParamInfo_.nextTokens);
188	    }
189	    if (opParamInfo_.returnValue != nullptr) {
190	        OP_LOGI(context_->GetNodeName(), "return value is:%d", *opParamInfo_.returnValue);
191	    }
192	    if (opParamInfo_.sparseBlockSize != nullptr) {
193	        OP_LOGI(context_->GetNodeName(), "sparse block size is:%d", *opParamInfo_.sparseBlockSize);
194	    }
195	    if (opParamInfo_.sparseBlockMode != nullptr) {
196	        OP_LOGI(context_->GetNodeName(), "sparse block mode is:%d", *opParamInfo_.sparseBlockMode);
197	    }
198	    OP_LOGI(context_->GetNodeName(), "GetAndCheckAttrParaInfo end");
199	
200	    OP_CHECK_IF(((std::string(opParamInfo_.layOutKey) != "PA_BSND") &&
201	                 (std::string(opParamInfo_.layOut) != std::string(opParamInfo_.layOutKey))),
202	                OP_LOGE(opName_, "under non-PA conditions, layout_query and layout_key should be equal."),
203	                return ge::GRAPH_FAILED);
204	    OP_CHECK_IF(((std::string(opParamInfo_.layOutKey) != "PA_BSND") &&
205	                 (std::string(opParamInfo_.layOutKey) != "BSND") && (std::string(opParamInfo_.layOutKey) != "TND")),
206	                OP_LOGE(opName_, "input attr layout_key only supported PA_BSND, BSND or TND"),
207	                return ge::GRAPH_FAILED);
208	    OP_CHECK_IF(((std::string(opParamInfo_.layOut) != "BSND") && (std::string(opParamInfo_.layOut) != "TND")),
209	                OP_LOGE(opName_, "input attr layout_query only supported BSND or TND."),
210	                return ge::GRAPH_FAILED);
211	    OP_CHECK_IF(
212	        (!((*opParamInfo_.sparseCount > 0) && (*opParamInfo_.sparseCount <= SPARSE_LIMIT)) &&
213	         *opParamInfo_.sparseCount % 1024 != 0),
214	        OP_LOGE(opName_,
215	                "input attr sparse_count must > 0 and <= 16384 or sparse_count is an interger multiple of 1024."),
216	        return ge::GRAPH_FAILED);
217	    OP_CHECK_IF(!((*opParamInfo_.sparseMode == 0) || (*opParamInfo_.sparseMode == SPARSE_MODE_LOWER)),
218	                OP_LOGE(opName_, "input attr sparse_mode only supported 0 or 3."),
219	                return ge::GRAPH_FAILED);
220	    OP_CHECK_IF(!((*opParamInfo_.sparseBlockSize == 1) || (*opParamInfo_.sparseBlockSize == 8) ||
221	                  (*opParamInfo_.sparseBlockSize == 16) || (*opParamInfo_.sparseBlockSize == 32) ||
222	                  (*opParamInfo_.sparseBlockSize == 64)),
223	                OP_LOGE(opName_, "input attr sparseBlockSize must be 1 or 8 or 16 or 32 or 64."),
