225	    OP_CHECK_IF(*opParamInfo_.sparseBlockMode != 0,
226	                OP_LOGE(opName_, "input attr sparseBlockMode only supported 0."),
227	                return ge::GRAPH_FAILED);
228	
229	    return ge::GRAPH_SUCCESS;
