332	                    (opParamInfo_.blockTable.tensor->GetStorageShape().GetDimNum() != DIM_NUM_TWO),
333	                OP_LOGE(opName_, "the dim num of block_table's shape should be 2"),
334	                return ge::GRAPH_FAILED);
335	
336	    uint32_t kShapeDim = opParamInfo_.key.shape->GetShape().GetDimNum();
337	    uint32_t qShapeDim = opParamInfo_.query.shape->GetStorageShape().GetDimNum();
338	    uint32_t weightsShapeDim = opParamInfo_.weights.shape->GetStorageShape().GetDimNum();
339	    uint32_t outShapeDim = opParamInfo_.attenOut.shape->GetStorageShape().GetDimNum();
340	    uint32_t valuesOutShapeDim = opParamInfo_.valuesOut.shape->GetStorageShape().GetDimNum();
341	    uint32_t qExpectShapeDim = DIM_NUM_FOUR;
342	    uint32_t kExpectShapeDim = DIM_NUM_FOUR;
343	    if (qLayout_ == DataLayout::TND) {
344	        qExpectShapeDim = DIM_NUM_THREE;
345	    }
346	    if (kLayout_ == DataLayout::TND) {
347	        kExpectShapeDim = DIM_NUM_THREE;
348	    }
349	    OP_CHECK_IF(kShapeDim != kExpectShapeDim,
350	                OP_LOGE(opName_, "the dim num of key's shape should be %u, but now is %u", kExpectShapeDim, kShapeDim),
351	                return ge::GRAPH_FAILED);
352	    OP_CHECK_IF(
353	        qShapeDim != qExpectShapeDim,
354	        OP_LOGE(opName_, "the dim num of query's shape should be %u, but now is %u", qExpectShapeDim, qShapeDim),
355	        return ge::GRAPH_FAILED);
356	    OP_CHECK_IF(
357	        outShapeDim != qExpectShapeDim,
358	        OP_LOGE(
359	            opName_, "the dim num of sparse_indices's shape should be %u, but now is %u", qExpectShapeDim, outShapeDim),
360	        return ge::GRAPH_FAILED);
361	    OP_CHECK_IF(valuesOutShapeDim != qExpectShapeDim,
362	                OP_LOGE(opName_,
363	                        "the dim num of sparse_values's shape should be %u, but now is %u",
364	                        qExpectShapeDim,
365	                        valuesOutShapeDim),
366	                return ge::GRAPH_FAILED);
367	    OP_CHECK_IF(!(weightsShapeDim == qExpectShapeDim - 1),
368	                OP_LOGE(opName_,
369	                        "the dim num of weights's shape should be %u, but now is %u",
370	                        qExpectShapeDim - 1,
371	                        weightsShapeDim),
372	                return ge::GRAPH_FAILED);
373	
374	    return ge::GRAPH_SUCCESS;
375	}
376	
377	ge::graphStatus LIInfoParser::GetN1Size()
378	{
379	    if (qLayout_ == DataLayout::BSND) {
380	        n1Size_ = static_cast<uint32_t>(opParamInfo_.query.shape->GetStorageShape().GetDim(DIM_IDX_TWO));
381	    } else {
382	        // TND
383	        n1Size_ = static_cast<uint32_t>(opParamInfo_.query.shape->GetStorageShape().GetDim(1));
384	    }
