421	ge::graphStatus LIInfoParser::GetBatchSize()
422	{
423	    // 获取B基准值
424	    // 1、非TND/NTD时, 以query的batch_size维度为基准;
425	    // 2、TND/NTD时, actual_seq_lens_q必须传入, 以actual_seq_lens_q数组的长度为B轴大小
426	    if ((qLayout_ == DataLayout::TND)) {
427	        return GetActualSeqLenSize(bSize_, opParamInfo_.actualSeqLengthsQ.tensor, "input actual_seq_lengths_query");
428	    } else { // BSND
429	        bSize_ = opParamInfo_.query.shape->GetStorageShape().GetDim(0);
430	        return ge::GRAPH_SUCCESS;
431	    }
432	}
433	
434	ge::graphStatus LIInfoParser::GetHeadDim()
435	{
436	    // 以query的D维度为基准
437	    uint32_t dIndex = DIM_IDX_TWO;
438	    // 根据layout确定D维度在shape中的位置
439	    switch (qLayout_) {
440	        case DataLayout::TND:
441	            // TND格式: [Total, N, D] -> D是第2维(索引2)
442	            dIndex = DIM_IDX_TWO;
443	            break;
444	        case DataLayout::BSND:
445	            // BSND格式: [Batch, SeqLen, N, D] -> D是第3维(索引3)
446	            dIndex = DIM_IDX_THREE;
447	            break;
448	        default:
449	            OP_LOGE(opName_, "unsupported layout for getting head dim.");
450	            return ge::GRAPH_FAILED;
451	    }
452	    headDim_ = opParamInfo_.query.shape->GetStorageShape().GetDim(dIndex);
453	    OP_CHECK_IF(headDim_ != HEAD_DIM_LIMIT,
454	                OP_LOGE(opName_, "input query's last dim head_dim only support 128."),
455	                return ge::GRAPH_FAILED);
456	
457	    return ge::GRAPH_SUCCESS;
458	}
459	
460	ge::graphStatus LIInfoParser::GetS1Size()
461	{
462	    if (qLayout_ == DataLayout::BSND) {
463	        s1Size_ = opParamInfo_.query.shape->GetStorageShape().GetDim(1);
464	    } else { // TND
465	        s1Size_ = opParamInfo_.query.shape->GetStorageShape().GetDim(0);
466	    }
467	    return ge::GRAPH_SUCCESS;
468	}
469	
470	ge::graphStatus LIInfoParser::GetAndCheckBlockSize()
471	{
472	    blockSize_ = static_cast<uint32_t>(opParamInfo_.key.shape->GetShape().GetDim(1));
473	    OP_LOGI(context_->GetNodeName(), "blockSize_ is %d", blockSize_);
474	
475	    OP_CHECK_IF(((blockSize_ % 16 != 0) || (blockSize_ == 0) || (blockSize_ > 1024)),
476	                OP_LOGE(opName_, "input key's block_size must be a multiple of 16 and belong to (0, 1024]."),
477	                return ge::GRAPH_FAILED);
478	
479	    return ge::GRAPH_SUCCESS;
480	}
481	
482	ge::graphStatus LIInfoParser::CheckBlockCount()
483	{
484	    int32_t blockCount_ = static_cast<uint32_t>(opParamInfo_.key.shape->GetShape().GetDim(0));
485	    OP_CHECK_IF((blockCount_ == 0), OP_LOGE(opName_, "input key's block_count cannot be 0."), return ge::GRAPH_FAILED);
486	    return ge::GRAPH_SUCCESS;
487	}
488	
489	ge::graphStatus LIInfoParser::GetS2SizeForPageAttention()
490	{
491	    if (GetAndCheckBlockSize() != ge::GRAPH_SUCCESS) {
492	        return ge::GRAPH_FAILED;
493	    }
494	    if (CheckBlockCount() != ge::GRAPH_SUCCESS) {
495	        return ge::GRAPH_FAILED;
496	    }
497	    maxBlockNumPerBatch_ = opParamInfo_.blockTable.tensor->GetStorageShape().GetDim(1);
498	    s2Size_ = maxBlockNumPerBatch_ * blockSize_;
499	    OP_LOGI(context_->GetNodeName(),
500	            "maxBlockNumPerBatch_ is %d, blockSize_ is %d, s2Size_ is %d",
501	            maxBlockNumPerBatch_,
502	            blockSize_,
503	            s2Size_);
504	    return ge::GRAPH_SUCCESS;
505	}
506	
507	ge::graphStatus LIInfoParser::GetS2Size()
508	{
509	    // 获取S2基准值
510	    // 1、BATCH_CONTINUOUS时, 从key的S轴获取
511	    // 3、PAGE_ATTENTION时, S2 = block_table.dim1 * block_size
512	    if (kLayout_ == DataLayout::BnBsND) {
513	        return GetS2SizeForPageAttention();
514	    } else if (kLayout_ == DataLayout::TND) {
515	        s2Size_ = opParamInfo_.key.shape->GetStorageShape().GetDim(0);
516	    } else if (kLayout_ == DataLayout::BSND) {
517	        s2Size_ = opParamInfo_.key.shape->GetStorageShape().GetDim(1);
518	    } else {
519	        OP_LOGE(opName_, "key layout only support PA_BNSD, TND, BSND.");
520	        return ge::GRAPH_FAILED;
521	    }
522	    return ge::GRAPH_SUCCESS;
523	}
524	
525	ge::graphStatus LIInfoParser::GetKeyStride()
526	{
527	    auto keyStride = context_->GetInputStride(KEY_INDEX);
528	    if (keyStride == nullptr) {
529	        OP_LOGE(opName_, "GetInputStride for key returned nullptr");
530	        return ge::GRAPH_FAILED;
531	    }
532	    uint32_t strideDimNum = keyStride->GetDimNum(); // 0:连续；非0:非连续
533	
534	    // 非PA场景
535	    if (kLayout_ != DataLayout::BnBsND) {
536	        if (strideDimNum != 0) {
537	            OP_LOGE(opName_, "Non-contiguous key is only supported in Page Attention.");
538	            return ge::GRAPH_FAILED;
539	        }
540	        return ge::GRAPH_SUCCESS; // 连续，直接返回
541	    }
542	
543	    // PA场景
544	    uint64_t originStride = blockSize_ * n2Size_ * headDim_;
545	    if (strideDimNum != 0) {
546	        kCacheStride_ = keyStride->GetStride(0);
547	        if (kCacheStride_ < originStride) {
548	            OP_LOGE(opName_,
549	                    "Non-contiguous stride(%u) should not be smaller than contiguous stride(%u).",
550	                    kCacheStride_,
551	                    originStride);
552	            return ge::GRAPH_FAILED;
553	        }
554	    } else {
555	        kCacheStride_ = originStride; // 连续，默认计算方式
556	    }
557	
558	    return ge::GRAPH_SUCCESS;
559	}
560	
561	ge::graphStatus LIInfoParser::ValidateInputShapesMatch()
562	{
563	    /*
564	    TND:
565	    query [T,N1,D],
566	    key [BlockNum,BlockSize,N2,D],
567	    weight [T,N1],
568	    block_table [BatchSize, BatchMaxBlockNum],
569	    act_seq_k [BatchSize]
570	    act_seq_q [BatchSize],
571	    out [T,N2,topk]
572	    ----------------------
573	    BSND:
574	    query [BatchSize,S1,N1,D],
575	    key [BlockNum,BlockSize,N2,D],
576	    weight [BatchSize,S1,N1],
577	    block_table [BatchSize, BatchMaxBlockNum],
578	    act_seq_k [BatchSize]
579	    act_seq_q [BatchSize] 可选
580	    out [BatchSize,S1,N2,topk]
581	    */
582	    uint32_t queryWeightsN1Dim = 1;
583	    uint32_t outN2Dim = 1;
584	    if (qLayout_ == DataLayout::TND) {
585	        // -----------------------check BatchSize-------------------
586	        // bSize_ 来源于act_seq_q
587	        OP_CHECK_IF((opParamInfo_.actualSeqLengths.tensor->GetShapeSize() != bSize_) ||
588	                        ((opParamInfo_.blockTable.tensor != nullptr) &&
589	                         (opParamInfo_.blockTable.tensor->GetStorageShape().GetDim(0) != bSize_)),
590	                    OP_LOGE(opName_,
591	                            "TND case input actual_seq_lengths_query, actual_seq_lengths_key, block_table dim 0 are "
592	                            "%u, %u, %u respectively, they must be same.",
593	                            bSize_,
594	                            opParamInfo_.actualSeqLengths.tensor->GetShapeSize(),
595	                            opParamInfo_.blockTable.tensor->GetStorageShape().GetDim(0)),
596	                    return ge::GRAPH_FAILED);
597	        // -----------------------check T-------------------
598	        uint32_t qTsize = opParamInfo_.query.shape->GetStorageShape().GetDim(0);
599	        OP_CHECK_IF((opParamInfo_.weights.shape->GetStorageShape().GetDim(0) != qTsize) ||
600	                        (opParamInfo_.attenOut.shape->GetStorageShape().GetDim(0) != qTsize) ||
601	                        (opParamInfo_.valuesOut.shape->GetStorageShape().GetDim(0) != qTsize),
602	                    OP_LOGE(opName_,
603	                            "TND case input query, weights, sparse_indices, sparse_values dim 0 are %u, %u, %u "
604	                            "respectively, they must be same.",
605	                            qTsize,
606	                            opParamInfo_.weights.shape->GetStorageShape().GetDim(0),
607	                            opParamInfo_.attenOut.shape->GetStorageShape().GetDim(0),
608	                            opParamInfo_.valuesOut.shape->GetStorageShape().GetDim(0)),
609	                    return ge::GRAPH_FAILED);
610	    } else {
611	        // -----------------------check BatchSize-------------------
612	        // bSize_ 来源于query
613	        OP_CHECK_IF((opParamInfo_.weights.shape->GetStorageShape().GetDim(0) != bSize_) ||
614	                        ((opParamInfo_.blockTable.tensor != nullptr) &&
615	                         (opParamInfo_.blockTable.tensor->GetStorageShape().GetDim(0) != bSize_)) ||
616	                        ((opParamInfo_.actualSeqLengths.tensor != nullptr) &&
617	                         (opParamInfo_.actualSeqLengths.tensor->GetShapeSize() != bSize_)) ||
618	                        (opParamInfo_.attenOut.shape->GetStorageShape().GetDim(0) != bSize_) ||
619	                        (opParamInfo_.valuesOut.shape->GetStorageShape().GetDim(0) != bSize_),
620	                    OP_LOGE(opName_,
621	                            "BSND case input query, weight, actual_seq_lengths_key, block_table, sparse_indices, "
622	                            "sparse_values dim 0 must be same."),
623	                    return ge::GRAPH_FAILED);
624	        OP_CHECK_IF(
625	            (opParamInfo_.actualSeqLengthsQ.tensor != nullptr) &&
626	                (opParamInfo_.actualSeqLengthsQ.tensor->GetShapeSize() != bSize_),
627	            OP_LOGE(opName_,
628	                    "BSND case input query, actual_seq_lengths_query dim 0 are %u, %u respectively, they must be same",
629	                    bSize_,
630	                    opParamInfo_.actualSeqLengthsQ.tensor->GetShapeSize()),
631	            return ge::GRAPH_FAILED);
632	        // -----------------------check S1-------------------
633	        OP_CHECK_IF(
634	            (opParamInfo_.weights.shape->GetStorageShape().GetDim(1) != s1Size_) ||
635	                (opParamInfo_.attenOut.shape->GetStorageShape().GetDim(1) != s1Size_) ||
636	                (opParamInfo_.valuesOut.shape->GetStorageShape().GetDim(1) != s1Size_),
637	            OP_LOGE(
638	                opName_,
639	                "BSND case input query, weight, sparse_indices, sparse_values dim 1 are %u, %u, %u, they must be same.",
640	                s1Size_,
641	                opParamInfo_.weights.shape->GetStorageShape().GetDim(1),
642	                opParamInfo_.attenOut.shape->GetStorageShape().GetDim(1)),
643	            return ge::GRAPH_FAILED);
644	        queryWeightsN1Dim = DIM_IDX_TWO;
645	        outN2Dim = DIM_IDX_TWO;
646	    }
647	    // -----------------------check N1-------------------
648	    OP_CHECK_IF((opParamInfo_.weights.shape->GetStorageShape().GetDim(queryWeightsN1Dim) != n1Size_),
649	                OP_LOGE(opName_, "input query, weight shape dim N1 must be same."),
650	                return ge::GRAPH_FAILED);
651	    // -----------------------check D-------------------
652	    uint32_t keyDDim = kLayout_ == DataLayout::TND ? DIM_IDX_TWO : DIM_IDX_THREE;
653	    OP_CHECK_IF((opParamInfo_.key.shape->GetShape().GetDim(keyDDim) != headDim_),
654	                OP_LOGE(opName_, "input query, key shape last dim must be same."),
655	                return ge::GRAPH_FAILED);
656	    // -----------------------check N2-------------------
657	    OP_CHECK_IF((opParamInfo_.attenOut.shape->GetStorageShape().GetDim(outN2Dim) != n2Size_) ||
658	                    (opParamInfo_.valuesOut.shape->GetStorageShape().GetDim(outN2Dim) != n2Size_),
659	                OP_LOGE(opName_, "input query and output sparse_indices, sparse_values shape n2 dim must be same."),
660	                return ge::GRAPH_FAILED);
661	    // -----------------------check sparse_count-------------------
662	    OP_CHECK_IF(
663	        (opParamInfo_.attenOut.shape->GetStorageShape().GetDim(outN2Dim + 1) !=
664	         ((*opParamInfo_.sparseCount + *opParamInfo_.sparseBlockSize - 1) / *opParamInfo_.sparseBlockSize)) ||
665	            (opParamInfo_.valuesOut.shape->GetStorageShape().GetDim(outN2Dim + 1) !=
666	             ((*opParamInfo_.sparseCount + *opParamInfo_.sparseBlockSize - 1) / *opParamInfo_.sparseBlockSize)),
667	        OP_LOGE(
668	            opName_,
669	            "output sparse_indices, sparse_values shape last dim must be same as (sparse_count / sparse_block_size)."),
670	        return ge::GRAPH_FAILED);
671	
672	    return ge::GRAPH_SUCCESS;
673	}
