675	void LIInfoParser::GenerateInfo(LITilingInfo &liInfo)
676	{
677	    liInfo.opName = opName_;
678	    liInfo.platformInfo = platformInfo_;
679	    liInfo.opParamInfo = opParamInfo_;
680	    liInfo.socVersion = socVersion_;
681	
682	    liInfo.bSize = bSize_;
683	    liInfo.n1Size = n1Size_;
684	    liInfo.n2Size = n2Size_;
685	    liInfo.s1Size = s1Size_;
686	    liInfo.s2Size = s2Size_;
687	    liInfo.gSize = gSize_;
688	    liInfo.kCacheStride = kCacheStride_;
689	
690	    liInfo.inputQType = inputQType_;
691	    liInfo.inputKType = inputKType_;
692	    liInfo.outputType = outputType_;
693	
694	    liInfo.blockSize = blockSize_;
695	    liInfo.maxBlockNumPerBatch = maxBlockNumPerBatch_;
696	
697	    std::string layOutKeyStr(opParamInfo_.layOutKey);
698	    liInfo.pageAttentionFlag = layOutKeyStr == "PA_BSND" ? true : false;
699	    liInfo.sparseMode = *opParamInfo_.sparseMode;
700	    liInfo.sparseCount = *opParamInfo_.sparseCount;
701	    liInfo.preTokens = *opParamInfo_.preTokens;
702	    liInfo.nextTokens = *opParamInfo_.nextTokens;
703	    liInfo.returnValue = *opParamInfo_.returnValue;
704	    liInfo.sparseBlockSize = *opParamInfo_.sparseBlockSize;
705	    liInfo.sparseBlockMode = *opParamInfo_.sparseBlockMode;
706	
707	    liInfo.inputQLayout = qLayout_;
708	    liInfo.inputKLayout = kLayout_;
709	}
