711	ge::graphStatus LIInfoParser::ParseAndCheck(LITilingInfo &liInfo)
712	{
713	    if (ge::GRAPH_SUCCESS != GetOpName() || ge::GRAPH_SUCCESS != GetNpuInfo() || ge::GRAPH_SUCCESS != GetOpParaInfo() ||
714	        ge::GRAPH_SUCCESS != CheckRequiredParaExistence()) {
715	        return ge::GRAPH_FAILED;
716	    }
717	
718	    if (ge::GRAPH_SUCCESS != GetAndCheckInOutDataType() || ge::GRAPH_SUCCESS != GetQueryKeyAndOutLayout() ||
719	        ge::GRAPH_SUCCESS != GetAndCheckOptionalInput()) {
720	        return ge::GRAPH_FAILED;
721	    }
722	
723	    if (ge::GRAPH_SUCCESS != CheckShapeDim() || ge::GRAPH_SUCCESS != GetN1Size() ||
724	        ge::GRAPH_SUCCESS != GetAndCheckN2Size() || ge::GRAPH_SUCCESS != GetGSize()) {
725	        return ge::GRAPH_FAILED;
726	    }
727	
728	    if (ge::GRAPH_SUCCESS != GetBatchSize() || ge::GRAPH_SUCCESS != GetS1Size() || ge::GRAPH_SUCCESS != GetHeadDim() ||
729	        ge::GRAPH_SUCCESS != GetS2Size()) {
730	        return ge::GRAPH_FAILED;
731	    }
732	
733	    if (ge::GRAPH_SUCCESS != GetKeyStride()) {
734	        return ge::GRAPH_FAILED;
735	    }
736	
737	    if (ge::GRAPH_SUCCESS != ValidateInputShapesMatch()) {
738	        return ge::GRAPH_FAILED;
739	    }
740	
741	    GenerateInfo(liInfo);
742	
743	    return ge::GRAPH_SUCCESS;
744	}
