752	// --------------------------LightningIndexerEnhanceTiling类成员函数定义-----------------------
753	ge::graphStatus LightningIndexerEnhanceTiling::DoTiling(LITilingInfo *tilingInfo)
754	{
755	    // -------------set blockdim-----------------
756	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(tilingInfo->platformInfo);
757	    uint32_t aivNum = ascendcPlatform.GetCoreNumAiv();
758	    uint32_t aicNum = ascendcPlatform.GetCoreNumAic();
759	    uint32_t blockDim = ascendcPlatform.CalcTschBlockDim(aivNum, aicNum, aivNum);
760	    context_->SetBlockDim(blockDim);
761	
762	    // -------------set workspacesize-----------------
763	    constexpr uint32_t MM1_RES_ELEM_SIZE = 4; // 4: fp32
764	    constexpr uint32_t DOUBLE_BUFFER = 2; // 双Buffer
765	    constexpr uint32_t M_BASE_SIZE = 512; // m轴基本块大小
766	    constexpr uint32_t S2_BASE_SIZE = 512; // S2轴基本块大小
767	    constexpr uint32_t V1_RES_ELEM_SIZE = 4; // 4: int32
768	    constexpr uint32_t V1_RES_ELEM_TYPE = 2; // 保留Index和Value 2种数据
769	    constexpr uint32_t V1_DECODE_PARAM_ELEM_SIZE = 8; // 8: int64
770	    constexpr uint32_t V1_DECODE_PARAM_NUM = 16; // Decode参数个数
771	    constexpr uint32_t V1_DECODE_DATA_NUM = 2; // Decode每个核需要存储头和尾部两块数据
772	    constexpr uint32_t TOPK_MAX_SIZE = 2048; // TopK选取个数
773	    constexpr uint32_t S1_BASE_SIZE_8 = 8; // S1轴基本块大小-默认值
774	
775	    uint32_t s1BaseSize = S1_BASE_SIZE_8;
776	    uint32_t s1Size = tilingInfo->s1Size;
777	
778	    bool isAverageLD = false; // 是否启用均分LD优化
779	
780	    if (tilingInfo->sparseBlockSize == 1 && tilingInfo->inputQLayout == DataLayout::TND &&
781	        tilingInfo->inputKLayout == DataLayout::BnBsND) {
782	        constexpr uint32_t S1_BASE_SIZE_2 = 2; // S1轴基本块大小-负载均衡
783	        constexpr uint32_t S1_BASE_SIZE_4 = 4; // S1轴基本块大小-负载均衡
784	        uint32_t useAicNum =
785	            (s1Size + S1_BASE_SIZE_8 - 1) / S1_BASE_SIZE_8 * (tilingInfo->s2Size + S2_BASE_SIZE - 1) / S2_BASE_SIZE;
786	        bool useFullAic = useAicNum >= aicNum;
787	        s1BaseSize = useFullAic
788	                         ? s1BaseSize
789	                         : (s1Size <= S1_BASE_SIZE_4 ? S1_BASE_SIZE_2
790	                                                     : (s1Size <= S1_BASE_SIZE_8 ? S1_BASE_SIZE_4 : S1_BASE_SIZE_8));
791	    }
792	
793	    uint32_t workspaceSize = ascendcPlatform.GetLibApiWorkSpaceSize();
794	    // 主流程需Workspace大小
795	    uint32_t mm1ResSize = M_BASE_SIZE * S2_BASE_SIZE;
796	    workspaceSize += mm1ResSize * MM1_RES_ELEM_SIZE * DOUBLE_BUFFER * aicNum;
797	    // Decode流程(LD)需要Workspace大小
798	    // 临时存储Decode中间结果大小: 2(头/尾)*8(s1Base)*2(idx/value)*2048(K)*sizeof(int32)*24=6M
799	    workspaceSize += V1_DECODE_DATA_NUM * s1BaseSize * V1_RES_ELEM_TYPE * TOPK_MAX_SIZE * V1_RES_ELEM_SIZE * aicNum;
800	    // 临时存储Decode中间参数信息大小: 2(头/尾)*8(s1Base)*16(paramNum)*sizeof(int64_t)*24=48k
801	    workspaceSize += V1_DECODE_DATA_NUM * s1BaseSize * V1_DECODE_PARAM_NUM * V1_DECODE_PARAM_ELEM_SIZE * aicNum;
802	    size_t *workSpaces = context_->GetWorkspaceSizes(1);
803	    workSpaces[0] = workspaceSize;
804	
805	    // -------------set tilingdata-----------------
806	    tilingData_.set_bSize(tilingInfo->bSize);
807	    tilingData_.set_s2Size(tilingInfo->s2Size);
808	    tilingData_.set_s1Size(tilingInfo->s1Size);
809	    tilingData_.set_sparseCount(tilingInfo->sparseCount);
810	    tilingData_.set_gSize(tilingInfo->gSize);
811	    tilingData_.set_blockSize(tilingInfo->blockSize);
812	    tilingData_.set_maxBlockNumPerBatch(tilingInfo->maxBlockNumPerBatch);
813	    tilingData_.set_sparseMode(tilingInfo->sparseMode);
814	    tilingData_.set_preTokens(tilingInfo->preTokens);
815	    tilingData_.set_nextTokens(tilingInfo->nextTokens);
816	    tilingData_.set_returnValue(tilingInfo->returnValue);
817	    tilingData_.set_sparseBlockSize(tilingInfo->sparseBlockSize);
818	    tilingData_.set_sparseBlockMode(tilingInfo->sparseBlockMode);
819	    tilingData_.set_kCacheStride(tilingInfo->kCacheStride);
820	    tilingData_.set_s1BaseSize(s1BaseSize);
821	    tilingData_.set_isAverageLD(isAverageLD);
822	
823	    tilingData_.set_usedCoreNum(blockDim);
824	    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
825	    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());
826	
827	    // -------------set tilingkey-----------------
828	    // DT_Q, DT_KV, DT_OUT, PAGE_ATTENTION, FLASH_DECODE, LAYOUT_T, KV_LAYOUT_T
829	    uint32_t inputQType = static_cast<uint32_t>(tilingInfo->inputQType);
830	    uint32_t inputKType = static_cast<uint32_t>(tilingInfo->inputKType);
831	    uint32_t outputType = static_cast<uint32_t>(tilingInfo->outputType);
832	    uint32_t pageAttentionFlag = static_cast<uint32_t>(tilingInfo->pageAttentionFlag);
833	    uint32_t inputQLayout = static_cast<uint32_t>(tilingInfo->inputQLayout);
834	    uint32_t inputKLayout = static_cast<uint32_t>(tilingInfo->inputKLayout);
835	    uint64_t tilingKey =
836	        GET_TPL_TILING_KEY(inputQType, inputKType, outputType, pageAttentionFlag, inputQLayout, inputKLayout);
837	    context_->SetTilingKey(tilingKey);
838	
839	    return ge::GRAPH_SUCCESS;
840	}
841	
842	// --------------------------Tiling函数定义---------------------------
843	ge::graphStatus TilingForLightningIndexerEnhance(gert::TilingContext *context)
844	{
845	    OP_CHECK_IF(context == nullptr,
846	                OPS_REPORT_VECTOR_INNER_ERR("LightningIndexerEnhance", "Tiling context is null."),
847	                return ge::GRAPH_FAILED);
848	    LITilingInfo liInfo;
849	    LIInfoParser LIInfoParser(context);
850	    if (LIInfoParser.ParseAndCheck(liInfo) != ge::GRAPH_SUCCESS) {
851	        return ge::GRAPH_FAILED;
852	    }
853	    LightningIndexerEnhanceTiling liTiling(context);
854	    return liTiling.DoTiling(&liInfo);
855	}
