ge::graphStatus LIInfoParser::GetBatchSize()
{
    // 获取B基准值
    // 1、非TND/NTD时, 以query的batch_size维度为基准;
    // 2、TND/NTD时, actual_seq_lens_q必须传入, 以actual_seq_lens_q数组的长度为B轴大小
    if ((qLayout_ == DataLayout::TND)) {
        return GetActualSeqLenSize(bSize_, opParamInfo_.actualSeqLengthsQ.tensor, "input actual_seq_lengths_query");
    } else { // BSND
        bSize_ = opParamInfo_.query.shape->GetStorageShape().GetDim(0);
        return ge::GRAPH_SUCCESS;
    }
}

ge::graphStatus LIInfoParser::GetHeadDim()
{
    // 以query的D维度为基准
    uint32_t dIndex = DIM_IDX_TWO;
    // 根据layout确定D维度在shape中的位置
    switch (qLayout_) {
        case DataLayout::TND:
            // TND格式: [Total, N, D] -> D是第2维(索引2)
            dIndex = DIM_IDX_TWO;
            break;
        case DataLayout::BSND:
            // BSND格式: [Batch, SeqLen, N, D] -> D是第3维(索引3)
            dIndex = DIM_IDX_THREE;
            break;
        default:
            OP_LOGE(opName_, "unsupported layout for getting head dim.");
            return ge::GRAPH_FAILED;
    }
    headDim_ = opParamInfo_.query.shape->GetStorageShape().GetDim(dIndex);
    OP_CHECK_IF(headDim_ != HEAD_DIM_LIMIT,
                OP_LOGE(opName_, "input query's last dim head_dim only support 128."),
                return ge::GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus LIInfoParser::GetS1Size()
{
    if (qLayout_ == DataLayout::BSND) {
        s1Size_ = opParamInfo_.query.shape->GetStorageShape().GetDim(1);
    } else { // TND
        s1Size_ = opParamInfo_.query.shape->GetStorageShape().GetDim(0);
    }
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus LIInfoParser::GetAndCheckBlockSize()
{
    blockSize_ = static_cast<uint32_t>(opParamInfo_.key.shape->GetShape().GetDim(1));
    OP_LOGI(context_->GetNodeName(), "blockSize_ is %d", blockSize_);

    OP_CHECK_IF(((blockSize_ % 16 != 0) || (blockSize_ == 0) || (blockSize_ > 1024)),
                OP_LOGE(opName_, "input key's block_size must be a multiple of 16 and belong to (0, 1024]."),
                return ge::GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus LIInfoParser::CheckBlockCount()
{
    int32_t blockCount_ = static_cast<uint32_t>(opParamInfo_.key.shape->GetShape().GetDim(0));
    OP_CHECK_IF((blockCount_ == 0), OP_LOGE(opName_, "input key's block_count cannot be 0."), return ge::GRAPH_FAILED);
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus LIInfoParser::GetS2SizeForPageAttention()
{
    if (GetAndCheckBlockSize() != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }
    if (CheckBlockCount() != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }
    maxBlockNumPerBatch_ = opParamInfo_.blockTable.tensor->GetStorageShape().GetDim(1);
    s2Size_ = maxBlockNumPerBatch_ * blockSize_;
    OP_LOGI(context_->GetNodeName(),
            "maxBlockNumPerBatch_ is %d, blockSize_ is %d, s2Size_ is %d",
            maxBlockNumPerBatch_,
            blockSize_,
            s2Size_);
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus LIInfoParser::GetS2Size()
{
    // 获取S2基准值
    // 1、BATCH_CONTINUOUS时, 从key的S轴获取
    // 3、PAGE_ATTENTION时, S2 = block_table.dim1 * block_size
    if (kLayout_ == DataLayout::BnBsND) {
        return GetS2SizeForPageAttention();
    } else if (kLayout_ == DataLayout::TND) {
        s2Size_ = opParamInfo_.key.shape->GetStorageShape().GetDim(0);
    } else if (kLayout_ == DataLayout::BSND) {
        s2Size_ = opParamInfo_.key.shape->GetStorageShape().GetDim(1);
    } else {
        OP_LOGE(opName_, "key layout only support PA_BNSD, TND, BSND.");
        return ge::GRAPH_FAILED;
    }
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus LIInfoParser::GetKeyStride()
{
    auto keyStride = context_->GetInputStride(KEY_INDEX);
    if (keyStride == nullptr) {
        OP_LOGE(opName_, "GetInputStride for key returned nullptr");
        return ge::GRAPH_FAILED;
    }
    uint32_t strideDimNum = keyStride->GetDimNum(); // 0:连续；非0:非连续

    // 非PA场景
    if (kLayout_ != DataLayout::BnBsND) {
        if (strideDimNum != 0) {
            OP_LOGE(opName_, "Non-contiguous key is only supported in Page Attention.");
            return ge::GRAPH_FAILED;
        }
        return ge::GRAPH_SUCCESS; // 连续，直接返回
    }

    // PA场景
    uint64_t originStride = blockSize_ * n2Size_ * headDim_;
    if (strideDimNum != 0) {
        kCacheStride_ = keyStride->GetStride(0);
        if (kCacheStride_ < originStride) {
            OP_LOGE(opName_,
                    "Non-contiguous stride(%u) should not be smaller than contiguous stride(%u).",
                    kCacheStride_,
                    originStride);
            return ge::GRAPH_FAILED;
        }
    } else {
        kCacheStride_ = originStride; // 连续，默认计算方式
    }

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus LIInfoParser::ValidateInputShapesMatch()
{
    /*
    TND:
    query [T,N1,D],
    key [BlockNum,BlockSize,N2,D],
    weight [T,N1],
    block_table [BatchSize, BatchMaxBlockNum],
    act_seq_k [BatchSize]
    act_seq_q [BatchSize],
    out [T,N2,topk]
    ----------------------
    BSND:
    query [BatchSize,S1,N1,D],
    key [BlockNum,BlockSize,N2,D],
    weight [BatchSize,S1,N1],
    block_table [BatchSize, BatchMaxBlockNum],
    act_seq_k [BatchSize]
    act_seq_q [BatchSize] 可选
    out [BatchSize,S1,N2,topk]
    */
    uint32_t queryWeightsN1Dim = 1;
    uint32_t outN2Dim = 1;
    if (qLayout_ == DataLayout::TND) {
        // -----------------------check BatchSize-------------------
        // bSize_ 来源于act_seq_q
        OP_CHECK_IF((opParamInfo_.actualSeqLengths.tensor->GetShapeSize() != bSize_) ||
                        ((opParamInfo_.blockTable.tensor != nullptr) &&
                         (opParamInfo_.blockTable.tensor->GetStorageShape().GetDim(0) != bSize_)),
                    OP_LOGE(opName_,
                            "TND case input actual_seq_lengths_query, actual_seq_lengths_key, block_table dim 0 are "
                            "%u, %u, %u respectively, they must be same.",
                            bSize_,
                            opParamInfo_.actualSeqLengths.tensor->GetShapeSize(),
                            opParamInfo_.blockTable.tensor->GetStorageShape().GetDim(0)),
                    return ge::GRAPH_FAILED);
        // -----------------------check T-------------------
        uint32_t qTsize = opParamInfo_.query.shape->GetStorageShape().GetDim(0);
        OP_CHECK_IF((opParamInfo_.weights.shape->GetStorageShape().GetDim(0) != qTsize) ||
                        (opParamInfo_.attenOut.shape->GetStorageShape().GetDim(0) != qTsize) ||
                        (opParamInfo_.valuesOut.shape->GetStorageShape().GetDim(0) != qTsize),
                    OP_LOGE(opName_,
                            "TND case input query, weights, sparse_indices, sparse_values dim 0 are %u, %u, %u "
                            "respectively, they must be same.",
                            qTsize,
                            opParamInfo_.weights.shape->GetStorageShape().GetDim(0),
                            opParamInfo_.attenOut.shape->GetStorageShape().GetDim(0),
                            opParamInfo_.valuesOut.shape->GetStorageShape().GetDim(0)),
                    return ge::GRAPH_FAILED);
    } else {
        // -----------------------check BatchSize-------------------
        // bSize_ 来源于query
        OP_CHECK_IF((opParamInfo_.weights.shape->GetStorageShape().GetDim(0) != bSize_) ||
                        ((opParamInfo_.blockTable.tensor != nullptr) &&
                         (opParamInfo_.blockTable.tensor->GetStorageShape().GetDim(0) != bSize_)) ||
                        ((opParamInfo_.actualSeqLengths.tensor != nullptr) &&
                         (opParamInfo_.actualSeqLengths.tensor->GetShapeSize() != bSize_)) ||
                        (opParamInfo_.attenOut.shape->GetStorageShape().GetDim(0) != bSize_) ||
                        (opParamInfo_.valuesOut.shape->GetStorageShape().GetDim(0) != bSize_),
                    OP_LOGE(opName_,
                            "BSND case input query, weight, actual_seq_lengths_key, block_table, sparse_indices, "
                            "sparse_values dim 0 must be same."),
                    return ge::GRAPH_FAILED);
        OP_CHECK_IF(
            (opParamInfo_.actualSeqLengthsQ.tensor != nullptr) &&
                (opParamInfo_.actualSeqLengthsQ.tensor->GetShapeSize() != bSize_),
            OP_LOGE(opName_,
                    "BSND case input query, actual_seq_lengths_query dim 0 are %u, %u respectively, they must be same",
                    bSize_,
                    opParamInfo_.actualSeqLengthsQ.tensor->GetShapeSize()),
            return ge::GRAPH_FAILED);
        // -----------------------check S1-------------------
        OP_CHECK_IF(
            (opParamInfo_.weights.shape->GetStorageShape().GetDim(1) != s1Size_) ||
                (opParamInfo_.attenOut.shape->GetStorageShape().GetDim(1) != s1Size_) ||
                (opParamInfo_.valuesOut.shape->GetStorageShape().GetDim(1) != s1Size_),
            OP_LOGE(
                opName_,
                "BSND case input query, weight, sparse_indices, sparse_values dim 1 are %u, %u, %u, they must be same.",
                s1Size_,
                opParamInfo_.weights.shape->GetStorageShape().GetDim(1),
                opParamInfo_.attenOut.shape->GetStorageShape().GetDim(1)),
            return ge::GRAPH_FAILED);
        queryWeightsN1Dim = DIM_IDX_TWO;
        outN2Dim = DIM_IDX_TWO;
    }
    // -----------------------check N1-------------------
    OP_CHECK_IF((opParamInfo_.weights.shape->GetStorageShape().GetDim(queryWeightsN1Dim) != n1Size_),
                OP_LOGE(opName_, "input query, weight shape dim N1 must be same."),
                return ge::GRAPH_FAILED);
    // -----------------------check D-------------------
    uint32_t keyDDim = kLayout_ == DataLayout::TND ? DIM_IDX_TWO : DIM_IDX_THREE;
    OP_CHECK_IF((opParamInfo_.key.shape->GetShape().GetDim(keyDDim) != headDim_),
                OP_LOGE(opName_, "input query, key shape last dim must be same."),
                return ge::GRAPH_FAILED);
    // -----------------------check N2-------------------
    OP_CHECK_IF((opParamInfo_.attenOut.shape->GetStorageShape().GetDim(outN2Dim) != n2Size_) ||
                    (opParamInfo_.valuesOut.shape->GetStorageShape().GetDim(outN2Dim) != n2Size_),
                OP_LOGE(opName_, "input query and output sparse_indices, sparse_values shape n2 dim must be same."),
                return ge::GRAPH_FAILED);
    // -----------------------check sparse_count-------------------
    OP_CHECK_IF(
        (opParamInfo_.attenOut.shape->GetStorageShape().GetDim(outN2Dim + 1) !=
         ((*opParamInfo_.sparseCount + *opParamInfo_.sparseBlockSize - 1) / *opParamInfo_.sparseBlockSize)) ||
            (opParamInfo_.valuesOut.shape->GetStorageShape().GetDim(outN2Dim + 1) !=
             ((*opParamInfo_.sparseCount + *opParamInfo_.sparseBlockSize - 1) / *opParamInfo_.sparseBlockSize)),
        OP_LOGE(
            opName_,
            "output sparse_indices, sparse_values shape last dim must be same as (sparse_count / sparse_block_size)."),
        return ge::GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

void LIInfoParser::GenerateInfo(LITilingInfo &liInfo)
{
    liInfo.opName = opName_;
    liInfo.platformInfo = platformInfo_;
    liInfo.opParamInfo = opParamInfo_;
    liInfo.socVersion = socVersion_;

    liInfo.bSize = bSize_;
    liInfo.n1Size = n1Size_;
    liInfo.n2Size = n2Size_;
    liInfo.s1Size = s1Size_;
    liInfo.s2Size = s2Size_;
    liInfo.gSize = gSize_;
    liInfo.kCacheStride = kCacheStride_;

    liInfo.inputQType = inputQType_;
    liInfo.inputKType = inputKType_;
    liInfo.outputType = outputType_;

    liInfo.blockSize = blockSize_;
    liInfo.maxBlockNumPerBatch = maxBlockNumPerBatch_;

    std::string layOutKeyStr(opParamInfo_.layOutKey);
    liInfo.pageAttentionFlag = layOutKeyStr == "PA_BSND" ? true : false;
    liInfo.sparseMode = *opParamInfo_.sparseMode;
    liInfo.sparseCount = *opParamInfo_.sparseCount;
    liInfo.preTokens = *opParamInfo_.preTokens;
    liInfo.nextTokens = *opParamInfo_.nextTokens;
    liInfo.returnValue = *opParamInfo_.returnValue;
    liInfo.sparseBlockSize = *opParamInfo_.sparseBlockSize;
    liInfo.sparseBlockMode = *opParamInfo_.sparseBlockMode;

    liInfo.inputQLayout = qLayout_;
    liInfo.inputKLayout = kLayout_;
}

ge::graphStatus LIInfoParser::ParseAndCheck(LITilingInfo &liInfo)
{
    if (ge::GRAPH_SUCCESS != GetOpName() || ge::GRAPH_SUCCESS != GetNpuInfo() || ge::GRAPH_SUCCESS != GetOpParaInfo() ||
        ge::GRAPH_SUCCESS != CheckRequiredParaExistence()) {
        return ge::GRAPH_FAILED;
    }

    if (ge::GRAPH_SUCCESS != GetAndCheckInOutDataType() || ge::GRAPH_SUCCESS != GetQueryKeyAndOutLayout() ||
        ge::GRAPH_SUCCESS != GetAndCheckOptionalInput()) {
        return ge::GRAPH_FAILED;
    }

    if (ge::GRAPH_SUCCESS != CheckShapeDim() || ge::GRAPH_SUCCESS != GetN1Size() ||
        ge::GRAPH_SUCCESS != GetAndCheckN2Size() || ge::GRAPH_SUCCESS != GetGSize()) {
        return ge::GRAPH_FAILED;
    }

    if (ge::GRAPH_SUCCESS != GetBatchSize() || ge::GRAPH_SUCCESS != GetS1Size() || ge::GRAPH_SUCCESS != GetHeadDim() ||
        ge::GRAPH_SUCCESS != GetS2Size()) {
        return ge::GRAPH_FAILED;
    }

    if (ge::GRAPH_SUCCESS != GetKeyStride()) {
        return ge::GRAPH_FAILED;
    }

    if (ge::GRAPH_SUCCESS != ValidateInputShapesMatch()) {
        return ge::GRAPH_FAILED;
    }

    GenerateInfo(liInfo);

    return ge::GRAPH_SUCCESS;
}

