static ge::graphStatus TilingPrepareForLightningIndexerEnhance(gert::TilingParseContext * /* context */)
{
    return ge::GRAPH_SUCCESS;
}

// --------------------------LightningIndexerEnhanceTiling类成员函数定义-----------------------
ge::graphStatus LightningIndexerEnhanceTiling::DoTiling(LITilingInfo *tilingInfo)
{
    // -------------set blockdim-----------------
    auto ascendcPlatform = platform_ascendc::PlatformAscendC(tilingInfo->platformInfo);
    uint32_t aivNum = ascendcPlatform.GetCoreNumAiv();
    uint32_t aicNum = ascendcPlatform.GetCoreNumAic();
    uint32_t blockDim = ascendcPlatform.CalcTschBlockDim(aivNum, aicNum, aivNum);
    context_->SetBlockDim(blockDim);

    // -------------set workspacesize-----------------
    constexpr uint32_t MM1_RES_ELEM_SIZE = 4; // 4: fp32
    constexpr uint32_t DOUBLE_BUFFER = 2; // 双Buffer
    constexpr uint32_t M_BASE_SIZE = 512; // m轴基本块大小
    constexpr uint32_t S2_BASE_SIZE = 512; // S2轴基本块大小
    constexpr uint32_t V1_RES_ELEM_SIZE = 4; // 4: int32
    constexpr uint32_t V1_RES_ELEM_TYPE = 2; // 保留Index和Value 2种数据
    constexpr uint32_t V1_DECODE_PARAM_ELEM_SIZE = 8; // 8: int64
    constexpr uint32_t V1_DECODE_PARAM_NUM = 16; // Decode参数个数
    constexpr uint32_t V1_DECODE_DATA_NUM = 2; // Decode每个核需要存储头和尾部两块数据
    constexpr uint32_t TOPK_MAX_SIZE = 2048; // TopK选取个数
    constexpr uint32_t S1_BASE_SIZE_8 = 8; // S1轴基本块大小-默认值

    uint32_t s1BaseSize = S1_BASE_SIZE_8;
    uint32_t s1Size = tilingInfo->s1Size;

    bool isAverageLD = false; // 是否启用均分LD优化

    if (tilingInfo->sparseBlockSize == 1 && tilingInfo->inputQLayout == DataLayout::TND &&
        tilingInfo->inputKLayout == DataLayout::BnBsND) {
        constexpr uint32_t S1_BASE_SIZE_2 = 2; // S1轴基本块大小-负载均衡
        constexpr uint32_t S1_BASE_SIZE_4 = 4; // S1轴基本块大小-负载均衡
        uint32_t useAicNum =
            (s1Size + S1_BASE_SIZE_8 - 1) / S1_BASE_SIZE_8 * (tilingInfo->s2Size + S2_BASE_SIZE - 1) / S2_BASE_SIZE;
        bool useFullAic = useAicNum >= aicNum;
        s1BaseSize = useFullAic
                         ? s1BaseSize
                         : (s1Size <= S1_BASE_SIZE_4 ? S1_BASE_SIZE_2
                                                     : (s1Size <= S1_BASE_SIZE_8 ? S1_BASE_SIZE_4 : S1_BASE_SIZE_8));
    }

    uint32_t workspaceSize = ascendcPlatform.GetLibApiWorkSpaceSize();
    // 主流程需Workspace大小
    uint32_t mm1ResSize = M_BASE_SIZE * S2_BASE_SIZE;
    workspaceSize += mm1ResSize * MM1_RES_ELEM_SIZE * DOUBLE_BUFFER * aicNum;
    // Decode流程(LD)需要Workspace大小
    // 临时存储Decode中间结果大小: 2(头/尾)*8(s1Base)*2(idx/value)*2048(K)*sizeof(int32)*24=6M
    workspaceSize += V1_DECODE_DATA_NUM * s1BaseSize * V1_RES_ELEM_TYPE * TOPK_MAX_SIZE * V1_RES_ELEM_SIZE * aicNum;
    // 临时存储Decode中间参数信息大小: 2(头/尾)*8(s1Base)*16(paramNum)*sizeof(int64_t)*24=48k
    workspaceSize += V1_DECODE_DATA_NUM * s1BaseSize * V1_DECODE_PARAM_NUM * V1_DECODE_PARAM_ELEM_SIZE * aicNum;
    size_t *workSpaces = context_->GetWorkspaceSizes(1);
    workSpaces[0] = workspaceSize;

    // -------------set tilingdata-----------------
    tilingData_.set_bSize(tilingInfo->bSize);
    tilingData_.set_s2Size(tilingInfo->s2Size);
    tilingData_.set_s1Size(tilingInfo->s1Size);
    tilingData_.set_sparseCount(tilingInfo->sparseCount);
    tilingData_.set_gSize(tilingInfo->gSize);
    tilingData_.set_blockSize(tilingInfo->blockSize);
    tilingData_.set_maxBlockNumPerBatch(tilingInfo->maxBlockNumPerBatch);
    tilingData_.set_sparseMode(tilingInfo->sparseMode);
    tilingData_.set_preTokens(tilingInfo->preTokens);
    tilingData_.set_nextTokens(tilingInfo->nextTokens);
    tilingData_.set_returnValue(tilingInfo->returnValue);
    tilingData_.set_sparseBlockSize(tilingInfo->sparseBlockSize);
    tilingData_.set_sparseBlockMode(tilingInfo->sparseBlockMode);
    tilingData_.set_kCacheStride(tilingInfo->kCacheStride);
    tilingData_.set_s1BaseSize(s1BaseSize);
    tilingData_.set_isAverageLD(isAverageLD);

    tilingData_.set_usedCoreNum(blockDim);
    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());

    // -------------set tilingkey-----------------
    // DT_Q, DT_KV, DT_OUT, PAGE_ATTENTION, FLASH_DECODE, LAYOUT_T, KV_LAYOUT_T
    uint32_t inputQType = static_cast<uint32_t>(tilingInfo->inputQType);
    uint32_t inputKType = static_cast<uint32_t>(tilingInfo->inputKType);
    uint32_t outputType = static_cast<uint32_t>(tilingInfo->outputType);
    uint32_t pageAttentionFlag = static_cast<uint32_t>(tilingInfo->pageAttentionFlag);
    uint32_t inputQLayout = static_cast<uint32_t>(tilingInfo->inputQLayout);
    uint32_t inputKLayout = static_cast<uint32_t>(tilingInfo->inputKLayout);
    uint64_t tilingKey =
        GET_TPL_TILING_KEY(inputQType, inputKType, outputType, pageAttentionFlag, inputQLayout, inputKLayout);
    context_->SetTilingKey(tilingKey);

    return ge::GRAPH_SUCCESS;
}

// --------------------------Tiling函数定义---------------------------
ge::graphStatus TilingForLightningIndexerEnhance(gert::TilingContext *context)
{
    OP_CHECK_IF(context == nullptr,
                OPS_REPORT_VECTOR_INNER_ERR("LightningIndexerEnhance", "Tiling context is null."),
                return ge::GRAPH_FAILED);
    LITilingInfo liInfo;
    LIInfoParser LIInfoParser(context);
    if (LIInfoParser.ParseAndCheck(liInfo) != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }
    LightningIndexerEnhanceTiling liTiling(context);
    return liTiling.DoTiling(&liInfo);
}

